input.command:
ssh -i ~/.ssh/soulpilates_deploy root@51.79.226.200 bash -s <<'EOF' 2>&1
URI=$(docker exec soulpilates-prod-backend printenv MongoDbSettings__ConnectionString)
DB=$(docker exec soulpilates-prod-backend printenv MongoDbSettings__DatabaseName)
docker exec -e URI="$URI" -e DBN="$DB" soulpilates-prod-mongo mongosh --quiet --eval '
  var conn = new Mongo(process.env.URI);
  var db = conn.getDB(process.env.DBN);
  var sessIds = db.CalendarSessions.find({InstructorId: ObjectId("6a54ad0f1d3c92cadac61b9e"), StartTime:{$gte: ISODate("2026-08-01T00:00:00Z"), $lt: ISODate("2026-09-01T00:00:00Z")}},{_id:1}).toArray().map(s=>s._id);

  var pkgAtt = db.Attendances.find({CalendarSessionId:{$in:sessIds}, PaymentMethod:"PACKAGE_CREDIT"}).toArray();
  var missing = 0, pkgRevenue = 0;
  pkgAtt.forEach(a => {
    var pkg = db.ClientPackages.findOne({_id: a.PackageInstanceId});
    if (!pkg || pkg.FractionalValuePerClass == null) { missing++; return; }
    pkgRevenue += parseFloat(pkg.FractionalValuePerClass.toString());
  });
  print("PACKAGE_CREDIT attendances: "+pkgAtt.length+", missing package/value: "+missing);
  print("PACKAGE_CREDIT revenue total: "+pkgRevenue);

  var direct = db.Attendances.aggregate([
    {$match:{CalendarSessionId:{$in:sessIds}, PaymentMethod:{$ne:"PACKAGE_CREDIT"}}},
    {$group:{_id:null, total:{$sum:"$AmountPaid"}, count:{$sum:1}}}
  ]).toArray();
  print("Direct-pay attendances/total: ");
  printjson(direct);

  print("GRAND TOTAL CLASS REVENUE (VND): " + (pkgRevenue + parseFloat(direct[0].total.toString())));
'
EOF

ssh -i ~/.ssh/soulpilates_deploy root@51.79.226.200 bash -s <<'EOF' 2>&1
URI=$(docker exec soulpilates-prod-backend printenv MongoDbSettings__ConnectionString)
DB=$(docker exec soulpilates-prod-backend printenv MongoDbSettings__DatabaseName)
docker exec -e URI="$URI" -e DBN="$DB" soulpilates-prod-mongo mongosh --quiet --eval '
  var conn = new Mongo(process.env.URI);
  var db = conn.getDB(process.env.DBN);
  var sessions = db.CalendarSessions.find({InstructorId: ObjectId("6a54ad0f1d3c92cadac61b9e"), StartTime:{$gte: ISODate("2026-08-01T00:00:00Z"), $lt: ISODate("2026-09-01T00:00:00Z")}},{_id:1, Format:1, ClassName:1, StartTime:1}).toArray();

  var perSession = db.Attendances.aggregate([
    {$match:{CalendarSessionId:{$in: sessions.map(s=>s._id)}, CountsTowardsCommission:true}},
    {$group:{_id:"$CalendarSessionId", headcount:{$sum:1}}}
  ]).toArray();
  var hcMap = {};
  perSession.forEach(p => hcMap[p._id.toString()] = p.headcount);

  var rows = sessions.map(s => ({
    id: s._id.toString(),
    date: s.StartTime.toISOString().slice(0,10),
    className: s.ClassName,
    format: s.Format,
    headcount: hcMap[s._id.toString()] || 0
  })).filter(r => r.headcount > 0).sort((a,b)=> a.date.localeCompare(b.date));

  print("--- per-class headcount (format) ---");
  rows.forEach(r => print(r.date+"  "+r.format.padEnd(7)+"  hc="+r.headcount+"  "+r.className));

  print("--- headcount distribution by format ---");
  var dist = {};
  rows.forEach(r => { var k=r.format+"_"+r.headcount; dist[k]=(dist[k]||0)+1; });
  printjson(dist);

  print("--- max headcount overall ---");
  print(Math.max(...rows.map(r=>r.headcount)));
'
EOF

