10	namespace SoulPilates.Services;
11	
12	public class WalletService : IWalletService
13	{
14	    private readonly IMongoCollection<ClientPackage> _clientPackages;
15	    private readonly IMongoCollection<PackageLedgerLog> _ledger;
16	    private readonly IMongoCollection<PackageFreeze> _freezes;
17	    private readonly IMongoCollection<Product> _products;
18	    private readonly IMongoCollection<CalendarSession> _sessions;
19	    private readonly IMongoCollection<Attendance> _attendances;
20	    private readonly IAuditLogger _auditLogger;
21	
22	    public WalletService(MongoDbContext dbContext, IAuditLogger auditLogger)
23	    {
24	        _clientPackages = dbContext.GetCollection<ClientPackage>("ClientPackages");
25	        _ledger = dbContext.GetCollection<PackageLedgerLog>("PackageLedgerLogs");
26	        _freezes = dbContext.GetCollection<PackageFreeze>("PackageFreezes");
27	        _products = dbContext.GetCollection<Product>("Products");
28	        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
29	        _attendances = dbContext.GetCollection<Attendance>("Attendances");
30	        _auditLogger = auditLogger;
31	    }
32	
33	    /// <summary>
34	    /// Per-package session/credit history for the admin client profile: every ledger
35	    /// movement on a package (class deductions, refunds, manual adjustments) resolved
36	    /// to the class name/date/instructor, so staff can vet usage vs remaining credits.
37	    /// </summary>
38	    public async Task<object?> GetPackageSessionHistoryAsync(string packageId)
39	    {
40	        var pkg = await _clientPackages.Find(p => p.Id == packageId).FirstOrDefaultAsync();
41	        if (pkg == null) return null;
42	
43	        var entries = await _ledger.Find(l => l.PackageInstanceId == packageId)
44	            .SortByDescending(l => l.Timestamp).ToListAsync();
45	
46	        var rows = new List<object>();
47	        foreach (var e in entries)
48	        {
49	            string? className = null; DateTime? sessionDate = null; string? instructor = null;
50	            if (!string.IsNullOrWhiteSpace(e.ReferenceAttendanceId))
51	            {
52	                var att = await _attendances.Find(a => a.Id == e.ReferenceAttendanceId).FirstOrDefaultAsync();
53	                if (att != null && !string.IsNullOrWhiteSpace(att.CalendarSessionId))
54	                {
55	                    var s = await _sessions.Find(x => x.Id == att.CalendarSessionId).FirstOrDefaultAsync();
56	                    if (s != null) { className = s.ClassName; sessionDate = s.StartTime; instructor = s.InstructorName; }
57	                }
58	            }
59	            rows.Add(new { timestamp = e.Timestamp, actionType = e.ActionType, amount = e.Amount, className, sessionDate, instructor, note = e.Notes });
60	        }
61	
62	        return new
63	        {
64	            packageId = pkg.Id,
65	            productName = $"{pkg.Format} package \u00b7 {pkg.TotalCredits} credits",
66	            totalCredits = pkg.TotalCredits,
67	            creditsUsed = pkg.CreditsUsed,
68	            creditsRemaining = pkg.CreditsRemaining,
69	            entries = rows,
70	        };
71	    }
72	
73	    public async Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
74	    {
75	        // A package with ExpiryDate == null never expires; include it unconditionally.
76	        // A package with a concrete ExpiryDate must still be in the future.
77	        var noExpiry  = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
78	        var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
79	        var expiryOk  = Builders<ClientPackage>.Filter.Or(noExpiry, notExpired);
80	
81	        // MAT is a sub-type of group class. A MAT session can be paid with either a
82	        // MAT-specific package (preferred — consumed first) or a generic GROUP package
83	        // (fallback). Exact matches on other formats (PRIVATE, DUO, FREELANCE) are kept
84	        // strict so packages are never cross-consumed across incompatible class types.
85	        var upper = (format ?? "").ToUpperInvariant();
86	        var formatFilter = upper == "MAT"
87	            ? Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" })
88	            : Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper);
89	
90	        var filter = Builders<ClientPackage>.Filter.And(
91	            Builders<ClientPackage>.Filter.Eq(p => p.ClientId, clientId),
92	            formatFilter,
93	            // Include LOW_BALANCE alongside ACTIVE: a package with ≤2 credits
94	            // remaining is still fully usable — excluding it would hide the
95	            // PACKAGE_CREDIT option at checkout even though credits exist.
96	            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
97	            Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0),
98	            expiryOk
99	        );
100	
101	        // For MAT sessions: sort MAT-specific packages before GROUP fallbacks so the
102	        // specialised wallet is always consumed first. Within each bucket sort by
103	        // earliest expiry (FIFO across wallets of the same type).
104	        var packages = await _clientPackages.Find(filter).ToListAsync();
105	        if (upper == "MAT")
106	        {
107	            packages = packages
108	                .OrderBy(p => p.Format == "MAT" ? 0 : 1)
109	                .ThenBy(p => p.ExpiryDate ?? DateTime.MaxValue)
110	                .ToList();
111	        }
112	        else
113	        {
114	            packages = packages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).ToList();
115	        }
116	        return packages;
117	    }
118	
119	    public async Task<IEnumerable<ClientPackage>> GetAllPackagesForClientAsync(string clientId)
120	    {
121	        return await _clientPackages.Find(p => p.ClientId == clientId)
122	            .SortByDescending(p => p.ActivationDate)
123	            .ToListAsync();
124	    }
125	
126	    public async Task<IEnumerable<ClientPackage>> GetAllActivePackagesAsync()
127	    {
128	        var now = DateTime.UtcNow;
129	        var f = Builders<ClientPackage>.Filter;
130	        var filter = f.And(
131	            f.Gt(p => p.CreditsRemaining, 0),
132	            f.Nin(p => p.Status, new[] { "EXPIRED", "CANCELLED", "DEPLETED" }),
133	            f.Or(
134	                f.Eq(p => p.ExpiryDate, (DateTime?)null),
135	                f.Gt(p => p.ExpiryDate, now)));
136	        return await _clientPackages.Find(filter)
137	            .SortBy(p => p.ExpiryDate)
138	            .ToListAsync();
139	    }
140	
141	    /// <summary>
142	    /// Deducts one credit/slot from the oldest-expiring active <see cref="ClientPackage"/> of the
143	    /// requested <paramref name="format"/> for the given client.
144	    /// Accepted formats: <c>"GROUP"</c>, <c>"PRIVATE"</c>, and (since P3-S13) <c>"FREELANCE"</c> —
145	    /// the same FIFO + low-balance + completed lifecycle applies regardless of format.
146	    /// <para>
147	    /// <paramref name="quantity"/> (Issue #3, default 1) deducts multiple credits in one call —
148	    /// e.g. a group-class multi-seat reservation. Credits are taken FIFO across the customer's
149	    /// active wallets of the format; the deduction may therefore span more than one wallet.
150	    /// Returns <c>false</c> if the customer has fewer than <paramref name="quantity"/> credits
151	    /// total — in that case no partial deduction is applied (atomic at the request level).
152	    /// </para>
153	    /// </summary>
154	    public async Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1)
155	    {
156	        if (quantity <= 0) quantity = 1;
157	
158	        var activePackages = (await GetActivePackagesForClientAsync(clientId, format)).ToList();
159	        var totalAvailable = activePackages.Sum(p => p.CreditsRemaining);
160	        if (totalAvailable < quantity) return false;
161	
162	        var remainingToDeduct = quantity;
163	        foreach (var pkg in activePackages)
164	        {
165	            if (remainingToDeduct <= 0) break;
166	
167	            var take = Math.Min(pkg.CreditsRemaining, remainingToDeduct);
168	            pkg.CreditsRemaining -= take;
169	            pkg.CreditsUsed += take;
170	
171	            if (pkg.CreditsRemaining == 0) pkg.Status = "COMPLETED";
172	            else if (pkg.CreditsRemaining <= 2) pkg.Status = "LOW_BALANCE";
173	
174	            await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
175	
176	            var log = new PackageLedgerLog
177	            {
178	                PackageInstanceId = pkg.Id ?? "",
179	                ActionType = "DEDUCTION",
180	                Amount = -take,
181	                ReferenceAttendanceId = referenceAttendanceId
182	            };
183	            await _ledger.InsertOneAsync(log);
184	
185	            remainingToDeduct -= take;
186	        }
187	
188	        return true;
189	    }
190	
191	    /// <summary>
192	    /// Refunds <paramref name="quantity"/> credits (default 1) back to the named
193	    /// <see cref="ClientPackage"/>. For multi-seat group cancellations the caller may need
194	    /// to invoke this once per source wallet if the original deduction spanned multiple
195	    /// wallets; the ledger log preserves which wallet each unit came from.
196	    /// </summary>
197	    public async Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1)
198	    {
199	        if (quantity <= 0) quantity = 1;
200	
201	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
202	        if (pkg == null) return false;
203	
204	        pkg.CreditsRemaining += quantity;
205	        pkg.CreditsUsed -= quantity;
206	        if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative
207	
208	        if (pkg.Status == "COMPLETED" && pkg.CreditsRemaining > 0)
209	        {
210	            pkg.Status = "ACTIVE";
211	        }
212	
213	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
214	
215	        var log = new PackageLedgerLog
216	        {
217	            PackageInstanceId = pkg.Id ?? "",
218	            ActionType = "REFUND",
219	            Amount = quantity,
220	            ReferenceAttendanceId = referenceAttendanceId
221	        };
222	        await _ledger.InsertOneAsync(log);
223	
224	        return true;
225	    }
226	
227	    /// <summary>
228	    /// Multi-wallet refund driven by the ledger. Walks every <c>DEDUCTION</c> row
229	    /// tagged with <paramref name="attendanceId"/> and reverses each one against its
230	    /// originating wallet — necessary because a single PACKAGE_CREDIT booking can
231	    /// span more than one <see cref="ClientPackage"/> when FIFO crosses a wallet
232	    /// boundary (e.g. 2-seat group class drawing 1 credit from each of two wallets).
233	    /// Idempotent: a second call after every DEDUCTION has been matched by a REFUND
234	    /// of equal or greater magnitude is a no-op (returns <c>false</c>).
235	    /// </summary>
236	    public async Task<bool> RefundCreditByAttendanceAsync(string attendanceId)
237	    {
238	        var (refundedAny, _) = await RefundCreditByAttendanceWithTrailAsync(attendanceId);
239	        return refundedAny;
240	    }
241	
242	    /// <summary>
243	    /// SPM-108 — ledger-driven refund that also reports whether ANY ledger trail
244	    /// (deduction or prior refund) exists for this attendance.
245	    /// <para>
246	    /// Returns <c>(refunded, hasLedgerTrail)</c>:
247	    /// <list type="bullet">
248	    ///   <item><c>refunded</c> — true when at least one credit was actually
249	    ///   returned by THIS call (i.e. a wallet still had a net-negative position).</item>
250	    ///   <item><c>hasLedgerTrail</c> — true when one or more ledger rows reference
251	    ///   this attendance, regardless of net. Callers use this to decide whether the
252	    ///   legacy non-ledger <see cref="RefundCreditAsync"/> fallback is safe: a trail
253	    ///   exists means this booking has already been accounted for in the ledger, so
254	    ///   the blind +1 fallback MUST NOT run (it would phantom-refund a credit, e.g.
255	    ///   the owner-reported 1 -> 2 on a re-cancel where the net was already 0).</item>
256	    /// </list>
257	    /// </para>
258	    /// </summary>
259	    public async Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId)
260	    {
261	        if (string.IsNullOrWhiteSpace(attendanceId)) return (false, false);
262	
263	        var entries = await _ledger
264	            .Find(l => l.ReferenceAttendanceId == attendanceId)
265	            .ToListAsync();
266	        if (entries.Count == 0) return (false, false);
267	
268	        // Net per-wallet position: sum of all ledger rows. Positive/zero net means the
269	        // wallet has already been refunded; we only want to refund where net < 0
270	        // (i.e. credits still consumed by this attendance). This is what makes the
271	        // refund idempotent — a second call after a full refund finds no net-negative
272	        // wallet and returns refunded=false WITHOUT writing another REFUND row.
273	        var netByWallet = entries
274	            .GroupBy(e => e.PackageInstanceId)
275	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
276	            .Where(x => x.Net < 0)
277	            .ToList();
278	
279	        if (netByWallet.Count == 0) return (false, true); // trail exists, nothing left to refund
280	
281	        var refundedAny = false;
282	        foreach (var w in netByWallet)
283	        {
284	            var qty = -w.Net; // flip the negative net into a positive refund quantity
285	            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
286	            refundedAny |= ok;
287	        }
288	        return (refundedAny, true);
289	    }
290	
291	    /// <summary>
292	    /// SPM-110 — refund AT MOST <paramref name="seatsToRefund"/> credits for the attendance,
293	    /// for the per-seat cancel of a multi-seat group booking. Mirrors the idempotent,
294	    /// over-refund-safe net-by-wallet logic of <see cref="RefundCreditByAttendanceWithTrailAsync"/>
295	    /// but caps the total returned at the requested seat count.
296	    /// </summary>
297	    public async Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund)
298	    {
299	        if (string.IsNullOrWhiteSpace(attendanceId)) return (0, false);
300	        if (seatsToRefund <= 0) return (0, false);
301	
302	        var entries = await _ledger
303	            .Find(l => l.ReferenceAttendanceId == attendanceId)
304	            .ToListAsync();
305	        if (entries.Count == 0) return (0, false);
306	
307	        // Per-wallet net position, identical bookkeeping to the full-cancel path:
308	        // only wallets still net-negative have credits consumed by this attendance
309	        // that can be returned. This is what keeps the partial refund idempotent —
310	        // a second call after seats were already returned sees a smaller net and
311	        // will not over-refund.
312	        var netByWallet = entries
313	            .GroupBy(e => e.PackageInstanceId)
314	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
315	            .Where(x => x.Net < 0)
316	            .ToList();
317	
318	        if (netByWallet.Count == 0) return (0, true); // trail exists, nothing left to refund
319	
320	        var remainingToRefund = seatsToRefund;
321	        var refundedCount = 0;
322	        foreach (var w in netByWallet)
323	        {
324	            if (remainingToRefund <= 0) break;
325	
326	            // Cap this wallet's refund at the smaller of (credits it still owes) and
327	            // (seats we have left to return) so we never exceed the requested count.
328	            var available = -w.Net; // positive credits still consumed on this wallet
329	            var qty = Math.Min(available, remainingToRefund);
330	            if (qty <= 0) continue;
331	
332	            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
333	            if (ok)
334	            {
335	                refundedCount += qty;
336	                remainingToRefund -= qty;
337	            }
338	        }
339	
340	        return (refundedCount, true);
341	    }
342	
343	    /// <summary>
344	    /// SPM-110 — neutralise the ledger net for up to <paramref name="seatsForfeited"/>
345	    /// seats of a late-cancelled PACKAGE_CREDIT booking WITHOUT touching wallet balances
346	    /// (the credits stay consumed — that's the forfeit). Writes ledger-only FORFEIT rows
347	    /// so the per-wallet net reflects the seats still genuinely owed, preventing a later
348	    /// cancel of the booking's remaining seats from over-refunding the forfeited ones.
349	    /// </summary>
350	    public async Task<int> ForfeitCreditByAttendanceAsync(string attendanceId, int seatsForfeited)
351	    {
352	        if (string.IsNullOrWhiteSpace(attendanceId)) return 0;
353	        if (seatsForfeited <= 0) return 0;
354	
355	        var entries = await _ledger
356	            .Find(l => l.ReferenceAttendanceId == attendanceId)
357	            .ToListAsync();
358	        if (entries.Count == 0) return 0;
359	
360	        var netByWallet = entries
361	            .GroupBy(e => e.PackageInstanceId)
362	            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
363	            .Where(x => x.Net < 0)
364	            .ToList();
365	
366	        if (netByWallet.Count == 0) return 0;
367	
368	        var remaining = seatsForfeited;
369	        var forfeited = 0;
370	        foreach (var w in netByWallet)
371	        {
372	            if (remaining <= 0) break;
373	
374	            var available = -w.Net; // credits still net-consumed on this wallet
375	            var qty = Math.Min(available, remaining);
376	            if (qty <= 0) continue;
377	
378	            // Ledger-only positive row: raises the net toward zero so these seats can't
379	            // be refunded later, but deliberately does NOT modify the ClientPackage
380	            // (the customer forfeited these credits by cancelling late).
381	            var log = new PackageLedgerLog
382	            {
383	                PackageInstanceId = w.PackageInstanceId,
384	                ActionType = "FORFEIT",
385	                Amount = qty,
386	                ReferenceAttendanceId = attendanceId,
387	                Notes = "Late-cancel seat forfeit (SPM-110) — credit not returned to wallet.",
388	            };
389	            await _ledger.InsertOneAsync(log);
390	
391	            forfeited += qty;
392	            remaining -= qty;
393	        }
394	
395	        return forfeited;
396	    }
