398	    public async Task ExpireOldPackagesAsync()
399	    {
400	        // Only expire packages that have a concrete ExpiryDate in the past.
401	        // Packages with ExpiryDate == null are open-ended and must never be swept.
402	        var filter = Builders<ClientPackage>.Filter.And(
403	            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
404	            Builders<ClientPackage>.Filter.Ne(p => p.ExpiryDate, (DateTime?)null),
405	            Builders<ClientPackage>.Filter.Lt(p => p.ExpiryDate, DateTime.UtcNow)
406	        );
407	
408	        var update = Builders<ClientPackage>.Update.Set(p => p.Status, "EXPIRED");
409	        await _clientPackages.UpdateManyAsync(filter, update);
410	    }
