412	    public async Task FreezePackageAsync(string packageInstanceId, DateTime freezeStart, int daysToFreeze, string? reason)
413	    {
414	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
415	        if (pkg == null) throw new Exception("Package not found.");
416	
417	        // Extend expiry by freeze duration
418	        if (pkg.ExpiryDate.HasValue)
419	        {
420	            pkg.ExpiryDate = pkg.ExpiryDate.Value.AddDays(daysToFreeze);
421	        }
422	        pkg.Status = "FROZEN";
423	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
424	
425	        // Log the freeze
426	        var freeze = new PackageFreeze
427	        {
428	            PackageInstanceId = packageInstanceId,
429	            FreezeStartDate = freezeStart,
430	            FreezeEndDate = freezeStart.AddDays(daysToFreeze),
431	            DaysAddedToExpiry = daysToFreeze,
432	            Reason = reason
433	        };
434	        await _freezes.InsertOneAsync(freeze);
435	    }
436	
437	    /// <summary>
438	    /// Manually adjust credits on a specific <see cref="ClientPackage"/> by a signed
439	    /// <paramref name="delta"/>. Positive delta adds credits (gift / compassionate refund);
440	    /// negative removes them (manual forfeit).
441	    /// <para>
442	    /// When adding credits, <see cref="ClientPackage.TotalCredits"/> is increased by the
443	    /// same amount to keep the invariant <c>TotalCredits = CreditsUsed + CreditsRemaining</c>
444	    /// consistent and the credit-bar percentage meaningful.
445	    /// </para>
446	    /// <para>
447	    /// Two audit trails are written on success:
448	    /// <list type="bullet">
449	    ///   <item>A <see cref="PackageLedgerLog"/> row with <c>ActionType = "MANUAL_ADJUSTMENT"</c>
450	    ///   and the reason in <c>Notes</c> — this is the financial ledger record.</item>
451	    ///   <item>An <see cref="AuditLog"/> row via <see cref="IAuditLogger"/> capturing actor,
452	    ///   before/after credit snapshots, IP and correlation-id — this is the governance record.</item>
453	    /// </list>
454	    /// </para>
455	    /// </summary>
456	    public async Task<bool> AdjustCreditAsync(string packageInstanceId, int delta, string reason)
457	    {
458	        if (delta == 0) return false;
459	
460	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
461	        if (pkg == null) return false;
462	
463	        // Guard: adjustments on frozen or expired packages are not allowed.
464	        // The admin should unfreeze (or extend expiry) first — otherwise the
465	        // status-recalculation logic below would silently overwrite FROZEN →
466	        // COMPLETED or leave stranded credits on an EXPIRED package that won't
467	        // appear in active-wallet queries.
468	        if (pkg.Status is "FROZEN" or "EXPIRED") return false;
469	
470	        // Guard: can't remove more credits than the package currently holds.
471	        if (delta < 0 && pkg.CreditsRemaining < Math.Abs(delta)) return false;
472	
473	        // Capture before-state for audit.
474	        var beforeRemaining = pkg.CreditsRemaining;
475	        var beforeUsed = pkg.CreditsUsed;
476	        var beforeTotal = pkg.TotalCredits;
477	        var beforeStatus = pkg.Status;
478	
479	        // Apply the adjustment.
480	        pkg.CreditsRemaining += delta;
481	        if (delta > 0)
482	        {
483	            // Adding credits back: reduce CreditsUsed (we're returning consumed
484	            // credits, not expanding the package capacity). TotalCredits must
485	            // stay at the original product capacity so renewals, the credit bar,
486	            // and the wallet label always reflect the purchased package size.
487	            pkg.CreditsUsed -= delta;
488	            if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative
489	        }
490	        else
491	        {
492	            // Removing credits: reflect the removal in CreditsUsed.
493	            pkg.CreditsUsed += Math.Abs(delta);
494	        }
495	
496	        // Recalculate status — mirrors the same rules as DeductCreditAsync.
497	        if (pkg.CreditsRemaining == 0)
498	            pkg.Status = "COMPLETED";
499	        else if (pkg.CreditsRemaining <= 2)
500	            pkg.Status = "LOW_BALANCE";
501	        else if (pkg.Status is "COMPLETED" or "LOW_BALANCE")
502	            pkg.Status = "ACTIVE";
503	
504	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
505	
506	        // ── Ledger row ────────────────────────────────────────────────────
507	        // ActionType = "MANUAL_ADJUSTMENT" (a new enum value in the comment
508	        // set of PackageLedgerLog). Notes carries the admin's stated reason.
509	        var log = new PackageLedgerLog
510	        {
511	            PackageInstanceId = pkg.Id ?? "",
512	            ActionType = "MANUAL_ADJUSTMENT",
513	            Amount = delta,
514	            ReferenceAttendanceId = null,
515	            Notes = reason,
516	        };
517	        await _ledger.InsertOneAsync(log);
518	
519	        // ── Governance audit row ──────────────────────────────────────────
520	        // Non-throwing per the IAuditLogger contract — business transaction
521	        // is never rolled back if audit storage fails.
522	        await _auditLogger.LogAsync(
523	            action: "MANUAL_CREDIT_ADJUSTMENT",
524	            entityType: "ClientPackage",
525	            entityId: pkg.Id ?? "",
526	            entityLabel: $"{pkg.Format} package · {beforeTotal} credits",
527	            before: new
528	            {
529	                creditsRemaining = beforeRemaining,
530	                creditsUsed = beforeUsed,
531	                totalCredits = beforeTotal,
532	                status = beforeStatus,
533	            },
534	            after: new
535	            {
536	                creditsRemaining = pkg.CreditsRemaining,
537	                creditsUsed = pkg.CreditsUsed,
538	                totalCredits = pkg.TotalCredits,
539	                status = pkg.Status,
540	            },
541	            metadata: new { reason, delta });
542	
543	        return true;
544	    }
545	
546	    /// <summary>
547	    /// Admin operation: set or clear the expiry date on a specific
548	    /// <see cref="ClientPackage"/>. Pass <c>null</c> to make the package
549	    /// open-ended (never expires); pass a future <see cref="DateTime"/> to
550	    /// set or update the deadline.
551	    /// <para>
552	    /// Both the before- and after-state are written to the governance audit log.
553	    /// The package status is re-evaluated: if the new date is in the past the
554	    /// status flips to <c>EXPIRED</c>; if it is in the future (or null) and the
555	    /// package was previously <c>EXPIRED</c> due to date alone, it reverts to
556	    /// <c>ACTIVE</c> or <c>LOW_BALANCE</c>.
557	    /// </para>
558	    /// </summary>
559	    public async Task<bool> SetPackageExpiryAsync(string packageInstanceId, DateTime? newExpiry, string reason)
560	    {
561	        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
562	        if (pkg == null) return false;
563	
564	        var oldExpiry  = pkg.ExpiryDate;
565	        var oldStatus  = pkg.Status;
566	
567	        pkg.ExpiryDate = newExpiry;
568	
569	        // Re-evaluate status only when the package is not FROZEN/COMPLETED.
570	        // EXPIRED → flip back to active if the new date is future or null.
571	        if (pkg.Status is "EXPIRED")
572	        {
573	            if (newExpiry == null || newExpiry > DateTime.UtcNow)
574	                pkg.Status = pkg.CreditsRemaining <= 2 ? "LOW_BALANCE" : "ACTIVE";
575	        }
576	        else if (pkg.Status is "ACTIVE" or "LOW_BALANCE")
577	        {
578	            // If admin deliberately sets a past date, mark as expired immediately.
579	            if (newExpiry.HasValue && newExpiry.Value <= DateTime.UtcNow)
580	                pkg.Status = "EXPIRED";
581	        }
582	
583	        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);
584	
585	        await _auditLogger.LogAsync(
586	            action: "EXPIRY_DATE_CHANGED",
587	            entityType: "ClientPackage",
588	            entityId: pkg.Id ?? "",
589	            entityLabel: $"{pkg.Format} package · {pkg.TotalCredits} credits",
590	            before: new { expiryDate = oldExpiry, status = oldStatus },
591	            after:  new { expiryDate = pkg.ExpiryDate, status = pkg.Status },
592	            metadata: new { reason });
593	
594	        return true;
595	    }
596	
597	    /// <summary>
598	    /// SPM-89 — directly grant a PACKAGE product to a client as a FREE COMP GRANT.
599	    /// <para>
600	    /// Loads the chosen <see cref="Product"/> and mints a <see cref="ClientPackage"/> from its
601	    /// <c>Credits</c> / <c>ValidityDays</c>. The minting logic intentionally MIRRORS
602	    /// <c>InvoiceService.ProvisionPackagesFromInvoiceAsync</c>:
603	    /// <list type="bullet">
604	    ///   <item>only <c>Type == "PACKAGE"</c> products provision a wallet;</item>
605	    ///   <item>credits floor at 1 (<c>product.Credits &gt; 0 ? product.Credits : 1</c>);</item>
606	    ///   <item><c>ValidityDays == 0</c> =&gt; <c>ExpiryDate</c> null / never-expires (SPM-38 fix).</item>
607	    /// </list>
608	    /// Because this is a comp grant there is no invoice/payment behind it, so
609	    /// <see cref="ClientPackage.InvoiceLineId"/> is left null and
610	    /// <see cref="ClientPackage.FractionalValuePerClass"/> is 0 (no revenue attribution).
611	    /// </para>
612	    /// <para>
613	    /// A single governance <see cref="AuditLog"/> row is written via <see cref="IAuditLogger"/>
614	    /// (non-throwing per its contract) — the same pattern the adjust-credit path uses — capturing
615	    /// the granting actor, the comp grant details and the mandatory <paramref name="reason"/>.
616	    /// </para>
617	    /// Returns the minted package, or <c>null</c> when the product is not found or is not a PACKAGE.
618	    /// </summary>
619	    public async Task<ClientPackage?> GrantPackageAsync(string clientId, string productId, string reason)
620	    {
621	        if (string.IsNullOrWhiteSpace(clientId)) return null;
622	        if (string.IsNullOrWhiteSpace(productId)) return null;
623	
624	        var product = await _products.Find(p => p.Id == productId).FirstOrDefaultAsync();
625	        if (product == null) return null;
626	
627	        // Mirror ProvisionPackagesFromInvoiceAsync: only PACKAGE products create wallets.
628	        if (product.Type != "PACKAGE") return null;
629	
630	        var credits = product.Credits > 0 ? product.Credits : 1;
631	        var validityDays = product.ValidityDays;
632	
633	        var newWallet = new ClientPackage
634	        {
635	            ClientId = clientId,
636	            // Comp grant — no invoice line behind it.
637	            InvoiceLineId = null,
638	            Format = product.FormatRestriction,
639	            TotalCredits = credits,
640	            CreditsRemaining = credits,
641	            ActivationDate = DateTime.UtcNow,
642	            // ValidityDays == 0 → open-ended package, no expiry date (SPM-38).
643	            ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
644	            Status = "ACTIVE",
645	            // Free comp grant: no revenue, so the per-class fractional value is 0.
646	            FractionalValuePerClass = 0
647	        };
648	
649	        await _clientPackages.InsertOneAsync(newWallet);
650	
651	        // Mirror ProvisionPackagesFromInvoiceAsync: a package that includes one
652	        // free private class grants a separate PRIVATE credit (value 0).
653	        if (product.IncludesFreePrivateClass)
654	        {
655	            await _clientPackages.InsertOneAsync(new ClientPackage
656	            {
657	                ClientId = clientId,
658	                InvoiceLineId = null,
659	                Format = "PRIVATE",
660	                TotalCredits = 1,
661	                CreditsRemaining = 1,
662	                ActivationDate = DateTime.UtcNow,
663	                ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
664	                Status = "ACTIVE",
665	                FractionalValuePerClass = 0,
666	                SourceNote = "FREE_PRIVATE:grant:" + (newWallet.Id ?? clientId),
667	            });
668	        }
669	
670	        // ── Governance audit row ──────────────────────────────────────────
671	        // Same IAuditLogger pattern as AdjustCreditAsync. Non-throwing: a failure
672	        // to persist the audit row must never roll back the granted package.
673	        await _auditLogger.LogAsync(
674	            action: "PACKAGE_GRANTED",
675	            entityType: "ClientPackage",
676	            entityId: newWallet.Id ?? "",
677	            entityLabel: $"{newWallet.Format} package · {newWallet.TotalCredits} credits",
678	            before: null,
679	            after: new
680	            {
681	                clientId = newWallet.ClientId,
682	                format = newWallet.Format,
683	                totalCredits = newWallet.TotalCredits,
684	                creditsRemaining = newWallet.CreditsRemaining,
685	                activationDate = newWallet.ActivationDate,
686	                expiryDate = newWallet.ExpiryDate,
687	                status = newWallet.Status,
688	            },
689	            metadata: new
690	            {
691	                reason,
692	                productId = product.Id,
693	                productName = product.Name,
694	                isCompGrant = true,
695	            });
696	
697	        return newWallet;
698	    }
699	}
