using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace SoulPilates.Services;

public class WalletService : IWalletService
{
    private readonly IMongoCollection<ClientPackage> _clientPackages;
    private readonly IMongoCollection<PackageLedgerLog> _ledger;
    private readonly IMongoCollection<PackageFreeze> _freezes;
    private readonly IMongoCollection<Product> _products;
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IAuditLogger _auditLogger;

    public WalletService(MongoDbContext dbContext, IAuditLogger auditLogger)
    {
        _clientPackages = dbContext.GetCollection<ClientPackage>("ClientPackages");
        _ledger = dbContext.GetCollection<PackageLedgerLog>("PackageLedgerLogs");
        _freezes = dbContext.GetCollection<PackageFreeze>("PackageFreezes");
        _products = dbContext.GetCollection<Product>("Products");
        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _auditLogger = auditLogger;
    }

    /// <summary>
    /// Per-package session/credit history for the admin client profile: every ledger
    /// movement on a package (class deductions, refunds, manual adjustments) resolved
    /// to the class name/date/instructor, so staff can vet usage vs remaining credits.
    /// </summary>
    public async Task<object?> GetPackageSessionHistoryAsync(string packageId)
    {
        var pkg = await _clientPackages.Find(p => p.Id == packageId).FirstOrDefaultAsync();
        if (pkg == null) return null;

        var entries = await _ledger.Find(l => l.PackageInstanceId == packageId)
            .SortByDescending(l => l.Timestamp).ToListAsync();

        var rows = new List<object>();
        foreach (var e in entries)
        {
            string? className = null; DateTime? sessionDate = null; string? instructor = null;
            if (!string.IsNullOrWhiteSpace(e.ReferenceAttendanceId))
            {
                var att = await _attendances.Find(a => a.Id == e.ReferenceAttendanceId).FirstOrDefaultAsync();
                if (att != null && !string.IsNullOrWhiteSpace(att.CalendarSessionId))
                {
                    var s = await _sessions.Find(x => x.Id == att.CalendarSessionId).FirstOrDefaultAsync();
                    if (s != null) { className = s.ClassName; sessionDate = s.StartTime; instructor = s.InstructorName; }
                }
            }
            rows.Add(new { timestamp = e.Timestamp, actionType = e.ActionType, amount = e.Amount, className, sessionDate, instructor, note = e.Notes });
        }

        return new
        {
            packageId = pkg.Id,
            productName = $"{pkg.Format} package \u00b7 {pkg.TotalCredits} credits",
            totalCredits = pkg.TotalCredits,
            creditsUsed = pkg.CreditsUsed,
            creditsRemaining = pkg.CreditsRemaining,
            entries = rows,
        };
    }

    public async Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
    {
        // A package with ExpiryDate == null never expires; include it unconditionally.
        // A package with a concrete ExpiryDate must still be in the future.
        var noExpiry  = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
        var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
        var expiryOk  = Builders<ClientPackage>.Filter.Or(noExpiry, notExpired);

        // MAT is a sub-type of group class. A MAT session can be paid with either a
        // MAT-specific package (preferred — consumed first) or a generic GROUP package
        // (fallback). Exact matches on other formats (PRIVATE, DUO, FREELANCE) are kept
        // strict so packages are never cross-consumed across incompatible class types.
        var upper = (format ?? "").ToUpperInvariant();
        var formatFilter = upper == "MAT"
            ? Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" })
            : Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper);

        var filter = Builders<ClientPackage>.Filter.And(
            Builders<ClientPackage>.Filter.Eq(p => p.ClientId, clientId),
            formatFilter,
            // Include LOW_BALANCE alongside ACTIVE: a package with ≤2 credits
            // remaining is still fully usable — excluding it would hide the
            // PACKAGE_CREDIT option at checkout even though credits exist.
            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
            Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0),
            expiryOk
        );

        // For MAT sessions: sort MAT-specific packages before GROUP fallbacks so the
        // specialised wallet is always consumed first. Within each bucket sort by
        // earliest expiry (FIFO across wallets of the same type).
        var packages = await _clientPackages.Find(filter).ToListAsync();
        if (upper == "MAT")
        {
            packages = packages
                .OrderBy(p => p.Format == "MAT" ? 0 : 1)
                .ThenBy(p => p.ExpiryDate ?? DateTime.MaxValue)
                .ToList();
        }
        else
        {
            packages = packages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).ToList();
        }
        return packages;
    }

    public async Task<IEnumerable<ClientPackage>> GetAllPackagesForClientAsync(string clientId)
    {
        return await _clientPackages.Find(p => p.ClientId == clientId)
            .SortByDescending(p => p.ActivationDate)
            .ToListAsync();
    }

    public async Task<IEnumerable<ClientPackage>> GetAllActivePackagesAsync()
    {
        var now = DateTime.UtcNow;
        var f = Builders<ClientPackage>.Filter;
        var filter = f.And(
            f.Gt(p => p.CreditsRemaining, 0),
            f.Nin(p => p.Status, new[] { "EXPIRED", "CANCELLED", "DEPLETED" }),
            f.Or(
                f.Eq(p => p.ExpiryDate, (DateTime?)null),
                f.Gt(p => p.ExpiryDate, now)));
        return await _clientPackages.Find(filter)
            .SortBy(p => p.ExpiryDate)
            .ToListAsync();
    }

    /// <summary>
    /// Deducts one credit/slot from the oldest-expiring active <see cref="ClientPackage"/> of the
    /// requested <paramref name="format"/> for the given client.
    /// Accepted formats: <c>"GROUP"</c>, <c>"PRIVATE"</c>, and (since P3-S13) <c>"FREELANCE"</c> —
    /// the same FIFO + low-balance + completed lifecycle applies regardless of format.
    /// <para>
    /// <paramref name="quantity"/> (Issue #3, default 1) deducts multiple credits in one call —
    /// e.g. a group-class multi-seat reservation. Credits are taken FIFO across the customer's
    /// active wallets of the format; the deduction may therefore span more than one wallet.
    /// Returns <c>false</c> if the customer has fewer than <paramref name="quantity"/> credits
    /// total — in that case no partial deduction is applied (atomic at the request level).
    /// </para>
    /// </summary>
    public async Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1)
    {
        if (quantity <= 0) quantity = 1;

        var activePackages = (await GetActivePackagesForClientAsync(clientId, format)).ToList();
        var totalAvailable = activePackages.Sum(p => p.CreditsRemaining);
        if (totalAvailable < quantity) return false;

        var remainingToDeduct = quantity;
        foreach (var pkg in activePackages)
        {
            if (remainingToDeduct <= 0) break;

            var take = Math.Min(pkg.CreditsRemaining, remainingToDeduct);
            pkg.CreditsRemaining -= take;
            pkg.CreditsUsed += take;

            if (pkg.CreditsRemaining == 0) pkg.Status = "COMPLETED";
            else if (pkg.CreditsRemaining <= 2) pkg.Status = "LOW_BALANCE";

            await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);

            var log = new PackageLedgerLog
            {
                PackageInstanceId = pkg.Id ?? "",
                ActionType = "DEDUCTION",
                Amount = -take,
                ReferenceAttendanceId = referenceAttendanceId
            };
            await _ledger.InsertOneAsync(log);

            remainingToDeduct -= take;
        }

        return true;
    }

    /// <summary>
    /// Refunds <paramref name="quantity"/> credits (default 1) back to the named
    /// <see cref="ClientPackage"/>. For multi-seat group cancellations the caller may need
    /// to invoke this once per source wallet if the original deduction spanned multiple
    /// wallets; the ledger log preserves which wallet each unit came from.
    /// </summary>
    public async Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1)
    {
        if (quantity <= 0) quantity = 1;

        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
        if (pkg == null) return false;

        pkg.CreditsRemaining += quantity;
        pkg.CreditsUsed -= quantity;
        if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative

        if (pkg.Status == "COMPLETED" && pkg.CreditsRemaining > 0)
        {
            pkg.Status = "ACTIVE";
        }

        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);

        var log = new PackageLedgerLog
        {
            PackageInstanceId = pkg.Id ?? "",
            ActionType = "REFUND",
            Amount = quantity,
            ReferenceAttendanceId = referenceAttendanceId
        };
        await _ledger.InsertOneAsync(log);

        return true;
    }

    /// <summary>
    /// Multi-wallet refund driven by the ledger. Walks every <c>DEDUCTION</c> row
    /// tagged with <paramref name="attendanceId"/> and reverses each one against its
    /// originating wallet — necessary because a single PACKAGE_CREDIT booking can
    /// span more than one <see cref="ClientPackage"/> when FIFO crosses a wallet
    /// boundary (e.g. 2-seat group class drawing 1 credit from each of two wallets).
    /// Idempotent: a second call after every DEDUCTION has been matched by a REFUND
    /// of equal or greater magnitude is a no-op (returns <c>false</c>).
    /// </summary>
    public async Task<bool> RefundCreditByAttendanceAsync(string attendanceId)
    {
        var (refundedAny, _) = await RefundCreditByAttendanceWithTrailAsync(attendanceId);
        return refundedAny;
    }

    /// <summary>
    /// SPM-108 — ledger-driven refund that also reports whether ANY ledger trail
    /// (deduction or prior refund) exists for this attendance.
    /// <para>
    /// Returns <c>(refunded, hasLedgerTrail)</c>:
    /// <list type="bullet">
    ///   <item><c>refunded</c> — true when at least one credit was actually
    ///   returned by THIS call (i.e. a wallet still had a net-negative position).</item>
    ///   <item><c>hasLedgerTrail</c> — true when one or more ledger rows reference
    ///   this attendance, regardless of net. Callers use this to decide whether the
    ///   legacy non-ledger <see cref="RefundCreditAsync"/> fallback is safe: a trail
    ///   exists means this booking has already been accounted for in the ledger, so
    ///   the blind +1 fallback MUST NOT run (it would phantom-refund a credit, e.g.
    ///   the owner-reported 1 -> 2 on a re-cancel where the net was already 0).</item>
    /// </list>
    /// </para>
    /// </summary>
    public async Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId)
    {
        if (string.IsNullOrWhiteSpace(attendanceId)) return (false, false);

        var entries = await _ledger
            .Find(l => l.ReferenceAttendanceId == attendanceId)
            .ToListAsync();
        if (entries.Count == 0) return (false, false);

        // Net per-wallet position: sum of all ledger rows. Positive/zero net means the
        // wallet has already been refunded; we only want to refund where net < 0
        // (i.e. credits still consumed by this attendance). This is what makes the
        // refund idempotent — a second call after a full refund finds no net-negative
        // wallet and returns refunded=false WITHOUT writing another REFUND row.
        var netByWallet = entries
            .GroupBy(e => e.PackageInstanceId)
            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
            .Where(x => x.Net < 0)
            .ToList();

        if (netByWallet.Count == 0) return (false, true); // trail exists, nothing left to refund

        var refundedAny = false;
        foreach (var w in netByWallet)
        {
            var qty = -w.Net; // flip the negative net into a positive refund quantity
            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
            refundedAny |= ok;
        }
        return (refundedAny, true);
    }

    /// <summary>
    /// SPM-110 — refund AT MOST <paramref name="seatsToRefund"/> credits for the attendance,
    /// for the per-seat cancel of a multi-seat group booking. Mirrors the idempotent,
    /// over-refund-safe net-by-wallet logic of <see cref="RefundCreditByAttendanceWithTrailAsync"/>
    /// but caps the total returned at the requested seat count.
    /// </summary>
    public async Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund)
    {
        if (string.IsNullOrWhiteSpace(attendanceId)) return (0, false);
        if (seatsToRefund <= 0) return (0, false);

        var entries = await _ledger
            .Find(l => l.ReferenceAttendanceId == attendanceId)
            .ToListAsync();
        if (entries.Count == 0) return (0, false);

        // Per-wallet net position, identical bookkeeping to the full-cancel path:
        // only wallets still net-negative have credits consumed by this attendance
        // that can be returned. This is what keeps the partial refund idempotent —
        // a second call after seats were already returned sees a smaller net and
        // will not over-refund.
        var netByWallet = entries
            .GroupBy(e => e.PackageInstanceId)
            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
            .Where(x => x.Net < 0)
            .ToList();

        if (netByWallet.Count == 0) return (0, true); // trail exists, nothing left to refund

        var remainingToRefund = seatsToRefund;
        var refundedCount = 0;
        foreach (var w in netByWallet)
        {
            if (remainingToRefund <= 0) break;

            // Cap this wallet's refund at the smaller of (credits it still owes) and
            // (seats we have left to return) so we never exceed the requested count.
            var available = -w.Net; // positive credits still consumed on this wallet
            var qty = Math.Min(available, remainingToRefund);
            if (qty <= 0) continue;

            var ok = await RefundCreditAsync(w.PackageInstanceId, attendanceId, qty);
            if (ok)
            {
                refundedCount += qty;
                remainingToRefund -= qty;
            }
        }

        return (refundedCount, true);
    }

    /// <summary>
    /// SPM-110 — neutralise the ledger net for up to <paramref name="seatsForfeited"/>
    /// seats of a late-cancelled PACKAGE_CREDIT booking WITHOUT touching wallet balances
    /// (the credits stay consumed — that's the forfeit). Writes ledger-only FORFEIT rows
    /// so the per-wallet net reflects the seats still genuinely owed, preventing a later
    /// cancel of the booking's remaining seats from over-refunding the forfeited ones.
    /// </summary>
    public async Task<int> ForfeitCreditByAttendanceAsync(string attendanceId, int seatsForfeited)
    {
        if (string.IsNullOrWhiteSpace(attendanceId)) return 0;
        if (seatsForfeited <= 0) return 0;

        var entries = await _ledger
            .Find(l => l.ReferenceAttendanceId == attendanceId)
            .ToListAsync();
        if (entries.Count == 0) return 0;

        var netByWallet = entries
            .GroupBy(e => e.PackageInstanceId)
            .Select(g => new { PackageInstanceId = g.Key, Net = g.Sum(e => e.Amount) })
            .Where(x => x.Net < 0)
            .ToList();

        if (netByWallet.Count == 0) return 0;

        var remaining = seatsForfeited;
        var forfeited = 0;
        foreach (var w in netByWallet)
        {
            if (remaining <= 0) break;

            var available = -w.Net; // credits still net-consumed on this wallet
            var qty = Math.Min(available, remaining);
            if (qty <= 0) continue;

            // Ledger-only positive row: raises the net toward zero so these seats can't
            // be refunded later, but deliberately does NOT modify the ClientPackage
            // (the customer forfeited these credits by cancelling late).
            var log = new PackageLedgerLog
            {
                PackageInstanceId = w.PackageInstanceId,
                ActionType = "FORFEIT",
                Amount = qty,
                ReferenceAttendanceId = attendanceId,
                Notes = "Late-cancel seat forfeit (SPM-110) — credit not returned to wallet.",
            };
            await _ledger.InsertOneAsync(log);

            forfeited += qty;
            remaining -= qty;
        }

        return forfeited;
    }

    public async Task ExpireOldPackagesAsync()
    {
        // Only expire packages that have a concrete ExpiryDate in the past.
        // Packages with ExpiryDate == null are open-ended and must never be swept.
        var filter = Builders<ClientPackage>.Filter.And(
            Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
            Builders<ClientPackage>.Filter.Ne(p => p.ExpiryDate, (DateTime?)null),
            Builders<ClientPackage>.Filter.Lt(p => p.ExpiryDate, DateTime.UtcNow)
        );

        var update = Builders<ClientPackage>.Update.Set(p => p.Status, "EXPIRED");
        await _clientPackages.UpdateManyAsync(filter, update);
    }

    public async Task FreezePackageAsync(string packageInstanceId, DateTime freezeStart, int daysToFreeze, string? reason)
    {
        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
        if (pkg == null) throw new Exception("Package not found.");

        // Extend expiry by freeze duration
        if (pkg.ExpiryDate.HasValue)
        {
            pkg.ExpiryDate = pkg.ExpiryDate.Value.AddDays(daysToFreeze);
        }
        pkg.Status = "FROZEN";
        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);

        // Log the freeze
        var freeze = new PackageFreeze
        {
            PackageInstanceId = packageInstanceId,
            FreezeStartDate = freezeStart,
            FreezeEndDate = freezeStart.AddDays(daysToFreeze),
            DaysAddedToExpiry = daysToFreeze,
            Reason = reason
        };
        await _freezes.InsertOneAsync(freeze);
    }

    /// <summary>
    /// Manually adjust credits on a specific <see cref="ClientPackage"/> by a signed
    /// <paramref name="delta"/>. Positive delta adds credits (gift / compassionate refund);
    /// negative removes them (manual forfeit).
    /// <para>
    /// When adding credits, <see cref="ClientPackage.TotalCredits"/> is increased by the
    /// same amount to keep the invariant <c>TotalCredits = CreditsUsed + CreditsRemaining</c>
    /// consistent and the credit-bar percentage meaningful.
    /// </para>
    /// <para>
    /// Two audit trails are written on success:
    /// <list type="bullet">
    ///   <item>A <see cref="PackageLedgerLog"/> row with <c>ActionType = "MANUAL_ADJUSTMENT"</c>
    ///   and the reason in <c>Notes</c> — this is the financial ledger record.</item>
    ///   <item>An <see cref="AuditLog"/> row via <see cref="IAuditLogger"/> capturing actor,
    ///   before/after credit snapshots, IP and correlation-id — this is the governance record.</item>
    /// </list>
    /// </para>
    /// </summary>
    public async Task<bool> AdjustCreditAsync(string packageInstanceId, int delta, string reason)
    {
        if (delta == 0) return false;

        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
        if (pkg == null) return false;

        // Guard: adjustments on frozen or expired packages are not allowed.
        // The admin should unfreeze (or extend expiry) first — otherwise the
        // status-recalculation logic below would silently overwrite FROZEN →
        // COMPLETED or leave stranded credits on an EXPIRED package that won't
        // appear in active-wallet queries.
        if (pkg.Status is "FROZEN" or "EXPIRED") return false;

        // Guard: can't remove more credits than the package currently holds.
        if (delta < 0 && pkg.CreditsRemaining < Math.Abs(delta)) return false;

        // Capture before-state for audit.
        var beforeRemaining = pkg.CreditsRemaining;
        var beforeUsed = pkg.CreditsUsed;
        var beforeTotal = pkg.TotalCredits;
        var beforeStatus = pkg.Status;

        // Apply the adjustment.
        pkg.CreditsRemaining += delta;
        if (delta > 0)
        {
            // Adding credits back: reduce CreditsUsed (we're returning consumed
            // credits, not expanding the package capacity). TotalCredits must
            // stay at the original product capacity so renewals, the credit bar,
            // and the wallet label always reflect the purchased package size.
            pkg.CreditsUsed -= delta;
            if (pkg.CreditsUsed < 0) pkg.CreditsUsed = 0; // defensive: never go negative
        }
        else
        {
            // Removing credits: reflect the removal in CreditsUsed.
            pkg.CreditsUsed += Math.Abs(delta);
        }

        // Recalculate status — mirrors the same rules as DeductCreditAsync.
        if (pkg.CreditsRemaining == 0)
            pkg.Status = "COMPLETED";
        else if (pkg.CreditsRemaining <= 2)
            pkg.Status = "LOW_BALANCE";
        else if (pkg.Status is "COMPLETED" or "LOW_BALANCE")
            pkg.Status = "ACTIVE";

        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);

        // ── Ledger row ────────────────────────────────────────────────────
        // ActionType = "MANUAL_ADJUSTMENT" (a new enum value in the comment
        // set of PackageLedgerLog). Notes carries the admin's stated reason.
        var log = new PackageLedgerLog
        {
            PackageInstanceId = pkg.Id ?? "",
            ActionType = "MANUAL_ADJUSTMENT",
            Amount = delta,
            ReferenceAttendanceId = null,
            Notes = reason,
        };
        await _ledger.InsertOneAsync(log);

        // ── Governance audit row ──────────────────────────────────────────
        // Non-throwing per the IAuditLogger contract — business transaction
        // is never rolled back if audit storage fails.
        await _auditLogger.LogAsync(
            action: "MANUAL_CREDIT_ADJUSTMENT",
            entityType: "ClientPackage",
            entityId: pkg.Id ?? "",
            entityLabel: $"{pkg.Format} package · {beforeTotal} credits",
            before: new
            {
                creditsRemaining = beforeRemaining,
                creditsUsed = beforeUsed,
                totalCredits = beforeTotal,
                status = beforeStatus,
            },
            after: new
            {
                creditsRemaining = pkg.CreditsRemaining,
                creditsUsed = pkg.CreditsUsed,
                totalCredits = pkg.TotalCredits,
                status = pkg.Status,
            },
            metadata: new { reason, delta });

        return true;
    }

    /// <summary>
    /// Admin operation: set or clear the expiry date on a specific
    /// <see cref="ClientPackage"/>. Pass <c>null</c> to make the package
    /// open-ended (never expires); pass a future <see cref="DateTime"/> to
    /// set or update the deadline.
    /// <para>
    /// Both the before- and after-state are written to the governance audit log.
    /// The package status is re-evaluated: if the new date is in the past the
    /// status flips to <c>EXPIRED</c>; if it is in the future (or null) and the
    /// package was previously <c>EXPIRED</c> due to date alone, it reverts to
    /// <c>ACTIVE</c> or <c>LOW_BALANCE</c>.
    /// </para>
    /// </summary>
    public async Task<bool> SetPackageExpiryAsync(string packageInstanceId, DateTime? newExpiry, string reason)
    {
        var pkg = await _clientPackages.Find(p => p.Id == packageInstanceId).FirstOrDefaultAsync();
        if (pkg == null) return false;

        var oldExpiry  = pkg.ExpiryDate;
        var oldStatus  = pkg.Status;

        pkg.ExpiryDate = newExpiry;

        // Re-evaluate status only when the package is not FROZEN/COMPLETED.
        // EXPIRED → flip back to active if the new date is future or null.
        if (pkg.Status is "EXPIRED")
        {
            if (newExpiry == null || newExpiry > DateTime.UtcNow)
                pkg.Status = pkg.CreditsRemaining <= 2 ? "LOW_BALANCE" : "ACTIVE";
        }
        else if (pkg.Status is "ACTIVE" or "LOW_BALANCE")
        {
            // If admin deliberately sets a past date, mark as expired immediately.
            if (newExpiry.HasValue && newExpiry.Value <= DateTime.UtcNow)
                pkg.Status = "EXPIRED";
        }

        await _clientPackages.ReplaceOneAsync(p => p.Id == pkg.Id, pkg);

        await _auditLogger.LogAsync(
            action: "EXPIRY_DATE_CHANGED",
            entityType: "ClientPackage",
            entityId: pkg.Id ?? "",
            entityLabel: $"{pkg.Format} package · {pkg.TotalCredits} credits",
            before: new { expiryDate = oldExpiry, status = oldStatus },
            after:  new { expiryDate = pkg.ExpiryDate, status = pkg.Status },
            metadata: new { reason });

        return true;
    }

    /// <summary>
    /// SPM-89 — directly grant a PACKAGE product to a client as a FREE COMP GRANT.
    /// <para>
    /// Loads the chosen <see cref="Product"/> and mints a <see cref="ClientPackage"/> from its
    /// <c>Credits</c> / <c>ValidityDays</c>. The minting logic intentionally MIRRORS
    /// <c>InvoiceService.ProvisionPackagesFromInvoiceAsync</c>:
    /// <list type="bullet">
    ///   <item>only <c>Type == "PACKAGE"</c> products provision a wallet;</item>
    ///   <item>credits floor at 1 (<c>product.Credits &gt; 0 ? product.Credits : 1</c>);</item>
    ///   <item><c>ValidityDays == 0</c> =&gt; <c>ExpiryDate</c> null / never-expires (SPM-38 fix).</item>
    /// </list>
    /// Because this is a comp grant there is no invoice/payment behind it, so
    /// <see cref="ClientPackage.InvoiceLineId"/> is left null and
    /// <see cref="ClientPackage.FractionalValuePerClass"/> is 0 (no revenue attribution).
    /// </para>
    /// <para>
    /// A single governance <see cref="AuditLog"/> row is written via <see cref="IAuditLogger"/>
    /// (non-throwing per its contract) — the same pattern the adjust-credit path uses — capturing
    /// the granting actor, the comp grant details and the mandatory <paramref name="reason"/>.
    /// </para>
    /// Returns the minted package, or <c>null</c> when the product is not found or is not a PACKAGE.
    /// </summary>
    public async Task<ClientPackage?> GrantPackageAsync(string clientId, string productId, string reason)
    {
        if (string.IsNullOrWhiteSpace(clientId)) return null;
        if (string.IsNullOrWhiteSpace(productId)) return null;

        var product = await _products.Find(p => p.Id == productId).FirstOrDefaultAsync();
        if (product == null) return null;

        // Mirror ProvisionPackagesFromInvoiceAsync: only PACKAGE products create wallets.
        if (product.Type != "PACKAGE") return null;

        var credits = product.Credits > 0 ? product.Credits : 1;
        var validityDays = product.ValidityDays;

        var newWallet = new ClientPackage
        {
            ClientId = clientId,
            // Comp grant — no invoice line behind it.
            InvoiceLineId = null,
            Format = product.FormatRestriction,
            TotalCredits = credits,
            CreditsRemaining = credits,
            ActivationDate = DateTime.UtcNow,
            // ValidityDays == 0 → open-ended package, no expiry date (SPM-38).
            ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
            Status = "ACTIVE",
            // Free comp grant: no revenue, so the per-class fractional value is 0.
            FractionalValuePerClass = 0
        };

        await _clientPackages.InsertOneAsync(newWallet);

        // Mirror ProvisionPackagesFromInvoiceAsync: a package that includes one
        // free private class grants a separate PRIVATE credit (value 0).
        if (product.IncludesFreePrivateClass)
        {
            await _clientPackages.InsertOneAsync(new ClientPackage
            {
                ClientId = clientId,
                InvoiceLineId = null,
                Format = "PRIVATE",
                TotalCredits = 1,
                CreditsRemaining = 1,
                ActivationDate = DateTime.UtcNow,
                ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
                Status = "ACTIVE",
                FractionalValuePerClass = 0,
                SourceNote = "FREE_PRIVATE:grant:" + (newWallet.Id ?? clientId),
            });
        }

        // ── Governance audit row ──────────────────────────────────────────
        // Same IAuditLogger pattern as AdjustCreditAsync. Non-throwing: a failure
        // to persist the audit row must never roll back the granted package.
        await _auditLogger.LogAsync(
            action: "PACKAGE_GRANTED",
            entityType: "ClientPackage",
            entityId: newWallet.Id ?? "",
            entityLabel: $"{newWallet.Format} package · {newWallet.TotalCredits} credits",
            before: null,
            after: new
            {
                clientId = newWallet.ClientId,
                format = newWallet.Format,
                totalCredits = newWallet.TotalCredits,
                creditsRemaining = newWallet.CreditsRemaining,
                activationDate = newWallet.ActivationDate,
                expiryDate = newWallet.ExpiryDate,
                status = newWallet.Status,
            },
            metadata: new
            {
                reason,
                productId = product.Id,
                productName = product.Name,
                isCompGrant = true,
            });

        return newWallet;
    }
}

