139	    /// Billable total for a session, honouring the fixed private-duo price. A PRIVATE
140	    /// session booked for 2 (a Duo Class) bills the flat <paramref name="privateDuoPrice"/>
141	    /// instead of 2x the drop-in; everything else is dropIn * seats.
142	    /// </summary>
143	    public static decimal DuoAwareTotal(string? format, decimal dropIn, int seats, decimal privateDuoPrice)
144	    {
145	        if (seats < 1) seats = 1;
146	        if (format == "PRIVATE" && seats == 2 && privateDuoPrice > 0m) return privateDuoPrice;
147	        return dropIn * seats;
