150	    public async Task<PriceQuote> QuotePriceAsync(
151	        string sessionFormat,
152	        string paymentMethod,
153	        decimal? customSessionFee = null,
154	        int quantity = 1,
155	        string? clientId = null,
156	        decimal promoDiscount = 0m)
157	    {
158	        // Defensive clamps:
159	        //   • Private classes are 1-seat, EXCEPT a "Duo Class" (SPM-98) which seats 2
160	        //     in the same private session (booker pays for both); cap PRIVATE at 2 so a
161	        //     malicious or buggy client cannot bill more than a duo.
162	        //   • quantity ≤ 0 is meaningless; treat as 1.
163	        if (quantity <= 0) quantity = 1;
164	        if (sessionFormat == "PRIVATE" && quantity > 2) quantity = 2;
165	
166	        // Deposit % and session pricing are admin-owned — no appsettings fallbacks.
167	        var settings = await _settingsService.GetAsync();
168	        var depositPct = settings.DepositPercentage;
169	        var feePct = settings.OnlinePaymentFeePercentage;
170	
171	        // customSessionFee must always be supplied by the caller (sourced from
172	        // CalendarSession.DropInPrice which is snapshotted from the ClassBlueprint).
173	        // A null here means the caller forgot to pass it — surface a clear error
174	        // rather than silently quoting the wrong price.
175	        if (customSessionFee is null)
176	            throw new InvalidOperationException(
177	                "PAYMENT.MISSING_SESSION_FEE — customSessionFee is required. " +
178	                "Pass CalendarSession.DropInPrice when calling QuotePriceAsync.");
179	
180	        var sessionFee = customSessionFee.Value;
181	
182	        // Total billable for this quote is sessionFee * quantity. For STRIPE_FULL and
183	        // PAY_AT_STUDIO the customer pays this in full one way or another. For
184	        // STRIPE_DEPOSIT the deposit is taken on the total and the remainder is
185	        // collected at the studio. PACKAGE_CREDIT pays zero today and deducts N credits at check-in.
186	        var billableTotal = DuoAwareTotal(sessionFormat, sessionFee, quantity, settings.PrivateDuoPrice);
187	
188	        // Booking-page promo (e.g. bring-a-friend one free seat) — subtract the
189	        // discount from the billable total, clamped so it can never go negative.
190	        var appliedDiscount = Math.Clamp(promoDiscount, 0m, billableTotal);
191	        billableTotal -= appliedDiscount;
192	
193	        var quote = new PriceQuote
194	        {
195	            SessionFee = sessionFee,
196	            DepositPercentage = depositPct,
197	            FeePercentage = feePct,
198	            Currency = Currency,
199	            Quantity = quantity,
200	            PromoDiscount = appliedDiscount,
201	        };
202	
203	        switch (paymentMethod)
204	        {
205	            case "PACKAGE_CREDIT":
206	                quote.AmountDueNow = 0;
207	                quote.AmountDueAtStudio = 0;
208	                break;
209	            case "STRIPE_DEPOSIT":
210	            {
211	                var baseDeposit = Math.Round(billableTotal * depositPct / 100m);
212	                var fee = feePct > 0 ? Math.Round(baseDeposit * feePct / 100m) : 0m;
213	                quote.FeeAmount = fee;
214	                quote.AmountDueNow = baseDeposit + fee;
215	                quote.AmountDueAtStudio = billableTotal - baseDeposit; // remaining is base, no extra fee
216	                break;
217	            }
218	            case "STRIPE_FULL":
219	            {
220	                var fee = feePct > 0 ? Math.Round(billableTotal * feePct / 100m) : 0m;
221	                quote.FeeAmount = fee;
222	                quote.AmountDueNow = billableTotal + fee;
223	                quote.AmountDueAtStudio = 0;
224	                break;
225	            }
226	            case "PAY_AT_STUDIO":
227	                quote.AmountDueNow = 0;
228	                quote.AmountDueAtStudio = billableTotal;
229	                break;
230	            default:
231	                throw new ArgumentException($"Unknown payment method: {paymentMethod}");
232	        }
233	
234	        // Upsell suggestions — only attached on the PRIMARY quote call (typically
235	        // STRIPE_FULL) the frontend uses. The frontend can call this once per
236	        // method but `Upsells` will be identical across them, so we leave the
237	        // duplicate work to the caller's choice.
238	        quote.Upsells = await BuildUpsellSuggestionsAsync(sessionFormat, sessionFee, clientId, settings);
239	
240	        return quote;
241	    }
