243	    /// <summary>
244	    /// Compute the admin-configured upsell suggestion for a quote.
245	    /// Returns a single-item list when a product has been pinned for the session
246	    /// format and the customer is eligible; otherwise returns an empty list.
247	    ///
248	    /// Empty list when:
249	    ///   • <see cref="GlobalSettings.EnableCheckoutPackageUpsell"/> is off, OR
250	    ///   • No product ID is pinned for the session's format, OR
251	    ///   • The pinned product no longer exists / is inactive, OR
252	    ///   • The customer already owns an active package and
253	    ///     <see cref="GlobalSettings.UpsellHideForActivePackageHolders"/> is true.
254	    /// </summary>
255	    private async Task<List<UpsellSuggestion>> BuildUpsellSuggestionsAsync(
256	        string sessionFormat,
257	        decimal dropInPrice,
258	        string? clientId,
259	        GlobalSettings settings)
260	    {
261	        if (!settings.EnableCheckoutPackageUpsell) return new List<UpsellSuggestion>();
262	
263	        // Pick the pinned product ID for this session format.
264	        var pinnedId = sessionFormat switch
265	        {
266	            "PRIVATE" => settings.UpsellPackageIdPrivate,
267	            "MIXED"   => settings.UpsellPackageIdMixed,
268	            _         => settings.UpsellPackageIdGroup, // GROUP and anything else
269	        };
270	
271	        if (string.IsNullOrWhiteSpace(pinnedId)) return new List<UpsellSuggestion>();
272	
273	        // Hide-when-owner check.
274	        if (settings.UpsellHideForActivePackageHolders && !string.IsNullOrWhiteSpace(clientId))
275	        {
276	            var ownsActive = await _clientPackages
277	                .Find(p => p.ClientId == clientId
278	                           && p.Status == "ACTIVE"
279	                           && p.CreditsRemaining > 0
280	                           && (p.ExpiryDate == null || p.ExpiryDate > DateTime.UtcNow))
281	                .AnyAsync();
282	            if (ownsActive) return new List<UpsellSuggestion>();
283	        }
284	
285	        // Load the pinned product. Never surface a product hidden from the
286	        // online shop as the checkout upsell.
287	        var product = await _products
288	            .Find(p => p.Id == pinnedId && p.IsActive && p.Type == "PACKAGE" && p.Credits > 0 && !p.HiddenFromOnline)
289	            .FirstOrDefaultAsync();
290	
291	        if (product == null) return new List<UpsellSuggestion>();
292	
293	        var perClass = Math.Round(product.BasePrice / product.Credits);
294	        var savingsPct = dropInPrice > 0
295	            ? (int)Math.Round((dropInPrice - perClass) * 100m / dropInPrice)
296	            : 0;
297	
298	        return new List<UpsellSuggestion>
299	        {
300	            new UpsellSuggestion
301	            {
302	                ProductId       = product.Id ?? "",
303	                Name            = product.Name,
304	                Description     = product.Description,
305	                FormatRestriction = product.FormatRestriction ?? "NONE",
306	                BasePrice       = product.BasePrice,
307	                Credits         = product.Credits,
308	                ValidityDays    = product.ValidityDays,
309	                PricePerClass   = perClass,
310	                SavingsPercentage = savingsPct,
311	            }
312	        };
313	    }
