315	    /// <summary>
316	    /// BOGO ("Buy 1 Get 1 Free") reward: when a booking made with the BOGO offer
317	    /// is confirmed, grant the client one free GROUP class credit valid 7 days.
318	    /// Idempotent-ish — fires once at the RESERVED→BOOKED transition. Best-effort:
319	    /// never throws into the booking flow.
320	    /// </summary>
321	    private async Task GrantBogoCreditIfEligibleAsync(Attendance? attendance)
322	    {
323	        try
