/// database-stored secret key before making any Stripe SDK call.
/// </summary>
private void EnsureStripeApiKey(StripeConfigResult cfg)
{
    if (!string.IsNullOrWhiteSpace(cfg.SecretKey))
        StripeConfiguration.ApiKey = cfg.SecretKey;
}

/// <summary>
/// Billable total for a session, honouring the fixed private-duo price. A PRIVATE
/// session booked for 2 (a Duo Class) bills the flat <paramref name="privateDuoPrice"/>
/// instead of 2x the drop-in; everything else is dropIn * seats.
/// </summary>
public static decimal DuoAwareTotal(string? format, decimal dropIn, int seats, decimal privateDuoPrice)
{
    if (seats < 1) seats = 1;
    if (format == "PRIVATE" && seats == 2 && privateDuoPrice > 0m) return privateDuoPrice;
    return dropIn * seats;
}

public async Task<PriceQuote> QuotePriceAsync(
    string sessionFormat,
    string paymentMethod,
    decimal? customSessionFee = null,
    int quantity = 1,
    string? clientId = null,
    decimal promoDiscount = 0m)
{
    // Defensive clamps:
    //   • Private classes are 1-seat, EXCEPT a "Duo Class" (SPM-98) which seats 2
    //     in the same private session (booker pays for both); cap PRIVATE at 2 so a
    //     malicious or buggy client cannot bill more than a duo.
    //   • quantity ≤ 0 is meaningless; treat as 1.
    if (quantity <= 0) quantity = 1;
    if (sessionFormat == "PRIVATE" && quantity > 2) quantity = 2;

    // Deposit % and session pricing are admin-owned — no appsettings fallbacks.
    var settings = await _settingsService.GetAsync();
    var depositPct = settings.DepositPercentage;
    var feePct = settings.OnlinePaymentFeePercentage;

    // customSessionFee must always be supplied by the caller (sourced from
    // CalendarSession.DropInPrice which is snapshotted from the ClassBlueprint).
    // A null here means the caller forgot to pass it — surface a clear error
    // rather than silently quoting the wrong price.
    if (customSessionFee is null)
        throw new InvalidOperationException(
            "PAYMENT.MISSING_SESSION_FEE — customSessionFee is required. " +
            "Pass CalendarSession.DropInPrice when calling QuotePriceAsync.");

    var sessionFee = customSessionFee.Value;

    // Total billable for this quote is sessionFee * quantity. For STRIPE_FULL and
    // PAY_AT_STUDIO the customer pays this in full one way or another. For
    // STRIPE_DEPOSIT the deposit is taken on the total and the remainder is
    // collected at the studio. PACKAGE_CREDIT pays zero today and deducts N credits at check-in.
    var billableTotal = DuoAwareTotal(sessionFormat, sessionFee, quantity, settings.PrivateDuoPrice);

    // Booking-page promo (e.g. bring-a-friend one free seat) — subtract the
    // discount from the billable total, clamped so it can never go negative.
    var appliedDiscount = Math.Clamp(promoDiscount, 0m, billableTotal);
    billableTotal -= appliedDiscount;

    var quote = new PriceQuote
    {
        SessionFee = sessionFee,
        DepositPercentage = depositPct,
        FeePercentage = feePct,
        Currency = Currency,
        Quantity = quantity,
        PromoDiscount = appliedDiscount,
    };

    switch (paymentMethod)
    {
        case "PACKAGE_CREDIT":
            quote.AmountDueNow = 0;
            quote.AmountDueAtStudio = 0;
            break;
        case "STRIPE_DEPOSIT":
        {
            var baseDeposit = Math.Round(billableTotal * depositPct / 100m);
            var fee = feePct > 0 ? Math.Round(baseDeposit * feePct / 100m) : 0m;
            quote.FeeAmount = fee;
            quote.AmountDueNow = baseDeposit + fee;
            quote.AmountDueAtStudio = billableTotal - baseDeposit; // remaining is base, no extra fee
            break;
        }
        case "STRIPE_FULL":
        {
            var fee = feePct > 0 ? Math.Round(billableTotal * feePct / 100m) : 0m;
            quote.FeeAmount = fee;
            quote.AmountDueNow = billableTotal + fee;
            quote.AmountDueAtStudio = 0;
            break;
        }
        case "PAY_AT_STUDIO":
            quote.AmountDueNow = 0;
            quote.AmountDueAtStudio = billableTotal;
            break;
        default:
            throw new ArgumentException($"Unknown payment method: {paymentMethod}");
    }

    // Upsell suggestions — only attached on the PRIMARY quote call (typically
    // STRIPE_FULL) the frontend uses. The frontend can call this once per
    // method but `Upsells` will be identical across them, so we leave the
    // duplicate work to the caller's choice.
    quote.Upsells = await BuildUpsellSuggestionsAsync(sessionFormat, sessionFee, clientId, settings);

    return quote;
}

/// <summary>
/// Compute the admin-configured upsell suggestion for a quote.
/// Returns a single-item list when a product has been pinned for the session
/// format and the customer is eligible; otherwise returns an empty list.
///
/// Empty list when:
///   • <see cref="GlobalSettings.EnableCheckoutPackageUpsell"/> is off, OR
///   • No product ID is pinned for the session's format, OR
///   • The pinned product no longer exists / is inactive, OR
///   • The customer already owns an active package and
///     <see cref="GlobalSettings.UpsellHideForActivePackageHolders"/> is true.
/// </summary>
private async Task<List<UpsellSuggestion>> BuildUpsellSuggestionsAsync(
    string sessionFormat,
    decimal dropInPrice,
    string? clientId,
    GlobalSettings settings)
{
    if (!settings.EnableCheckoutPackageUpsell) return new List<UpsellSuggestion>();

    // Pick the pinned product ID for this session format.
    var pinnedId = sessionFormat switch
    {
        "PRIVATE" => settings.UpsellPackageIdPrivate,
        "MIXED"   => settings.UpsellPackageIdMixed,
        _         => settings.UpsellPackageIdGroup, // GROUP and anything else
    };

    if (string.IsNullOrWhiteSpace(pinnedId)) return new List<UpsellSuggestion>();

    // Hide-when-owner check.
    if (settings.UpsellHideForActivePackageHolders && !string.IsNullOrWhiteSpace(clientId))
    {
        var ownsActive = await _clientPackages
            .Find(p => p.ClientId == clientId
                       && p.Status == "ACTIVE"
                       && p.CreditsRemaining > 0
                       && (p.ExpiryDate == null || p.ExpiryDate > DateTime.UtcNow))
            .AnyAsync();
        if (ownsActive) return new List<UpsellSuggestion>();
    }

    // Load the pinned product. Never surface a product hidden from the
    // online shop as the checkout upsell.
    var product = await _products
        .Find(p => p.Id == pinnedId && p.IsActive && p.Type == "PACKAGE" && p.Credits > 0 && !p.HiddenFromOnline)
        .FirstOrDefaultAsync();

    if (product == null) return new List<UpsellSuggestion>();

    var perClass = Math.Round(product.BasePrice / product.Credits);
    var savingsPct = dropInPrice > 0
        ? (int)Math.Round((dropInPrice - perClass) * 100m / dropInPrice)
        : 0;

    return new List<UpsellSuggestion>
    {
        new UpsellSuggestion
        {
            ProductId       = product.Id ?? "",
            Name            = product.Name,
            Description     = product.Description,
            FormatRestriction = product.FormatRestriction ?? "NONE",
            BasePrice       = product.BasePrice,
            Credits         = product.Credits,
            ValidityDays    = product.ValidityDays,
            PricePerClass   = perClass,
            SavingsPercentage = savingsPct,
        }
    };
}

/// <summary>
/// BOGO ("Buy 1 Get 1 Free") reward: when a booking made with the BOGO offer
/// is confirmed, grant the client one free GROUP class credit valid 7 days.
/// Idempotent-ish — fires once at the RESERVED→BOOKED transition. Best-effort:
/// never throws into the booking flow.
/// </summary>
private async Task GrantBogoCreditIfEligibleAsync(Attendance? attendance)
{
    try
    {
        if (attendance is null) return;
        if (!string.Equals(attendance.PromoCode, "BOGO", StringComparison.OrdinalIgnoreCase)) return;
        if (string.IsNullOrWhiteSpace(attendance.ClientId)) return;
        // Guard against a duplicate grant if this transition runs twice.
        var already = await _clientPackages
            .Find(p => p.ClientId == attendance.ClientId && p.SourceNote == "BOGO:" + attendance.Id)
            .AnyAsync();
        if (already) return;

        await _clientPackages.InsertOneAsync(new ClientPackage
        {
            ClientId = attendance.ClientId,
            Format = "GROUP",
            TotalCredits = 1,
            CreditsUsed = 0,
            CreditsRemaining = 1,
            ActivationDate = DateTime.UtcNow,
            ExpiryDate = DateTime.UtcNow.AddDays(7),
            Status = "ACTIVE",
            FractionalValuePerClass = 0m,
            SourceNote = "BOGO:" + attendance.Id,
        });
    }
    catch { /* analytics/reward must never break a booking */ }
}

public async Task<PaymentIntentResult> CreateIntentAsync(string attendanceId, string paymentMethod)
{
    var attendance = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync()
        ?? throw new Exception("Booking not found.");
    var session = await _sessions.Find(s => s.Id == attendance.CalendarSessionId).FirstOrDefaultAsync()
        ?? throw new Exception("Session not found.");

    // Resolve the drop-in price: prefer the session's snapshotted price, but
    // fall back to the blueprint's current price for sessions materialized before
    // the price was set (same fallback as PaymentController.Quote).
    var resolvedFee = session.DropInPrice;
    if (resolvedFee is null && !string.IsNullOrWhiteSpace(session.ClassBlueprintId))
    {
        var bp = await _blueprints.Find(b => b.Id == session.ClassBlueprintId).FirstOrDefaultAsync();
        if (bp != null) resolvedFee = bp.DropInPrice;
    }

    var quote = await QuotePriceAsync(
        session.Format,
        paymentMethod,
        customSessionFee: resolvedFee,
        quantity: Math.Max(1, attendance.Quantity),
        clientId: attendance.ClientId);

