    // Previously this block did a read-only pre-flight and left the
    // actual deduction to check-in, which (a) never happened in code,
    // and (b) contradicted the studio's policy of "use credits up
    // while confirming/checking out". We now:
    //   1. Read all eligible wallets ordered by expiry (FIFO).
    //   2. Fail fast if the customer doesn't have `quantity` credits.
    //   3. Stamp the oldest-contributing wallet on the attendance so
    //      cancellation can find a refund target (refund itself walks
    //      the ledger for the full multi-wallet case).
    //   4. Delegate the actual atomic decrement to WalletService so
    //      the PackageLedgerLog entries are written in lock-step with
    //      the wallet state — the same code path admins use.
    if (paymentMethod == "PACKAGE_CREDIT")
    {
        var quantityNeeded = Math.Max(1, attendance.Quantity);

        // SPM-108: the pre-flight wallet read MUST match the wallet set
        // DeductCreditAsync actually decrements, otherwise the two can
        // disagree on the boundary case. A wallet with its LAST credit(s)
        // has Status == "LOW_BALANCE" (set by DeductCreditAsync once
        // CreditsRemaining <= 2), NOT "ACTIVE". The previous inline filter
        // here only accepted "ACTIVE", so a customer's final credit was
        // invisible to this pre-flight: totalCredits came back 0, this
        // method threw INSUFFICIENT_CREDITS, and the attendance was left
        // stranded in RESERVED (never promoted to BOOKED, no credit spent).
        // Delegate to the canonical active-wallet query (ACTIVE +
        // LOW_BALANCE, expiry-aware, FIFO-sorted) — the exact same query
        // DeductCreditAsync walks — so the two stay in lock-step.
        var activeWallets = (await _walletService
            .GetActivePackagesForClientAsync(attendance.ClientId, session.Format))
            .ToList();
        var totalCredits = activeWallets.Sum(p => p.CreditsRemaining);
        if (totalCredits < quantityNeeded)
            throw new InvalidOperationException(
                $"BOOKING.INSUFFICIENT_CREDITS — {quantityNeeded} credit(s) required but only {totalCredits} available.");

        // Pick the oldest-expiring wallet as the "primary" refund target.
        // WalletService.RefundCreditByAttendanceAsync walks the ledger
        // so a deduction that spans more than one wallet is still fully
        // reversed on cancel; this field is just a fast-path hint and a
        // legacy compatibility shim for existing single-wallet refund code.
        // Order by soonest-expiring first; never-expiring (null) wallets sort
        // last so an open-ended package isn't burned before a dated one.
        var primaryWallet = activeWallets
            .OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue)
            .First();

        var deducted = await _walletService.DeductCreditAsync(
            attendance.ClientId,
            session.Format,
            attendanceId,
            quantityNeeded);
