public async Task<Attendance> AdminAddStudentAsync(string sessionId, string clientId, string clientName, string? clientPhone, int quantity = 1)
{
    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
    if (session == null) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

    // SPM-126 — The duplicate-booking guard is intentionally omitted here.
    // The owner wants admins to add the same client to a session more than once
    // (e.g. the client is bringing a guest, or buying a second seat at the desk).
    // Each add is a distinct Attendance row and bumps CurrentBookings by the seat
    // quantity. This mirrors WalkInCheckoutAsync, which by design also skips the
    // guard. The customer-facing BookClientAsync guard is unaffected.

    // Capacity guard — enforce even for admin adds. Accounts for the requested
    // quantity so a 2-seat add against 1 remaining spot is rejected.
    var requestedSeats = Math.Max(1, quantity);
    if (string.Equals(session.Format, "PRIVATE", StringComparison.OrdinalIgnoreCase))
    {
        // SPM-98 — Duo private. A PRIVATE session is created with Capacity=1 (a
        // 1-on-1 slot). The studio may instead run it as a DUO — two clients in
        // the same private session. Mirror ReserveSpotAsync's duo rule for the
        // admin/desk add path: clamp any private add to at most 2 seats, ensure
        // the class stays within the duo cap of 2 total, then lift the session's
        // Capacity 1→2 so the second seat (one booker taking ×2, OR a distinct
        // second client taking ×1) fits the atomic capacity guard below. Only ever
        // raise it — never shrink an admin-configured larger capacity.
        requestedSeats = Math.Min(requestedSeats, 2);
        var wouldHold = session.CurrentBookings + requestedSeats;
        if (wouldHold > 2)
            throw new BusinessRuleException("BOOKING.PRIVATE_DUO_MAX",
                "A private session can hold at most 2 people (duo). Remove a seat before adding another.");
        if (session.Capacity < wouldHold)
        {
            await _sessions.UpdateOneAsync(
                s => s.Id == sessionId,
                Builders<CalendarSession>.Update.Set(s => s.Capacity, 2));
            session.Capacity = 2;
        }
    }
    var spotsLeft = session.Capacity - session.CurrentBookings;
    if (spotsLeft <= 0)
        throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "This class is at full capacity.");
    if (requestedSeats > spotsLeft)
        throw new BusinessRuleException("BOOKING.CAPACITY_REACHED",
            $"Only {spotsLeft} spot{(spotsLeft == 1 ? "" : "s")} remaining. Cannot add {requestedSeats} seat{(requestedSeats == 1 ? "" : "s")}.");

    // SPM-120 — A manual admin/instructor add is an UNPAID booking that the studio
    // must collect for at the desk. Mirror the WalkInCheckout snapshot logic so the
    // POS "collect" card surfaces the correct outstanding balance instead of ₫0:
    // stamp PaymentMethod = PAY_AT_STUDIO and snapshot the amount due from the
    // session's drop-in price × seat quantity (defaults to 1). For a free class

using SoulPilates.Core.Entities;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SoulPilates.Core.Interfaces;

public interface IWalletService
{
    Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format);
    /// <summary>Per-package session/credit history (ledger resolved to class name/date/instructor) for admin vetting.</summary>
    Task<object?> GetPackageSessionHistoryAsync(string packageId);
    Task<IEnumerable<ClientPackage>> GetAllPackagesForClientAsync(string clientId);

    /// <summary>All active packages across every client (credits remaining, not expired/cancelled) — for the admin Packages overview.</summary>
    Task<IEnumerable<ClientPackage>> GetAllActivePackagesAsync();
    Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1);
    Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1);

    /// <summary>
    /// Refund every credit that the given attendance previously deducted, walking the
    /// ledger to find the originating wallet(s). Required for cancellations of
    /// PACKAGE_CREDIT bookings whose deduction may have spanned more than one wallet.
    /// </summary>
    Task<bool> RefundCreditByAttendanceAsync(string attendanceId);

    /// <summary>
    /// SPM-108 — like <see cref="RefundCreditByAttendanceAsync"/> but also reports
    /// whether ANY ledger trail exists for the attendance. Returns
    /// <c>(refunded, hasLedgerTrail)</c>. Callers use <c>hasLedgerTrail</c> to decide
    /// whether the legacy non-ledger <see cref="RefundCreditAsync"/> fallback is safe:
    /// when a trail exists the booking is already ledger-accounted, so the blind
    /// fallback must be skipped to avoid a phantom (double) refund.
    /// </summary>
    Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId);

    /// <summary>
    /// SPM-110 — PARTIAL ledger-driven refund: returns at most <paramref name="seatsToRefund"/>
    /// credits to the originating wallet(s) for the given attendance, instead of the entire
    /// net-negative position the full-cancel <see cref="RefundCreditByAttendanceWithTrailAsync"/>
    /// reverses. Used when a customer cancels only some seats of a multi-seat group booking.
    /// <para>
    /// Walks net-negative wallets (FIFO by ledger order) and refunds against each until the
    /// requested seat count is satisfied or no net-negative credit remains. Idempotent and
    /// over-refund-safe: each refunded seat shrinks the per-wallet net, so a repeated call only
    /// ever reverses credits still net-consumed by this attendance.
    /// </para>
    /// Returns <c>(refundedCount, hasLedgerTrail)</c> where <c>refundedCount</c> is the number of
    /// credits actually returned by THIS call (0 when nothing was outstanding) and
    /// <c>hasLedgerTrail</c> is true when any ledger row references the attendance (callers use it
    /// to gate the legacy non-ledger fallback exactly as the full-cancel path does).
    /// </summary>
    Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund);

    /// <summary>
