using SoulPilates.Core.Entities;
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SoulPilates.Core.Interfaces;

public interface IWalletService
{
    Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format);
    /// <summary>Per-package session/credit history (ledger resolved to class name/date/instructor) for admin vetting.</summary>
    Task<object?> GetPackageSessionHistoryAsync(string packageId);
    Task<IEnumerable<ClientPackage>> GetAllPackagesForClientAsync(string clientId);

    /// <summary>All active packages across every client (credits remaining, not expired/cancelled) — for the admin Packages overview.</summary>
    Task<IEnumerable<ClientPackage>> GetAllActivePackagesAsync();
    Task<bool> DeductCreditAsync(string clientId, string format, string referenceAttendanceId, int quantity = 1);
    Task<bool> RefundCreditAsync(string packageInstanceId, string referenceAttendanceId, int quantity = 1);

    /// <summary>
    /// Refund every credit that the given attendance previously deducted, walking the
    /// ledger to find the originating wallet(s). Required for cancellations of
    /// PACKAGE_CREDIT bookings whose deduction may have spanned more than one wallet.
    /// </summary>
    Task<bool> RefundCreditByAttendanceAsync(string attendanceId);

    /// <summary>
    /// SPM-108 — like <see cref="RefundCreditByAttendanceAsync"/> but also reports
    /// whether ANY ledger trail exists for the attendance. Returns
    /// <c>(refunded, hasLedgerTrail)</c>. Callers use <c>hasLedgerTrail</c> to decide
    /// whether the legacy non-ledger <see cref="RefundCreditAsync"/> fallback is safe:
    /// when a trail exists the booking is already ledger-accounted, so the blind
    /// fallback must be skipped to avoid a phantom (double) refund.
    /// </summary>
    Task<(bool refunded, bool hasLedgerTrail)> RefundCreditByAttendanceWithTrailAsync(string attendanceId);

    /// <summary>
    /// SPM-110 — PARTIAL ledger-driven refund: returns at most <paramref name="seatsToRefund"/>
    /// credits to the originating wallet(s) for the given attendance, instead of the entire
    /// net-negative position the full-cancel <see cref="RefundCreditByAttendanceWithTrailAsync"/>
    /// reverses. Used when a customer cancels only some seats of a multi-seat group booking.
    /// <para>
    /// Walks net-negative wallets (FIFO by ledger order) and refunds against each until the
    /// requested seat count is satisfied or no net-negative credit remains. Idempotent and
    /// over-refund-safe: each refunded seat shrinks the per-wallet net, so a repeated call only
    /// ever reverses credits still net-consumed by this attendance.
    /// </para>
    /// Returns <c>(refundedCount, hasLedgerTrail)</c> where <c>refundedCount</c> is the number of
    /// credits actually returned by THIS call (0 when nothing was outstanding) and
    /// <c>hasLedgerTrail</c> is true when any ledger row references the attendance (callers use it
    /// to gate the legacy non-ledger fallback exactly as the full-cancel path does).
    /// </summary>
    Task<(int refundedCount, bool hasLedgerTrail)> RefundPartialCreditByAttendanceWithTrailAsync(string attendanceId, int seatsToRefund);

    /// <summary>
    /// SPM-110 — record that <paramref name="seatsForfeited"/> seats of a PACKAGE_CREDIT
    /// booking were cancelled LATE (outside the window) and their credits are forfeited.
    /// Writes ledger-only FORFEIT rows tagged to the attendance that bring the per-wallet
    /// net back up by the forfeited amount WITHOUT returning credits to the wallet (the
    /// credits stay consumed — that's the forfeit). This keeps the ledger net in sync with
    /// the seats actually still owed, so a LATER cancel of the booking's remaining seats
    /// can't over-refund the already-forfeited seats. Walks the same net-negative wallets
    /// the refund path uses and is idempotent/over-forfeit-safe (never neutralises more net
    /// than is outstanding). No-op when nothing is net-negative for the attendance.
    /// Returns the number of seats actually neutralised by this call.
    /// </summary>
    Task<int> ForfeitCreditByAttendanceAsync(string attendanceId, int seatsForfeited);

    Task ExpireOldPackagesAsync();
    Task FreezePackageAsync(string packageInstanceId, DateTime freezeStart, int daysToFreeze, string? reason);

    /// <summary>
    /// Manually adjust the credits on a specific <see cref="ClientPackage"/> by a signed delta.
    /// Positive delta adds credits (e.g. gift, compassionate refund); negative removes them.
    /// A non-empty <paramref name="reason"/> is mandatory — it is written to both the
    /// <see cref="PackageLedgerLog"/> and the <see cref="AuditLog"/> for full traceability.
    /// Returns <c>false</c> if the package is not found, or if a removal would push credits below zero.
    /// </summary>
    Task<bool> AdjustCreditAsync(string packageInstanceId, int delta, string reason);

    /// <summary>
    /// Set or clear the expiry date on a specific package. Passing <c>null</c> makes the
    /// package open-ended (never expires). Re-evaluates the package status on save and writes
    /// an audit-log entry. Returns <c>false</c> when the package is not found.
    /// </summary>
    Task<bool> SetPackageExpiryAsync(string packageInstanceId, DateTime? newExpiry, string reason);

    /// <summary>
    /// SPM-89 — directly grant a PACKAGE product to a client as a FREE COMP GRANT.
    /// Loads the chosen PACKAGE <see cref="Product"/> and mints a <see cref="ClientPackage"/>
    /// from its <c>Credits</c> / <c>ValidityDays</c>, mirroring the provisioning logic in
    /// <c>InvoiceService.ProvisionPackagesFromInvoiceAsync</c> (including <c>ValidityDays == 0</c>
    /// =&gt; never-expires, per the SPM-38 fix). No invoice, payment, or revenue is created.
    /// A mandatory <paramref name="reason"/> is written to the governance <see cref="AuditLog"/>
    /// using the same <see cref="IAuditLogger"/> pattern as the adjust-credit path. Returns the
    /// minted package on success, or <c>null</c> when the product is not found or is not a PACKAGE.
    /// </summary>
    Task<ClientPackage?> GrantPackageAsync(string clientId, string productId, string reason);
}

