//      the PackageLedgerLog entries are written in lock-step with
//      the wallet state — the same code path admins use.
if (paymentMethod == "PACKAGE_CREDIT")
{
    var quantityNeeded = Math.Max(1, attendance.Quantity);

    // SPM-108: the pre-flight wallet read MUST match the wallet set
    // DeductCreditAsync actually decrements, otherwise the two can
    // disagree on the boundary case. A wallet with its LAST credit(s)
    // has Status == "LOW_BALANCE" (set by DeductCreditAsync once
    // CreditsRemaining <= 2), NOT "ACTIVE". The previous inline filter
    // here only accepted "ACTIVE", so a customer's final credit was
    // invisible to this pre-flight: totalCredits came back 0, this
    // method threw INSUFFICIENT_CREDITS, and the attendance was left
    // stranded in RESERVED (never promoted to BOOKED, no credit spent).
    // Delegate to the canonical active-wallet query (ACTIVE +
    // LOW_BALANCE, expiry-aware, FIFO-sorted) — the exact same query
    // DeductCreditAsync walks — so the two stay in lock-step.
    // Duo Private packages — a PRIVATE booking for 2 seats prefers a dedicated
    // DUO-format package (1 credit) over 2 credits from a regular PRIVATE
    // package. Every other format/quantity resolves to itself unchanged.
    // The pre-flight read below and the DeductCreditAsync call MUST both use
    // this resolved (format, quantity) so they never disagree (SPM-108 lesson).
    (var creditFormat, quantityNeeded) = await _walletService
        .ResolveBookingCreditBucketAsync(attendance.ClientId, session.Format, quantityNeeded);

    var activeWallets = (await _walletService
        .GetActivePackagesForClientAsync(attendance.ClientId, creditFormat))
        .ToList();
    var totalCredits = activeWallets.Sum(p => p.CreditsRemaining);
    if (totalCredits < quantityNeeded)
        throw new InvalidOperationException(
            $"BOOKING.INSUFFICIENT_CREDITS — {quantityNeeded} credit(s) required but only {totalCredits} available.");

    // Pick the oldest-expiring wallet as the "primary" refund target.
    // WalletService.RefundCreditByAttendanceAsync walks the ledger
    // so a deduction that spans more than one wallet is still fully
    // reversed on cancel; this field is just a fast-path hint and a
    // legacy compatibility shim for existing single-wallet refund code.
    // Order by soonest-expiring first; never-expiring (null) wallets sort
    // last so an open-ended package isn't burned before a dated one.
    var primaryWallet = activeWallets
        .OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue)
        .First();

    var deducted = await _walletService.DeductCreditAsync(
        attendance.ClientId,
        creditFormat,
        attendanceId,
        quantityNeeded);
    if (!deducted)
        throw new InvalidOperationException(
            "BOOKING.CREDIT_DEDUCTION_FAILED — wallet state changed during checkout, please retry.");

    // Persist payment method + amounts + the wallet hint in a single

    // Persist payment method + amounts + the wallet hint in a single
    // round-trip so we don't leave an attendance with a missing
    // PackageInstanceId if the next write fails.
    var creditUpdate = Builders<Attendance>.Update
        .Set(a => a.PaymentMethod, paymentMethod)
        .Set(a => a.AmountPaid, 0m)
        .Set(a => a.AmountDueAtStudio, quote.AmountDueAtStudio)
        .Set(a => a.PackageInstanceId, primaryWallet.Id);
    await _attendances.UpdateOneAsync(a => a.Id == attendanceId, creditUpdate);

    await _audit.LogAsync(
        action: "PACKAGE_CREDIT_DEDUCTED",
        entityType: "Attendance",
        entityId: attendanceId,
        after: new
        {
            attendance.ClientId,
            Format = session.Format,
            Quantity = quantityNeeded,
            PrimaryWalletId = primaryWallet.Id
        });
}
else
{
    // Non-PACKAGE_CREDIT methods persist the chosen method + the studio
    // balance. AmountPaid stays 0 here: for Stripe the money hasn't been
    // charged yet (it's set to the real charged amount in MarkSucceededAsync
    // on payment success), and for PAY_AT_STUDIO nothing is paid online.
    // Setting it to AmountDueNow up-front stamped a phantom "deposit paid"
    // on bookings the customer later abandoned at checkout.
    var attUpdate = Builders<Attendance>.Update
        .Set(a => a.PaymentMethod, paymentMethod)
        .Set(a => a.AmountPaid, 0m)
        .Set(a => a.AmountDueAtStudio, quote.AmountDueAtStudio);
    await _attendances.UpdateOneAsync(a => a.Id == attendanceId, attUpdate);
}

// No charge needed for credit-only or studio-only flows
if (quote.AmountDueNow == 0)
