const monthsLeft = expiry
  ? Math.max(0, Math.round((expiry.getTime() - Date.now()) / (1000 * 60 * 60 * 24 * 30)))
  : null;

// SPM-121: no expiry date means an open-ended package — render nothing
// rather than "No expiry", which reads as "not valid".
const subText = expiry
  ? (p.status === "EXPIRED" ? `Expired ${expiryStr}` : `Valid until ${expiryStr}`)
  : "";

const fmt = (p.format || "GROUP").toUpperCase();
const fmtColor = fmt === "PRIVATE" ? "#f59e0b" : "#6366f1";

// Short ID for display: last 8 chars of the MongoDB ObjectId
const rawId = String(p.id || p._id || "");
const shortId = rawId.length > 8 ? rawId.slice(-8) : rawId;

return `
<div
  class="sp-pkg-item"
  data-pkg-id="${escapeHtml(rawId)}"
  role="button" tabindex="0" aria-expanded="false"
>
  <!-- Compact row -->
  <div class="sp-pkg-row-header">
    <span class="sp-pkg-format-tag">
      <span class="sp-fmt-dot" style="background:${fmtColor};"></span>
      ${escapeHtml(fmt)}
    </span>
    <div class="sp-pkg-row-meta">

