    if (isCredit)
    {
        // SPM-98 duo upgrade — growing a 1-seat PRIVATE credit booking to 2 seats.
        // The original booking already spent `current` (1) credit from whichever
        // wallet is stamped as att.PackageInstanceId. If the client holds an active
        // Duo Private package, migrate the WHOLE booking onto it: refund the credit
        // already spent back to its exact source wallet, then spend exactly 1 Duo
        // Private credit for the whole 2-person class — instead of just debiting a
        // 2nd Private credit. Falls back to the plain incremental-Private-credit
        // path below when no Duo package is available, or the migration can't be
        // completed safely (e.g. the source wallet is now frozen/expired).
        var migratedToDuo = false;
        if (isPrivate && newQuantity == 2 && !string.IsNullOrWhiteSpace(att.PackageInstanceId))
        {
            var duoPackages = (await _walletService.GetActivePackagesForClientAsync(att.ClientId, "DUO")).ToList();
            var duoPrimary = duoPackages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).FirstOrDefault();
            if (duoPrimary != null)
            {
                var restored = await _walletService.AdjustCreditAsync(
                    att.PackageInstanceId, current,
                    "SPM-98 duo upgrade — refunding the original Private credit ahead of migrating to a Duo Private package.");
                if (restored)
                {
                    var duoOk = await _walletService.DeductCreditAsync(att.ClientId, "DUO", att.Id!, 1);
                    if (duoOk)
                    {
                        migratedToDuo = true;
                        await _attendances.UpdateOneAsync(a => a.Id == att.Id,
