        if (isPrivate && newQuantity == 2 && !string.IsNullOrWhiteSpace(att.PackageInstanceId))
        {
            var duoPackages = (await _walletService.GetActivePackagesForClientAsync(att.ClientId, "DUO")).ToList();
            var duoPrimary = duoPackages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).FirstOrDefault();
            if (duoPrimary != null)
            {
                var restored = await _walletService.AdjustCreditAsync(
                    att.PackageInstanceId, current,
                    "SPM-98 duo upgrade — refunding the original Private credit ahead of migrating to a Duo Private package.");
                if (restored)
                {
                    var duoOk = await _walletService.DeductCreditAsync(att.ClientId, "DUO", att.Id!, 1);
                    if (duoOk)
                    {
                        migratedToDuo = true;
                        await _attendances.UpdateOneAsync(a => a.Id == att.Id,
                            Builders<Attendance>.Update.Set(a => a.PackageInstanceId, duoPrimary.Id));
                    }
                    else
                    {
                        // Race: the Duo package was depleted between the check above and
                        // this deduction. Put the original Private credit back so the
                        // client isn't left worse off, then fall through to the normal path.
                        await _walletService.AdjustCreditAsync(
                            att.PackageInstanceId, -current,
                            "SPM-98 duo upgrade — Duo Private deduction failed, reverting to the original Private credit.");
                    }
                }
            }
        }

        if (!migratedToDuo)
        {
            // Debit the additional credits for the extra seats. DeductCreditAsync is
            // atomic: it returns false with NO partial deduction when the wallet
            // can't cover `delta`, so we roll the seat claim back and abort.
            var ok = await _walletService.DeductCreditAsync(
                att.ClientId, session.Format, "qty-adjust-" + att.Id, delta);
            if (!ok)
            {
                await ReleaseSessionCapacityAsync(sessionId, delta);
                throw new BusinessRuleException("BOOKING.CREDIT_DEDUCTION_FAILED",
                    "Not enough package credits to add the extra seat(s). Collect the difference another way.");
            }
        }
    }
}
else // delta < 0 — releasing seats
{
    // Guard: a booking currently funded by a Duo Private credit can't be shrunk here
    // — a Duo credit pays for the whole 2-person class, so a blind partial refund
    // would hand back the full credit while leaving the remaining seat free (a
    // revenue leak). Refuse and point staff at remove-and-re-add instead, mirroring
    // the ALREADY_PAID guard above.
    if (isCredit && isPrivate && newQuantity == 1 && !string.IsNullOrWhiteSpace(att.PackageInstanceId))
    {
        var currentPkg = await _walletService.GetPackageByIdAsync(att.PackageInstanceId);
        if (currentPkg != null && string.Equals(currentPkg.Format, "DUO", StringComparison.OrdinalIgnoreCase))
            throw new BusinessRuleException("BOOKING.DUO_CREDIT_CANNOT_SHRINK",
                "This booking is paid with a Duo Private credit, which covers the full 2-person class. Remove and re-add to drop to a single seat.");
    }

    await _sessions.UpdateOneAsync(s => s.Id == sessionId,
        Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, delta));
    await _sessions.UpdateOneAsync(
        s => s.Id == sessionId && s.CurrentBookings < 0,
        Builders<CalendarSession>.Update.Set(s => s.CurrentBookings, 0));
    // Refund the freed seats' credits (ledger-driven partial refund).
    if (isCredit)
        await _walletService.RefundPartialCreditByAttendanceWithTrailAsync(att.Id!, -delta);
}

