/// <inheritdoc />
public async Task<decimal> CalculateTotalCommissionsAsync(DateTime start, DateTime end)
{
    // Mirror CalculatePayrollAsync's session scope, but don't persist a run.
    var sessions = await _sessions
        .Find(s => s.StartTime >= start && s.StartTime <= end
                && s.Status == "COMPLETED"
                && s.Origin != "BLOCK")
        .ToListAsync();

    decimal total = 0m;
    foreach (var group in sessions.GroupBy(s => s.InstructorId))
    {
        var instructorId = group.Key;
        if (string.IsNullOrEmpty(instructorId)) continue;

        var staff = await _staff.Find(s => s.Id == instructorId).FirstOrDefaultAsync();
        if (staff is null) continue;

        var revision = await _revisions.ResolveAsOfAsync(staff.Id!, end);
        revision = await ApplyCommissionOverrideAsync(staff.Id!, end, revision);

        var result = await AggregateInstructorAsync(staff, revision, group.ToList());
        total += result.GroupClassEarnings + result.PrivateClassEarnings;
    }
    return total;
}

/// <summary>
/// Checks whether a <see cref="MonthlyCommissionOverride"/> exists for the
/// given staff member in the calendar month containing <paramref name="periodEnd"/>.
/// If one is found, its fields are merged into a copy of <paramref name="baseRevision"/>
/// (or a fresh synthetic revision if none exists) so the downstream
/// <see cref="AggregateInstructorAsync"/> never needs to know the difference.
/// </summary>
private async Task<StaffRateRevision?> ApplyCommissionOverrideAsync(
    string staffId, DateTime periodEnd, StaffRateRevision? baseRevision)
{
    var year = periodEnd.Year;
    var month = periodEnd.Month;

    var ovr = await _commissionOverrides
        .Find(o => o.StaffId == staffId && o.Year == year && o.Month == month)
        .FirstOrDefaultAsync();

    if (ovr is null) return baseRevision;

    // Build a synthetic revision that inherits non-commission fields from
    // the base revision (so BaseSalary, headcount rates, etc. are still
    // version-controlled by the revision ledger) and overrides only the
    // commission-specific fields.
    var merged = baseRevision is not null
        ? new StaffRateRevision
        {
            Id = baseRevision.Id,
            StaffId = baseRevision.StaffId,
            StaffNameSnapshot = baseRevision.StaffNameSnapshot,
            EffectiveFrom = baseRevision.EffectiveFrom,
            ChangeNote = $"[Override applied for {year}-{month:D2}] " + baseRevision.ChangeNote,
            IsBootstrap = baseRevision.IsBootstrap,

            // Commission fields — from the override.
            CommissionModel = ovr.CommissionModel,
            Tiers = ovr.Tiers.Select(t => new CommissionTier
            {
                MinClasses = t.MinClasses,
                MaxClasses = t.MaxClasses,
                CommissionPercentage = t.CommissionPercentage,
            }).ToList(),
            HasTieredPrivateCommission = ovr.HasTieredPrivateCommission,
            FlatPrivateCommissionPct = ovr.FlatPrivateCommissionPct,
            GroupFlatRatePerClass = ovr.GroupFlatRatePerClass,
            GroupRatePerHead = ovr.GroupRatePerHead,
            FreeGroupClassRate = ovr.FreeGroupClassRate,
            FreePrivateClassRate = ovr.FreePrivateClassRate,
            RatePerHead = ovr.RatePerHead,
            HeadcountTiers = ovr.HeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            PrivateRatePerHead = ovr.PrivateRatePerHead,
            PrivateHeadcountTiers = ovr.PrivateHeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            UseMarginalHeadcountTiers = ovr.UseMarginalHeadcountTiers,

            // Non-commission fields — from the base revision.
            BaseSalary = baseRevision.BaseSalary,
            BaseRate = baseRevision.BaseRate,
        }
        : new StaffRateRevision
        {
            StaffId = staffId,
            EffectiveFrom = periodEnd,
            ChangeNote = $"[Synthetic from override for {year}-{month:D2}]",

            CommissionModel = ovr.CommissionModel,
            Tiers = ovr.Tiers.Select(t => new CommissionTier
            {
                MinClasses = t.MinClasses,
                MaxClasses = t.MaxClasses,
                CommissionPercentage = t.CommissionPercentage,
            }).ToList(),
            HasTieredPrivateCommission = ovr.HasTieredPrivateCommission,
            FlatPrivateCommissionPct = ovr.FlatPrivateCommissionPct,
            GroupFlatRatePerClass = ovr.GroupFlatRatePerClass,
            GroupRatePerHead = ovr.GroupRatePerHead,
            FreeGroupClassRate = ovr.FreeGroupClassRate,
            FreePrivateClassRate = ovr.FreePrivateClassRate,
            RatePerHead = ovr.RatePerHead,
            HeadcountTiers = ovr.HeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            PrivateRatePerHead = ovr.PrivateRatePerHead,
            PrivateHeadcountTiers = ovr.PrivateHeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            UseMarginalHeadcountTiers = ovr.UseMarginalHeadcountTiers,
            BaseSalary = ovr.BaseSalary,
            BaseRate = ovr.BaseRate,
        };

    return merged;
}

