/// Snapshot-driven counterpart of <see cref="ResolvePrivateCommissionRate"/>.
/// Reads only from the <see cref="InstructorPayrollResult"/> snapshot block
/// so historical re-runs are guaranteed to reproduce the original rate even
/// after the live <see cref="Staff"/> document has been edited.
/// </summary>
private static decimal ResolvePrivateCommissionRateFromSnapshot(InstructorPayrollResult r, int privateClassCount)
{
    if (!r.HasTieredPrivateCommissionSnapshot || r.TiersSnapshot.Count == 0)
    {
        return NormalizeCommissionPct(r.FlatPrivateCommissionPctSnapshot);
    }
    var matching = r.TiersSnapshot
        .Where(t => privateClassCount >= t.MinClasses
                 && (!t.MaxClasses.HasValue || privateClassCount <= t.MaxClasses.Value))
        .OrderByDescending(t => t.CommissionPercentage)
        .FirstOrDefault();
    return NormalizeCommissionPct(matching?.CommissionPercentage ?? r.FlatPrivateCommissionPctSnapshot);
}

