using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace SoulPilates.API.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor,Accountant")]
public class InvoiceController : ControllerBase
{
    private readonly IInvoiceService _invoiceService;

    public InvoiceController(IInvoiceService invoiceService)
    {
        _invoiceService = invoiceService;
    }

    /// <summary>
    /// Returns the N most recent invoices for the dashboard widget.
    /// Joins client names and product names server-side for efficiency.
    /// </summary>
    [HttpGet("recent")]
    public async Task<IActionResult> GetRecent([FromQuery] int limit = 5)
    {
        if (limit < 1) limit = 1;
        if (limit > 20) limit = 20;
        var result = await _invoiceService.GetRecentInvoicesAsync(limit);
        return Ok(result);
    }

    /// <summary>
    /// Create a new invoice + lines. The wire shape intentionally omits
    /// server-stamped fields like <c>InvoiceNumber</c> (generated by the
    /// service) and <c>InvoiceLine.InvoiceId</c> (back-filled after insert).
    /// Binding straight to <see cref="Invoice"/> would force callers to send
    /// those fields purely to satisfy ASP.NET's non-nullable string
    /// validators, which surfaces as a confusing 400 at the POS.
    /// </summary>
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateInvoiceRequest req)
    {
        if (req is null) return BadRequest(new { error = "Body is required." });
        if (string.IsNullOrWhiteSpace(req.ClientId)) return BadRequest(new { error = "clientId is required." });
        if (req.Lines is null || req.Lines.Count == 0) return BadRequest(new { error = "At least one line is required." });

        var invoice = new Invoice
        {
            ClientId = req.ClientId,
            // Either name is accepted on the wire; the server canonicalises
            // onto Invoice.RefereePartnerId. The POS today sends
            // refereeClientId for historical reasons; future callers should
            // prefer refereePartnerId.
            RefereePartnerId = string.IsNullOrWhiteSpace(req.RefereePartnerId) ? req.RefereeClientId : req.RefereePartnerId,
            TotalDiscount = req.DiscountAmount ?? 0m,
            TotalTax = req.TaxAmount ?? 0m,
            IssueDate = req.IssueDate ?? DateTime.UtcNow,
            Notes = req.Notes,
            Lines = req.Lines.Select(l => new InvoiceLine
            {
                ProductId = l.ProductId,
                VariantId = string.IsNullOrWhiteSpace(l.VariantId) ? null : l.VariantId,
                Quantity = l.Quantity,
                UnitPrice = l.UnitPrice,
                LineDiscount = l.LineDiscount ?? 0m,
                AttendanceId = string.IsNullOrWhiteSpace(l.AttendanceId) ? null : l.AttendanceId,
                CalendarSessionId = string.IsNullOrWhiteSpace(l.CalendarSessionId) ? null : l.CalendarSessionId,
                // Description is informational on the receipt; the entity
                // does not persist it today, so we discard cleanly.
            }).ToList(),
        };

        var result = await _invoiceService.CreateInvoiceAsync(invoice);
        return Ok(result);
    }

    [HttpPost("{id}/payment")]
    public async Task<IActionResult> AddPayment(string id, [FromBody] AddPaymentRequest req)
    {
        if (req is null) return BadRequest(new { error = "Body is required." });
        if (req.AmountPaid <= 0m) return BadRequest(new { error = "amountPaid must be greater than zero." });

        // Split tender: record one Payment ledger row per {method, amount} line,
        // validated to sum to AmountPaid, so a single order paid across multiple
        // methods credits each income stream its real share. When no split is
        // supplied the payment is recorded once via PaymentMethod as before.
