1	using Microsoft.AspNetCore.Authorization;
2	using Microsoft.AspNetCore.Mvc;
3	using MongoDB.Driver;
4	using SoulPilates.Core.Entities;
5	using SoulPilates.Core.Interfaces;
6	using SoulPilates.Infrastructure.Data;
7	using System;
8	using System.Linq;
9	using System.Security.Claims;
10	using System.Threading.Tasks;
11	
12	namespace SoulPilates.API.Controllers;
13	
14	/// <summary>
15	/// Customer-facing package purchase flow (Issue #1).
16	/// <para>
17	/// All write endpoints are gated behind the <c>Customer</c> role — there are
18	/// no guest purchases. The flow is:
19	/// </para>
20	/// <list type="number">
21	///   <item>
22	///     <description>
23	///       <c>POST /api/package-purchase/checkout</c> — creates a draft
24	///       <see cref="Invoice"/> for the chosen product and returns a Stripe
25	///       <c>client_secret</c> via <see cref="IPaymentService.CreatePackagePurchaseIntentAsync"/>.
26	///     </description>
27	///   </item>
28	///   <item>
29	///     <description>
30	///       <c>POST /api/package-purchase/confirm</c> — dev-mode fallback that
31	///       finalises the invoice when Stripe is disabled. In production this
32	///       path is exercised only by the local-preview UI; the real money path
33	///       is the Stripe webhook firing <c>payment_intent.succeeded</c>.
34	///     </description>
35	///   </item>
36	/// </list>
37	/// <para>
38	/// Featured-package discovery (Issue #4 home-page strip) is served via the
39	/// existing public <c>GET /api/products/packages</c>; this controller exposes
40	/// a thin <c>GET /featured</c> alias that pre-filters on
41	/// <see cref="Product.IsFeatured"/>.
42	/// </para>
43	/// </summary>
44	[ApiController]
45	[Route("api/package-purchase")]
46	public class PackagePurchaseController : ControllerBase
47	{
48	    private readonly IProductService _productService;
49	    private readonly IInvoiceService _invoiceService;
50	    private readonly IPaymentService _paymentService;
51	    private readonly ISettingsService _settingsService;
52	    private readonly IMongoCollection<Invoice> _invoices;
53	    private readonly IAuditLogger _audit;
54	
55	    public PackagePurchaseController(
56	        IProductService productService,
57	        IInvoiceService invoiceService,
58	        IPaymentService paymentService,
59	        ISettingsService settingsService,
60	        MongoDbContext db,
61	        IAuditLogger audit)
62	    {
63	        _productService = productService;
64	        _invoiceService = invoiceService;
65	        _paymentService = paymentService;
66	        _settingsService = settingsService;
67	        _invoices = db.GetCollection<Invoice>("Invoices");
68	        _audit = audit;
69	    }
70	
71	    /// <summary>
72	    /// Featured-package strip data for the home page (Issue #4).
73	    /// </summary>
74	    [HttpGet("featured")]
75	    [AllowAnonymous]
76	    public async Task<IActionResult> Featured()
77	    {
78	        var products = await _productService.GetAllProductsAsync();
79	
80	        // Drop-in reference prices per format, taken from the SINGLE_CLASS
81	        // products (e.g. "Single Group Class" 500k, "Single Private Class" 850k).
82	        // Used to show the drop-in price and compute each package's savings.
83	        decimal DropInFor(string? format)
84	        {
85	            var single = products.FirstOrDefault(p =>
86	                p.IsActive && p.Type == "SINGLE_CLASS" &&
87	                string.Equals(p.FormatRestriction, format, StringComparison.OrdinalIgnoreCase));
88	            return single?.BasePrice ?? 0m;
89	        }
90	
91	        var featured = products
92	            .Where(p => p.IsActive && !p.HiddenFromOnline && p.IsFeatured && p.Type == "PACKAGE")
93	            .OrderBy(p => p.BasePrice)
94	            .Select(p =>
95	            {
96	                var perClass = p.Credits > 0 ? Math.Round(p.BasePrice / p.Credits) : p.BasePrice;
97	                var dropIn = DropInFor(p.FormatRestriction);
98	                var savePercent = (dropIn > 0 && perClass < dropIn)
99	                    ? (int)Math.Round((1 - (perClass / dropIn)) * 100)
100	                    : 0;
101	                return new
102	                {
103	                    id = p.Id,
104	                    name = p.Name,
105	                    description = p.Description,
106	                    formatRestriction = p.FormatRestriction,
107	                    basePrice = p.BasePrice,
108	                    credits = p.Credits,
109	                    validityDays = p.ValidityDays,
110	                    pricePerClass = perClass,
111	                    dropInPrice = dropIn,
112	                    savePercent,
113	                    freeSocks = p.FreeSocks,
114	                    includesFreePrivateClass = p.IncludesFreePrivateClass,
115	                };
116	            });
117	        return Ok(featured);
118	    }
119	
120	    /// <summary>
121	    /// Create a draft invoice for the chosen package and a Stripe PaymentIntent
122	    /// to settle it. Auth-gated to the <c>Customer</c> role — no guests.
123	    /// </summary>
124	    [HttpPost("checkout")]
125	    [Authorize(Roles = "Customer")]
126	    public async Task<IActionResult> Checkout([FromBody] CheckoutRequest request)
127	    {
128	        if (string.IsNullOrWhiteSpace(request.ProductId))
129	            return BadRequest(new { message = "productId is required." });
130	
131	        var clientId = User.FindFirstValue("clientId");
132	        if (string.IsNullOrWhiteSpace(clientId))
133	            return Unauthorized(new { message = "Customer account not linked to a client." });
134	
135	        var product = await _productService.GetProductByIdAsync(request.ProductId);
136	        if (product == null) return NotFound(new { message = "Package not found." });
137	
138	        // Only PACKAGE products can go through the customer purchase flow.
139	        // MERCHANDISE must be sold via the POS.
140	        if (product.Type != "PACKAGE")
141	            return BadRequest(new { message = "Only PACKAGE products can be purchased through this flow." });
142	        if (!product.IsActive)
143	            return BadRequest(new { message = "This package is no longer available." });
144	        if (product.HiddenFromOnline)
145	            return BadRequest(new { message = "This package is no longer available." });
146	        if (product.BasePrice <= 0)
147	            return BadRequest(new { message = "Package has no purchasable price." });
148	
149	        // Build the draft invoice. PARTIAL is intentional rather than UNPAID —
150	        // it mirrors the POS shape so AddPaymentAsync can later flip it to PAID
151	        // via the standard provisioning path. ProductTypeSnapshot is stamped by
152	        // InvoiceService.CreateInvoiceAsync so historical washouts stay correct.
153	        // Online payment fee (VAT, online only) — same surcharge customers pay on
154	        // online class bookings. Applied to the package price; CreateInvoiceAsync
155	        // folds OnlineFeeAmount into TotalNet, so the customer is billed base + VAT
156	        // and the receipt itemises it.
157	        var feePct = (await _settingsService.GetAsync()).OnlinePaymentFeePercentage;
158	        var onlineFee = feePct > 0 ? Math.Round(product.BasePrice * feePct / 100m) : 0m;
159	
160	        var invoice = new Invoice
161	        {
162	            ClientId = clientId,
163	            IssueDate = DateTime.UtcNow,
164	            Status = "PENDING",
165	            Notes = $"Online package purchase — {product.Name}",
166	            OnlineFeeAmount = onlineFee,
167	            Lines = new System.Collections.Generic.List<InvoiceLine>
168	            {
169	                new InvoiceLine
170	                {
171	                    ProductId = product.Id!,
172	                    Quantity = 1,
173	                    UnitPrice = product.BasePrice,
174	                    LineDiscount = 0,
175	                    LineTotal = product.BasePrice,
176	                }
177	            }
178	        };
179	
180	        var created = await _invoiceService.CreateInvoiceAsync(invoice);
181	
182	        // Hand off to PaymentService — it handles dev-mode mocks, Stripe live,
183	        // audit logging, and metadata routing for the webhook.
184	        var intent = await _paymentService.CreatePackagePurchaseIntentAsync(created.Id!);
185	
186	        await _audit.LogAsync(
187	            action: "PACKAGE_PURCHASE_CHECKOUT",
188	            entityType: "Invoice",
189	            entityId: created.Id!,
190	            entityLabel: created.InvoiceNumber,
191	            metadata: new { product.Id, product.Name, product.BasePrice, clientId });
192	
193	        return Ok(new
194	        {
195	            invoiceId = created.Id,
196	            invoiceNumber = created.InvoiceNumber,
197	            paymentIntentId = intent.PaymentIntentId,
198	            clientSecret = intent.ClientSecret,
199	            useEmbeddedCheckout = intent.UseEmbeddedCheckout,
200	            checkoutSessionId = intent.CheckoutSessionId,
201	            amount = intent.Amount,
202	            baseAmount = intent.SessionFee,
203	            feeAmount = intent.FeeAmount,
204	            feePercentage = intent.FeePercentage,
205	            currency = intent.Currency,
206	            publishableKey = intent.PublishableKey,
207	            productName = product.Name,
208	            credits = product.Credits,
209	            validityDays = product.ValidityDays,
210	        });
211	    }
212	
213	    /// <summary>
214	    /// Dev-mode confirm hook — called by the front-end after the mock Stripe
215	    /// Elements promise resolves. In production this is a NO-OP because the
216	    /// real Stripe webhook fires <c>payment_intent.succeeded</c> and the
217	    /// webhook handler invokes <see cref="IPaymentService.MarkInvoicePaidAsync"/>
218	    /// directly. We deliberately accept the <c>invoiceId</c> from the client
219	    /// (and re-verify ownership against the JWT) because mock intents don't
220	    /// have Metadata we can recover the invoiceId from.
221	    /// </summary>
222	    [HttpPost("confirm")]
223	    [Authorize(Roles = "Customer")]
224	    public async Task<IActionResult> Confirm([FromBody] ConfirmRequest request)
225	    {
226	        if (string.IsNullOrWhiteSpace(request.InvoiceId))
227	            return BadRequest(new { message = "invoiceId is required." });
228	        if (string.IsNullOrWhiteSpace(request.PaymentIntentId))
229	            return BadRequest(new { message = "paymentIntentId is required." });
230	
231	        var clientId = User.FindFirstValue("clientId");
232	        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();
233	
234	        // Defence-in-depth: confirm that the JWT principal owns this invoice
235	        // before we let them flip it to PAID. Without this, a logged-in
236	        // customer could in theory settle someone else's pending invoice.
237	        var invoice = await _invoices.Find(i => i.Id == request.InvoiceId).FirstOrDefaultAsync();
238	        if (invoice == null) return NotFound(new { message = "Invoice not found." });
239	        if (invoice.ClientId != clientId)
240	            return StatusCode(403, new { message = "Invoice does not belong to this customer." });
241	
242	        // For real Stripe intents, MarkInvoicePaidAsync recovers the invoiceId
243	        // from intent.Metadata and is the safe path. For mock intents we route
244	        // through the internal helper.
245	        bool ok;
246	        if (request.PaymentIntentId.StartsWith("pi_pkg_mock_", StringComparison.Ordinal))
247	        {
248	            ok = await _paymentService.MarkInvoicePaidByIdAsync(request.InvoiceId, request.PaymentIntentId);
249	        }
250	        else
251	        {
252	            ok = await _paymentService.MarkInvoicePaidAsync(request.PaymentIntentId);
253	        }
254	
255	        return Ok(new { success = ok });
256	    }
257	
258	    public class CheckoutRequest
259	    {
260	        public string ProductId { get; set; } = null!;
261	    }
262	
263	    public class ConfirmRequest
264	    {
265	        public string InvoiceId { get; set; } = null!;
266	        public string PaymentIntentId { get; set; } = null!;
267	    }
268	}
269

