/// <summary>
/// Customer-facing package purchase flow (Issue #1).
/// <para>
/// All write endpoints are gated behind the <c>Customer</c> role — there are
/// no guest purchases. The flow is:
/// </para>
/// <list type="number">
///   <item>
///     <description>
///       <c>POST /api/package-purchase/checkout</c> — creates a draft
///       <see cref="Invoice"/> for the chosen product and returns a Stripe
///       <c>client_secret</c> via <see cref="IPaymentService.CreatePackagePurchaseIntentAsync"/>.
///     </description>
///   </item>
///   <item>
///     <description>
///       <c>POST /api/package-purchase/confirm</c> — dev-mode fallback that
///       finalises the invoice when Stripe is disabled. In production this
///       path is exercised only by the local-preview UI; the real money path
///       is the Stripe webhook firing <c>payment_intent.succeeded</c>.
///     </description>
///   </item>
/// </list>
