/// existing public <c>GET /api/products/packages</c>; this controller exposes
/// a thin <c>GET /featured</c> alias that pre-filters on
/// <see cref="Product.IsFeatured"/>.
/// </para>
/// </summary>
[ApiController]
[Route("api/package-purchase")]
public class PackagePurchaseController : ControllerBase
{
    private readonly IProductService _productService;
    private readonly IInvoiceService _invoiceService;
    private readonly IPaymentService _paymentService;
    private readonly ISettingsService _settingsService;
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IAuditLogger _audit;

    public PackagePurchaseController(
        IProductService productService,
        IInvoiceService invoiceService,
        IPaymentService paymentService,
        ISettingsService settingsService,
        MongoDbContext db,
        IAuditLogger audit)
    {
        _productService = productService;
        _invoiceService = invoiceService;
        _paymentService = paymentService;
        _settingsService = settingsService;
        _invoices = db.GetCollection<Invoice>("Invoices");
        _audit = audit;
    }

    /// <summary>
    /// Featured-package strip data for the home page (Issue #4).
    /// </summary>
    [HttpGet("featured")]
    [AllowAnonymous]
    public async Task<IActionResult> Featured()
    {
        var products = await _productService.GetAllProductsAsync();

        // Drop-in reference prices per format, taken from the SINGLE_CLASS
        // products (e.g. "Single Group Class" 500k, "Single Private Class" 850k).
        // Used to show the drop-in price and compute each package's savings.
        decimal DropInFor(string? format)
        {
            var single = products.FirstOrDefault(p =>
                p.IsActive && p.Type == "SINGLE_CLASS" &&
                string.Equals(p.FormatRestriction, format, StringComparison.OrdinalIgnoreCase));
            return single?.BasePrice ?? 0m;
        }

        var featured = products
            .Where(p => p.IsActive && !p.HiddenFromOnline && p.IsFeatured && p.Type == "PACKAGE")
            .OrderBy(p => p.BasePrice)
            .Select(p =>
            {
                var perClass = p.Credits > 0 ? Math.Round(p.BasePrice / p.Credits) : p.BasePrice;
                var dropIn = DropInFor(p.FormatRestriction);
                var savePercent = (dropIn > 0 && perClass < dropIn)
                    ? (int)Math.Round((1 - (perClass / dropIn)) * 100)
                    : 0;
                return new
                {
                    id = p.Id,
                    name = p.Name,
                    description = p.Description,
                    formatRestriction = p.FormatRestriction,
                    basePrice = p.BasePrice,
                    credits = p.Credits,
                    validityDays = p.ValidityDays,
                    pricePerClass = perClass,
                    dropInPrice = dropIn,
                    savePercent,
                    freeSocks = p.FreeSocks,
                    includesFreePrivateClass = p.IncludesFreePrivateClass,
                };
            });
        return Ok(featured);
    }

    /// <summary>
    /// Create a draft invoice for the chosen package and a Stripe PaymentIntent
    /// to settle it. Auth-gated to the <c>Customer</c> role — no guests.
    /// </summary>
    [HttpPost("checkout")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> Checkout([FromBody] CheckoutRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.ProductId))
            return BadRequest(new { message = "productId is required." });

        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId))
            return Unauthorized(new { message = "Customer account not linked to a client." });

        var product = await _productService.GetProductByIdAsync(request.ProductId);
        if (product == null) return NotFound(new { message = "Package not found." });

        // Only PACKAGE products can go through the customer purchase flow.
        // MERCHANDISE must be sold via the POS.
        if (product.Type != "PACKAGE")
            return BadRequest(new { message = "Only PACKAGE products can be purchased through this flow." });
        if (!product.IsActive)
            return BadRequest(new { message = "This package is no longer available." });
        if (product.HiddenFromOnline)
            return BadRequest(new { message = "This package is no longer available." });
        if (product.BasePrice <= 0)
            return BadRequest(new { message = "Package has no purchasable price." });

        // Build the draft invoice. PARTIAL is intentional rather than UNPAID —
        // it mirrors the POS shape so AddPaymentAsync can later flip it to PAID
        // via the standard provisioning path. ProductTypeSnapshot is stamped by
        // InvoiceService.CreateInvoiceAsync so historical washouts stay correct.
        // Online payment fee (VAT, online only) — same surcharge customers pay on
        // online class bookings. Applied to the package price; CreateInvoiceAsync
        // folds OnlineFeeAmount into TotalNet, so the customer is billed base + VAT
        // and the receipt itemises it.
        var feePct = (await _settingsService.GetAsync()).OnlinePaymentFeePercentage;
        var onlineFee = feePct > 0 ? Math.Round(product.BasePrice * feePct / 100m) : 0m;

        var invoice = new Invoice
        {
            ClientId = clientId,
            IssueDate = DateTime.UtcNow,
            Status = "PENDING",
            Notes = $"Online package purchase — {product.Name}",
            OnlineFeeAmount = onlineFee,
            Lines = new System.Collections.Generic.List<InvoiceLine>
            {
                new InvoiceLine
                {
                    ProductId = product.Id!,
                    Quantity = 1,
                    UnitPrice = product.BasePrice,
                    LineDiscount = 0,
                    LineTotal = product.BasePrice,
                }
            }
        };

        var created = await _invoiceService.CreateInvoiceAsync(invoice);

        // Hand off to PaymentService — it handles dev-mode mocks, Stripe live,
        // audit logging, and metadata routing for the webhook.
        var intent = await _paymentService.CreatePackagePurchaseIntentAsync(created.Id!);

        await _audit.LogAsync(
            action: "PACKAGE_PURCHASE_CHECKOUT",
            entityType: "Invoice",
            entityId: created.Id!,
            entityLabel: created.InvoiceNumber,
            metadata: new { product.Id, product.Name, product.BasePrice, clientId });

        return Ok(new
        {
            invoiceId = created.Id,
            invoiceNumber = created.InvoiceNumber,
            paymentIntentId = intent.PaymentIntentId,
            clientSecret = intent.ClientSecret,
            useEmbeddedCheckout = intent.UseEmbeddedCheckout,
            checkoutSessionId = intent.CheckoutSessionId,
            amount = intent.Amount,
            baseAmount = intent.SessionFee,
            feeAmount = intent.FeeAmount,
            feePercentage = intent.FeePercentage,
            currency = intent.Currency,
            publishableKey = intent.PublishableKey,
            productName = product.Name,
            credits = product.Credits,
            validityDays = product.ValidityDays,
        });
    }

    /// <summary>
    /// Dev-mode confirm hook — called by the front-end after the mock Stripe
    /// Elements promise resolves. In production this is a NO-OP because the
    /// real Stripe webhook fires <c>payment_intent.succeeded</c> and the
    /// webhook handler invokes <see cref="IPaymentService.MarkInvoicePaidAsync"/>
    /// directly. We deliberately accept the <c>invoiceId</c> from the client
    /// (and re-verify ownership against the JWT) because mock intents don't
    /// have Metadata we can recover the invoiceId from.
    /// </summary>
    [HttpPost("confirm")]
    [Authorize(Roles = "Customer")]
    public async Task<IActionResult> Confirm([FromBody] ConfirmRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.InvoiceId))
            return BadRequest(new { message = "invoiceId is required." });
        if (string.IsNullOrWhiteSpace(request.PaymentIntentId))
            return BadRequest(new { message = "paymentIntentId is required." });

        var clientId = User.FindFirstValue("clientId");
        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();

        // Defence-in-depth: confirm that the JWT principal owns this invoice
        // before we let them flip it to PAID. Without this, a logged-in
        // customer could in theory settle someone else's pending invoice.
        var invoice = await _invoices.Find(i => i.Id == request.InvoiceId).FirstOrDefaultAsync();
        if (invoice == null) return NotFound(new { message = "Invoice not found." });
        if (invoice.ClientId != clientId)
            return StatusCode(403, new { message = "Invoice does not belong to this customer." });

        // For real Stripe intents, MarkInvoicePaidAsync recovers the invoiceId
        // from intent.Metadata and is the safe path. For mock intents we route
        // through the internal helper.
        bool ok;
        if (request.PaymentIntentId.StartsWith("pi_pkg_mock_", StringComparison.Ordinal))
        {
            ok = await _paymentService.MarkInvoicePaidByIdAsync(request.InvoiceId, request.PaymentIntentId);
        }
        else
        {
            ok = await _paymentService.MarkInvoicePaidAsync(request.PaymentIntentId);
        }

        return Ok(new { success = ok });
    }

    public class CheckoutRequest
    {
        public string ProductId { get; set; } = null!;
    }

    public class ConfirmRequest
    {
        public string InvoiceId { get; set; } = null!;
        public string PaymentIntentId { get; set; } = null!;
    }
}

