function render() {
  const grid = document.getElementById("packagesGrid");
  let list = allPackages;

  if (activeFilter !== "ALL") {
    // MIXED / NONE / null format are surfaced under the "Mixed" tab so
    // people who want flexibility see them clearly. GROUP / PRIVATE
    // tabs are exact-match.
    if (activeFilter === "MIXED") {
      list = list.filter((p) => {
        const f = (p.formatRestriction || "").toUpperCase();
        return f === "MIXED" || f === "NONE" || f === "";
      });
    } else {
      list = list.filter(
        (p) => (p.formatRestriction || "").toUpperCase() === activeFilter,
      );
    }
  }

  if (list.length === 0) {
    grid.innerHTML = `
      <div class="sp-store-empty">
        <strong>${t("store.emptyTitle")}</strong><br>
        ${t("store.emptyBody")}
      </div>`;
    return;
  }

  // Featured first (visual ordering), then by price ascending.
  const sorted = [...list].sort((a, b) => {
    const af = a.isFeatured ? 0 : 1;
    const bf = b.isFeatured ? 0 : 1;
    if (af !== bf) return af - bf;
    return (a.basePrice || 0) - (b.basePrice || 0);
  });

  grid.innerHTML = sorted.map(card).join("");
  grid.querySelectorAll("[data-pkg-id]").forEach((btn) => {
    btn.addEventListener("click", () => goToCheckout(btn.dataset.pkgId));
  });
}

function card(p) {
  const featured = p.isFeatured;
  const credits = p.credits || 0;
  const perClass = p.pricePerClass || 0;
  const validity = p.validityDays || 0;
  // SPM-121: only surface validity when there's an actual expiry window;
  // a null/0 validity means "no expiry" which reads as "not valid", so
  // we omit the line entirely rather than show a misleading label.
  const validityItem =
    validity > 0
      ? `<li>${check()} ${esc(t("store.featValidity", { days: validity }))}</li>`
      : "";
  const format = (p.formatRestriction || "MIXED").toUpperCase();

  const formatLabelMap = {
    GROUP: t("store.fmtGroup"),
    MAT: "Mat Group Classes",
    PRIVATE: t("store.fmtPrivate"),
    MIXED: t("store.fmtMixed"),
    NONE: t("store.fmtMixed"),
  };
  const formatLabel = formatLabelMap[format] || format;

  return `
    <article class="sp-pkg-card${featured ? " featured" : ""}">
      ${featured ? `<span class="sp-pkg-card-featured-badge">${t("store.featured")}</span>` : ""}
      <div class="sp-pkg-card-icon" aria-hidden="true">${productIconSvg(p.iconKey || defaultPackageIcon(format))}</div>
      <span class="sp-pkg-card-format">${esc(formatLabel)}</span>
      <h2 class="sp-pkg-card-name">${esc(p.name || "")}</h2>
      <p class="sp-pkg-card-desc">${esc(p.description || "")}</p>

      <div class="sp-pkg-card-price">
        <span class="sp-pkg-card-price-amount">${fmtPrice(p.basePrice)}</span>
        <span class="sp-pkg-card-price-currency">VND</span>
      </div>
      <div class="sp-pkg-card-per-class">
        ${t("store.perClass", { amount: fmtPrice(perClass) })}
      </div>

      <ul class="sp-pkg-card-features">
        <li>${check()} ${t("store.featClasses", { count: credits })}</li>
        ${validityItem}
        <li>${check()} ${t("store.featBooking")}</li>
        <li>${check()} ${t("store.featCancel")}</li>
      </ul>

      <button class="sp-pkg-card-cta" data-pkg-id="${esc(p.id)}">
        ${t("store.buyNow")}
      </button>
    </article>`;
}

function defaultPackageIcon(format) {
  switch ((format || "").toUpperCase()) {
    case "PRIVATE":
      return "user";
    case "MAT":
      return "sparkles";
    case "GROUP":
      return "users";
    case "MIXED":
    case "NONE":
      return "package";
    default:
      return "package";
  }
}

