  if (!token && checkoutSettings.allowGuestCheckout === false) {
    const here = window.location.pathname + window.location.search;
    window.location.href = "/login?redirect=" + encodeURIComponent(here);
    return; // Stop further init — the redirect will navigate away
  }

  // Try to get logged-in client + their packages.
  if (token) {
    try {
      const cr = await fetch(`${API}/api/booking/client-context`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (cr.ok) {
        const ctx = await cr.json();
        if (ctx.clientName && !intent.clientName)
          intent.clientName = ctx.clientName;
        if (ctx.clientPhone && !intent.clientPhone)
          intent.clientPhone = ctx.clientPhone;
        if (ctx.clientEmail && !intent.clientEmail)
          intent.clientEmail = ctx.clientEmail;
        // Capture clientId so /quote can run the "hide for active holders" check server-side.
        if (ctx.clientId) resolvedClientId = ctx.clientId;
        // MAT sessions can be paid with GROUP or MAT packages (mirrors WalletService logic)
        const sessionFmt = session.format;
        activePackages = (ctx.packages || []).filter(
          (p) =>
            p.creditsRemaining > 0 &&
            (p.format === sessionFmt ||
              p.format === "MIXED" ||
              (sessionFmt === "MAT" && p.format === "GROUP")),
        );
      }
    } catch {}
  }

  // Fetch quotes for each method we will display
  await loadPaymentOptions();
} catch (e) {
  document.getElementById("paymentOptions").innerHTML =
    `<div class="sp-error-msg visible">Could not load checkout. Please try again.</div>`;

