async function loadPaymentOptions() {
  // Only request quotes for methods that are enabled in admin settings
  const methods = ["PACKAGE_CREDIT"];
  if (checkoutSettings.allowOnlinePayment) {
    if (checkoutSettings.allowPartialPayment)
      methods.push("STRIPE_DEPOSIT");
    // Pay-in-full can be disabled (e.g. deposit-only for no-show reduction).
    if (checkoutSettings.allowFullPayment !== false)
      methods.push("STRIPE_FULL");
  }
  if (checkoutSettings.allowPayAtStudio) methods.push("PAY_AT_STUDIO");

  const quotes = {};
  upsellsByMethod = {};
  for (const m of methods) {
    // Hide PACKAGE_CREDIT if the customer doesn't have enough credits
    // for the requested quantity — stops the option dead-ending at
    // the BOOKING.INSUFFICIENT_CREDITS pre-flight server-side.
    if (m === "PACKAGE_CREDIT") {
      const total = activePackages.reduce(
        (acc, p) => acc + (p.creditsRemaining || 0),
        0,
      );
      if (total < quantity) continue;
    }
    try {
      const clientParam = resolvedClientId
        ? `&clientId=${encodeURIComponent(resolvedClientId)}`
        : "";
      let _offerParam = "";
      try {
        const _co = JSON.parse(sessionStorage.getItem("sp_claimed_offer") || "null");
        if (_co && _co.type) _offerParam = `&offerType=${encodeURIComponent(_co.type)}`;
      } catch (e) {}
      const r = await fetch(
        `${API}/api/payment/quote?sessionId=${sessionId}&paymentMethod=${m}&quantity=${quantity}${clientParam}${_offerParam}`,
      );
      if (!r.ok) continue; // skip methods the server can't price (e.g. missing drop-in price)
      const q = await r.json();
      quotes[m] = q;
      if (Array.isArray(q.upsells)) upsellsByMethod[m] = q.upsells;
    } catch {}
  }
  renderPaymentOptions(quotes);
  renderUpsell();
}

/**
 * Reveal the admin-configured upsell card when /quote returned
 * suggestions and the customer hasn't dismissed it this session.
 * We pick the suggestion from STRIPE_FULL (the "natural" full-price
 * quote) when present, since the upsell math is most compelling
 * against the full single-class price.
 */
function renderUpsell() {
  const card = document.getElementById("upsellCard");
  if (upsellDismissed) {
    card.style.display = "none";
    return;
  }
  // Scan every quote method we actually received upsells for. STRIPE_FULL is
  // the preferred "compare against drop-in price" anchor, but if the customer
  // only ever sees PAY_AT_STUDIO or PACKAGE_CREDIT (because of admin toggles)
  // we still want to surface the upsell rather than silently dropping it.
  const ups =
    upsellsByMethod.STRIPE_FULL ||
    upsellsByMethod.STRIPE_DEPOSIT ||
    upsellsByMethod.PAY_AT_STUDIO ||
    upsellsByMethod.PACKAGE_CREDIT ||
    Object.values(upsellsByMethod).find(
      (u) => Array.isArray(u) && u.length > 0,
    ) ||
    [];

