/// <summary>
/// P4-S02 — Customer joins the waitlist for a full session.
/// Authorised: any logged-in Customer. Rate-limited under the
/// shared <c>auth-login</c> bucket to deter scripted spam.
/// </summary>
[HttpPost("waitlist/join")]
[Authorize(Roles = "Customer")]
[EnableRateLimiting("auth-login")]
public async Task<IActionResult> JoinWaitlist([FromBody] JoinWaitlistRequest req)
{
    var clientId = User.FindFirstValue("clientId");
    if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();

    if (string.IsNullOrWhiteSpace(req.SessionId))
        return BadRequest(new { message = "SessionId is required." });

    // Pull profile fields from the client record so the entry has
    // accurate denormalised display data for both admin + customer views.
    var client = await _clientService.GetClientByIdAsync(clientId);
    if (client == null) return NotFound(new { message = "Client profile not found." });

    var session = await _schedulingService.GetSessionByIdAsync(req.SessionId);
    if (session == null) return NotFound(new { message = "Session not found." });

    // Auto-match package if not provided (mirrors ReserveSpot behaviour).
    string? packageId = req.PackageId;
    if (string.IsNullOrWhiteSpace(packageId))
    {
        var packages = await _walletService.GetActivePackagesForClientAsync(clientId, session.Format);
        packageId = packages.FirstOrDefault()?.Id;
    }

    var entry = await _waitlistService.JoinAsync(
        req.SessionId,
        clientId,
        client.FullName,
        client.PhoneNumber,
        client.Email,
        packageId,
        req.Goals,
        req.EquipmentType);

    var position = await _waitlistService.GetPositionAsync(req.SessionId, clientId);

    return Ok(new
    {
        success = true,
        entryId = entry.Id,
        position,

