    el.innerHTML = cart
      .map((c, idx) => {
        const sessionHint = c._classSessionLabel
          ? `<div style="font-size:11px;color:var(--color-text-muted);margin-top:2px;">📅 ${c._classSessionLabel}</div>`
          : '';
        const collectTag = c._isCollectPayment
          ? `<span style="font-size:9px;font-weight:700;color:var(--color-warning);margin-left:4px;">COLLECT</span>`
          : c._isCollectInvoice
          ? `<span style="font-size:9px;font-weight:700;color:var(--color-warning);background:rgba(245,158,11,0.12);border:1px solid rgba(245,158,11,0.35);border-radius:3px;padding:1px 5px;margin-left:4px;">₫ BALANCE</span>`
          : '';

        // Credit checkbox: walk-in class items AND collect-payment items (SPM-124).
        // Collect items carry _classFormat, so they offer pay-with-credit just like
        // walk-ins. Invoice-balance items are excluded (no _classSessionId).
        let creditRow = '';
        if (c._classSessionId && (_clientGroupCredits > 0 || _clientMatCredits > 0 || _clientPrivateCredits > 0)) {
          const fmt = (c._classFormat || 'GROUP').toUpperCase();
          const pool = _getCreditPoolForFormat(fmt);
          const used = usedCredits[fmt] || 0;
          const remaining = pool - used + (c._useCredit ? 1 : 0); // add back self if checked
          const canUse = remaining > 0;
          const isChecked = !!c._useCredit;
          const disabled = !canUse && !isChecked;

          if (pool > 0) {
            // For MAT classes: show which type will actually be consumed (MAT first, GROUP fallback)
            const fmtDisplay = fmt === 'PRIVATE' ? 'Private' : fmt === 'MAT' ? 'Mat' : 'Group';
            const creditLabel = fmt === 'MAT' && _clientMatCredits === 0
              ? '📦 Use Group credit (fallback)'
              : `📦 Use ${fmtDisplay} credit`;
            creditRow = `<div style="margin-top:4px;display:flex;align-items:center;gap:6px;">
              <label style="display:flex;align-items:center;gap:5px;cursor:${disabled ? 'not-allowed' : 'pointer'};opacity:${disabled ? '0.45' : '1'};">
                <input type="checkbox" ${isChecked ? 'checked' : ''} ${disabled ? 'disabled' : ''}
                  onchange="toggleCartCredit(${idx})"
                  style="accent-color:#8B5CF6;width:14px;height:14px;" />
                <span style="font-size:11px;font-weight:600;color:#8B5CF6;">${creditLabel}</span>
              </label>
              <span style="font-size:10px;color:var(--color-text-muted);">(${remaining - (isChecked ? 1 : 0)} left)</span>
            </div>`;
          }
        }

        // If credit is applied, show zero price and a "CREDIT" tag
        const creditApplied = c._useCredit;
        const displayPrice = creditApplied ? 0 : ((c.unitPrice ?? c.basePrice ?? 0) * c.qty);
        const creditTag = creditApplied
          ? `<span style="font-size:9px;font-weight:700;color:#8B5CF6;margin-left:4px;">CREDIT</span>`
          : '';

        return `
      <div class="cart-item">
        <div style="flex:1;">
          <div class="cart-item-name">${c.name} ×${c.qty}${collectTag}${creditTag}</div>
          ${sessionHint}
          ${c._isCollectInvoice ? `<div style="font-size:11px;color:var(--color-warning);margin-top:2px;">⚠️ Partial invoice balance</div>` : ''}
          ${creditRow}
        </div>
        <div class="cart-item-price" style="${creditApplied ? 'text-decoration:line-through;opacity:0.5;' : ''}">${displayPrice.toLocaleString()} ₫</div>
        <button class="btn btn-ghost btn-sm btn-icon" onclick="removeFromCart('${c.lineKey}')">
