// Refund any consumed package credit — ledger-driven, with the legacy
// PackageInstanceId fallback (mirrors the session-cancel refund path).
//
// The legacy fallback ALSO requires PaymentMethod == PACKAGE_CREDIT, not
// just a non-null PackageInstanceId. A RESERVED-but-never-confirmed
// booking has PackageInstanceId auto-matched purely as a UI hint
// (BookingController.ReserveSpot) but PaymentMethod is never set until
// CreateIntentAsync actually deducts a credit — so "no ledger trail" no
// longer implies "this is a legacy pre-ledger row that really was paid."
// Without this guard, reserving a class you have a package for and
// cancelling before ever paying phantom-refunds a real credit.
var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(att.Id!);
if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(att.PackageInstanceId)
    && string.Equals(att.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase))
    await _walletService.RefundCreditAsync(
        att.PackageInstanceId, att.RescheduledFromAttendanceId ?? att.Id!);

