    // Exact matches on other formats (GROUP, DUO itself, FREELANCE) are kept
    // strict so packages are never cross-consumed across incompatible class types.
    var upper = (format ?? "").ToUpperInvariant();
    var formatFilter = upper switch
    {
        "MAT" => Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" }),
        "PRIVATE" => Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "PRIVATE", "DUO" }),
        _ => Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper),
