/// makes a Duo package a general fallback for ANY private booking (see above), so
/// this override only needs to handle the OPPOSITE-preference case: a 2-seat
/// booking should prefer spending 1 Duo credit over draining 2 Private credits,
/// where the default PRIVATE-first ordering would otherwise pick Private first.
/// A plain 1-seat booking needs no override — the default ordering (Private
/// preferred, Duo as fallback) is already exactly what's wanted.
/// </summary>
public async Task<(string format, int quantity)> ResolveBookingCreditBucketAsync(string clientId, string format, int quantity)
{
    if (string.Equals(format, "PRIVATE", StringComparison.OrdinalIgnoreCase) && quantity == 2)
    {
        var duoPackages = await GetActivePackagesForClientAsync(clientId, "DUO");
        if (duoPackages.Sum(p => p.CreditsRemaining) >= 1)
            return ("DUO", 1);
    }
    return (format, quantity);
}

