// MAT sessions can be paid with GROUP or MAT packages (mirrors WalletService logic).
// A Duo Private package is a fallback for ANY private booking, solo or
// duo — not just a genuine 2-seat one — mirrors
// WalletService.GetActivePackagesForClientAsync's PRIVATE/DUO fallback.
const sessionFmt = session.format;
const duoBooking = isDuoBooking();
activePackages = (ctx.packages || []).filter(
  (p) =>
    p.creditsRemaining > 0 &&
    (p.format === sessionFmt ||
      p.format === "MIXED" ||
      (sessionFmt === "MAT" && p.format === "GROUP") ||
      (sessionFmt === "PRIVATE" && p.format === "DUO")),
);
if (sessionFmt === "PRIVATE") {
  // Ordering mirrors the server: a genuine 2-seat duo booking prefers
  // spending 1 Duo credit over 2 Private credits; an ordinary 1-seat
  // booking prefers a plain Private credit and only falls back to a
  // (more valuable) Duo credit if that's all the client has. Either
  // way, activePackages[0] — used for the credit-count label below —
  // ends up matching what the server will actually charge.
  activePackages.sort((a, b) => {
    const preferred = duoBooking ? "DUO" : "PRIVATE";
    return (a.format === preferred ? 0 : 1) - (b.format === preferred ? 0 : 1);
  });
}

