content.content:
if (!roster) return;

let attendees = [];
let detail = this._sessionDetail;
try {
  const r = await fetch(`${_CDP_API}/api/scheduling/class/${sessionId}`, {
    headers: { Authorization: 'Bearer ' + this._getToken() },
  });
  if (r.ok) {
    detail = await r.json();
    this._sessionDetail = detail;
    attendees = detail.attendees || [];
  }
} catch {}

const countEl = document.getElementById('cdpAttCount');
const seatCount = detail?.isFreelance
  ? Math.max(0, detail.freelanceHeadcount ?? detail.currentBookings ?? 0)
  : attendees.reduce((sum, a) => sum + Math.max(1, a.quantity ?? 1), 0);
if (countEl) countEl.textContent = `(${seatCount})`;

if (!attendees.length) {
  roster.innerHTML = detail?.isFreelance
    ? '<div style="text-align:center;padding:32px 20px;color:var(--color-text-muted);font-size:12px;">No CRM clients linked to this rental class. Use the attendee count above when the freelance instructor brings their own clients.</div>'
    : '<div style="text-align:center;padding:32px 20px;color:var(--color-text-muted);font-size:12px;">No bookings yet.</div>';
  return;
}

const avatarColors = ['#2BB7A3','#8B5CF6','#F4923C','#3B82F6','#EC4899','#F59E0B','#10B981','#6366F1'];

// Seat-adjuster context: a PRIVATE session is capped at 2 (duo); other formats
// are bounded by the session capacity. seatCount is the class-wide booked total
// computed above — used to decide whether "+" still has room across the class.
const isPrivateSess = (detail?.format || '') === 'PRIVATE';
const sessCapacity = detail?.capacity || 0;
const maxSeats = isPrivateSess ? 2 : (sessCapacity > 0 ? sessCapacity : Infinity);
const classSeatTotal = seatCount;

roster.innerHTML = attendees.map((a, idx) => {
  const initials = (a.clientName || 'U').split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
  const ac = avatarColors[idx % avatarColors.length];
  const statusNorm = (a.status === 'CHECKED_IN') ? 'ARRIVED' : (a.status || 'BOOKED');

  const payBadge = a.isFreeClass
    ? `<span style="font-size:10px;color:var(--color-success);font-weight:600;">FREE</span>`
    : a.paymentStatus === 'package'
      ? `<span style="font-size:10px;color:var(--color-brand-accent);font-weight:600;">📦 PKG</span>`
      : a.paymentStatus === 'paid'
        ? `<span style="font-size:10px;color:var(--color-success);font-weight:600;">✅ Paid</span>`
        : a.paymentStatus === 'partial'
          ? `<span style="font-size:10px;color:var(--color-warning);font-weight:600;">⚠️ Partial</span>`
          : `<span style="font-size:10px;color:var(--color-warning);font-weight:600;">Unpaid</span>`;

  const invLink = a.linkedInvoiceNumber
    ? ` <a href="/admin/invoices?search=${encodeURIComponent(a.linkedInvoiceNumber)}" style="font-size:10px;color:var(--color-brand-accent);" onclick="event.stopPropagation();">📄 ${esc(a.linkedInvoiceNumber)}</a>`
    : '';
  const bkgLink = `<a href="/admin/bookings?search=${encodeURIComponent(a.bookingReference || a.attendanceId)}" style="font-size:10px;color:var(--color-brand-accent);" onclick="event.stopPropagation();">📋 ${esc(a.bookingReference || a.attendanceId.substring(0, 8))}</a>`;
  const commNote = !a.countsTowardsCommission
    ? `<span title="Excluded from commission" style="font-size:10px;color:var(--color-text-muted);">⛔ No comm.</span>`
    : '';

  /* Status select */
  const statusSelect = `<select class="dp-status-select" data-status="${statusNorm}"
    onchange="ClassDetailPanel._onStatusChange(this,'${a.attendanceId}')">
    <option value="ARRIVED"      ${statusNorm === 'ARRIVED'      ? 'selected' : ''}>✅ Arrived</option>
    <option value="NO_SHOW"      ${statusNorm === 'NO_SHOW'      ? 'selected' : ''}>❌ No Show</option>
    <option value="LATE_CANCEL"  ${statusNorm === 'LATE_CANCEL'  ? 'selected' : ''}>⚠️ Late Cancel</option>
    <option value="BOOKED"       ${statusNorm === 'BOOKED' || statusNorm === 'RESERVED' ? 'selected' : ''}>📅 Booked</option>
  </select>`;

  const safeName = (a.clientName || 'this client').replace(/['"\\<>]/g, '');
  const removeBtn = `<button class="btn btn-ghost btn-sm" title="Remove from class (booking mistake)"
    onclick="ClassDetailPanel.removeAttendee('${a.attendanceId}','${safeName}')"
