/* ── Make a solo PRIVATE booking a Duo Class, from checkout ─── */
async mposMakeDuo() {
  const m = this._mpos;
  if (!m || !this._sessionId) return;
  if (!confirm('Make this a Duo Class? The booking will be resized to 2 people and re-priced at the duo rate (or a Duo Private credit, if available).')) return;
  try {
    const r = await fetch(`${_CDP_API}/api/scheduling/session/${this._sessionId}/attendee/${m.attendanceId}/quantity`, {
      method: 'PATCH',
      headers: { Authorization: 'Bearer ' + this._getToken(), 'Content-Type': 'application/json' },
      body: JSON.stringify({ quantity: 2 }),
    });
    if (!r.ok) throw new Error(await this._readApiError(r));
    const updated = await r.json();
    window.showToast?.('Now a Duo Class · 2 people', 'success');
    if (this._afterAttendanceUpdate && this._sessionId) await this._afterAttendanceUpdate(this._sessionId);
    await this.refresh();
    // Re-open checkout fresh from the resized booking's real state (seats,
    // amount due, payment method if it migrated to a credit) rather than
    // hand-patching _mpos — reuses showCollectPayment's own initialization
    // instead of duplicating it.
    this.showCollectPayment(
      updated.id || m.attendanceId,
      updated.amountDueAtStudio || 0,
      m.clientId, m.clientName,
      updated.quantity || 2,
      updated.status || m.bookingStatus,
    );
  } catch (err) {
    window.showToast?.(err.message || 'Failed to make this a duo class', 'error');
  }
},

