        // Refund the freed seats' credits (ledger-driven partial refund).
        if (isCredit)
            await _walletService.RefundPartialCreditByAttendanceWithTrailAsync(att.Id!, -delta);
    }

    // Persist the new seat count. For a pay-at-studio / unpaid booking, re-snapshot
    // the amount due, duo-aware (mirrors AdminAddStudentAsync) — growing a PRIVATE
    // booking to 2 seats bills the flat duo rate, not 2x the drop-in. Without this,
    // resizing a cash Private booking up to duo (e.g. via "Make it a Duo Class" at
    // checkout) would overcharge the client. Credit bookings stay 0đ due — the
    // wallet already absorbed it (see the migration above).
    var update = Builders<Attendance>.Update.Set(a => a.Quantity, newQuantity);
    if (!isCredit)
    {
        var resizeSettings = await _settingsService.GetAsync();
        var dueAmount = PaymentService.DuoAwareTotal(session.Format, session.DropInPrice ?? 0m, newQuantity, resizeSettings.PrivateDuoPrice);
        update = update.Set(a => a.AmountDueAtStudio, dueAmount);
    }
    await _attendances.UpdateOneAsync(a => a.Id == att.Id, update);

    // SPM-98 — a decrease that empties a bumped duo PRIVATE restores Capacity to 1.
    if (delta < 0)
        await RestorePrivateCapacityIfEmptyAsync(sessionId);

    att.Quantity = newQuantity;
    return att;
}

