    // ── V2: Calendar Operations ──────────────────────────────────────────

    /// <summary>
    /// Admin creates an ad-hoc (non-blueprint) session. Sets Origin = MANUAL.
    /// </summary>
    [HttpPost("session/manual")]
    [Authorize(Roles = "Admin,Manager,Receptionist,HeadInstructor")]
    public async Task<IActionResult> CreateManualSession([FromBody] CalendarSession session)
    {
        try
        {
            var created = await _schedulingService.CreateManualSessionAsync(session);
            return Ok(created);
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Override a materialised session: reschedule, swap instructor, change capacity.
    /// The original session is mutated in-place with IsOverride = true.
    /// </summary>
    [HttpPatch("session/{id}/override")]
    [Authorize(Roles = "Admin,Manager,Receptionist,HeadInstructor,Instructor")]
    public async Task<IActionResult> OverrideSession(string id, [FromBody] OverrideSessionRequest request)
    {
        // SPM-91 — resolve the public-visibility intent. When the request omits
        // IsPublic (legacy clients), preserve the session's current value rather
        // than defaulting it on or off.
        var current = await _schedulingService.GetSessionByIdAsync(id);
        if (current is null) return NotFound(new { message = "Session not found." });

        var updated = new CalendarSession
        {
            InstructorId = request.InstructorId,
            InstructorName = request.InstructorName,
            ClassName = request.ClassName,
            FocusArea = request.FocusArea,
            DifficultyLevel = request.DifficultyLevel,
            Capacity = request.Capacity,
            StartTime = request.StartTime,
            EndTime = request.EndTime,
            Status = request.Status,
            IsPublic = request.IsPublic ?? current.IsPublic,
        };
        var success = await _schedulingService.OverrideSessionAsync(id, updated, request.Note);
        if (!success) return NotFound(new { message = "Session not found." });
        return Ok(new { message = "Session overridden." });
    }

    /// <summary>
    /// Returns all sessions for a specific studio-local date. Used by the
    /// admin day-view calendar.
    /// </summary>
    [HttpGet("day/{date}")]
    [Authorize(Roles = "Admin,Manager,Receptionist,HeadInstructor,Instructor")]
    public async Task<IActionResult> GetDayView(DateTime date)
    {
        var sessions = await _schedulingService.GetSessionsByDateAsync(date);
        return Ok(sessions);
    }

    // ── V2: Freelance Operations ─────────────────────────────────────────

    /// <summary>
    /// Create a freelance rental session. Admin only.
    /// </summary>
    [HttpPost("session/freelance")]
    [Authorize(Roles = "Admin,Manager")]
    public async Task<IActionResult> CreateFreelanceSession([FromBody] CalendarSession session)
    {
        try
        {
            var created = await _schedulingService.CreateFreelanceSessionAsync(session);
            return Ok(created);
        }
        catch (Exception ex)
        {
            return BadRequest(new { message = ex.Message });
        }
    }

    /// <summary>
    /// Complete a freelance session and debit package credits.
    /// </summary>
    [HttpPost("session/{id}/complete-freelance")]
    [Authorize(Roles = "Admin,Manager")]
    public async Task<IActionResult> CompleteFreelanceSession(string id, [FromBody] FreelanceCompleteRequest request)
    {
        try
        {
            var result = await _schedulingService.CompleteFreelanceSessionAsync(id, request.Headcount);
            if (result == null) return NotFound(new { message = "Freelance session not found or not a freelance session." });
            return Ok(result);
        }
        catch (BusinessRuleException ex)
        {
            return BadRequest(new { message = ex.Message, code = ex.Code });
        }
    }
}

