    string attendanceId, [FromBody] CollectBookingPaymentRequest request)
{
    try
    {
        var result = await _schedulingService.CollectStudioPaymentAsync(
            attendanceId, request.Amount, request.PaymentMethod,
            request.Notes, _invoiceService, request.AttendingSeats,
            request.PaymentSplits, request.DiscountAmount);
        return Ok(result);
    }
