/// <summary>
/// Split a multi-seat "book for N" booking into separate single-seat bookings
/// so each person can be checked out / paid individually. The caller resolves
/// each additional person to a real client first (search or quick walk-in add).
/// </summary>
[HttpPost("booking/{attendanceId}/split")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> SplitBooking(string attendanceId, [FromBody] SplitBookingRequest request)
{
    try
    {
        var created = await _schedulingService.SplitBookingAsync(attendanceId, request.People ?? new());
        return Ok(new { message = "Booking split into individual bookings.", createdIds = created.Select(a => a.Id) });
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

/// <summary>
/// Adjust the seat quantity of an existing attendee on a session in place — the
/// class-detail panel's inline seat stepper (card cmskphkyx…). Grows/shrinks the
/// booking, updating the "X/Y booked" count and the attendee's credit / pay-at-studio
/// charge together. Bounded by remaining capacity (PRIVATE = duo cap of 2) and a
/// minimum of one seat.
/// </summary>
[HttpPatch("session/{id}/attendee/{attendanceId}/quantity")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor")]
public async Task<IActionResult> AdjustAttendeeQuantity(string id, string attendanceId, [FromBody] AdjustQuantityRequest request)
{
    try
    {
        var attendance = await _schedulingService.AdjustAttendeeQuantityAsync(id, attendanceId, request.Quantity);
        return Ok(attendance);
    }
    catch (Exception ex)
    {
        return BadRequest(new { message = ex.Message });
    }
}

