public async Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
{
    // A package with ExpiryDate == null never expires; include it unconditionally.
    // A package with a concrete ExpiryDate must still be in the future.
    var noExpiry  = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
    var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
    var expiryOk  = Builders<ClientPackage>.Filter.Or(noExpiry, notExpired);

    // MAT is a sub-type of group class. A MAT session can be paid with either a
    // MAT-specific package (preferred — consumed first) or a generic GROUP package
    // (fallback). PRIVATE similarly accepts a DUO package as a fallback — a Duo
    // Private credit is usable for ANY private class, solo or duo, not just a
    // genuine 2-person booking (the client just "spends" a duo-rate credit on a
    // single session if they choose to; the studio loses nothing either way).
    // Exact matches on other formats (GROUP, DUO itself, FREELANCE) are kept
    // strict so packages are never cross-consumed across incompatible class types.
    var upper = (format ?? "").ToUpperInvariant();
    var formatFilter = upper switch
    {
        "MAT" => Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" }),
        "PRIVATE" => Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "PRIVATE", "DUO" }),
        _ => Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper),
    };

    var filter = Builders<ClientPackage>.Filter.And(
        Builders<ClientPackage>.Filter.Eq(p => p.ClientId, clientId),
        formatFilter,
        // Include LOW_BALANCE alongside ACTIVE: a package with ≤2 credits
        // remaining is still fully usable — excluding it would hide the
        // PACKAGE_CREDIT option at checkout even though credits exist.
        Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),
        Builders<ClientPackage>.Filter.Gt(p => p.CreditsRemaining, 0),
        expiryOk
    );

    // For MAT/PRIVATE: sort the specialised/exact-match packages before the
    // fallback bucket so the more specific wallet is always consumed first
    // (a solo private booking should spend a plain Private credit before it
    // touches a more valuable Duo one). Within each bucket sort by earliest
    // expiry (FIFO across wallets of the same type). DeductCreditAsync's
    // quantity==2 duo override handles the OPPOSITE preference (Duo first)
    // for a genuine 2-seat booking — see ResolveBookingCreditBucketAsync.
    var packages = await _clientPackages.Find(filter).ToListAsync();
    if (upper == "MAT")
    {
        packages = packages
            .OrderBy(p => p.Format == "MAT" ? 0 : 1)
            .ThenBy(p => p.ExpiryDate ?? DateTime.MaxValue)
            .ToList();
    }
    else if (upper == "PRIVATE")
    {
        packages = packages
            .OrderBy(p => p.Format == "PRIVATE" ? 0 : 1)
            .ThenBy(p => p.ExpiryDate ?? DateTime.MaxValue)
            .ToList();
    }
    else
    {
        packages = packages.OrderBy(p => p.ExpiryDate ?? DateTime.MaxValue).ToList();
    }
    return packages;
}

/// <summary>
/// Duo Private packages — resolves which wallet bucket a genuine 2-seat "Make it
/// a Duo Class" booking should draw from. GetActivePackagesForClientAsync already
/// makes a Duo package a general fallback for ANY private booking (see above), so
/// this override only needs to handle the OPPOSITE-preference case: a 2-seat
/// booking should prefer spending 1 Duo credit over draining 2 Private credits,
/// where the default PRIVATE-first ordering would otherwise pick Private first.
/// A plain 1-seat booking needs no override — the default ordering (Private
/// preferred, Duo as fallback) is already exactly what's wanted.
/// </summary>
public async Task<(string format, int quantity)> ResolveBookingCreditBucketAsync(string clientId, string format, int quantity)
{
    if (string.Equals(format, "PRIVATE", StringComparison.OrdinalIgnoreCase) && quantity == 2)
    {
        var duoPackages = await GetActivePackagesForClientAsync(clientId, "DUO");
        if (duoPackages.Sum(p => p.CreditsRemaining) >= 1)
            return ("DUO", 1);
    }
    return (format, quantity);
}

