///   <item>Monetary bookings are paid when a linked <see cref="Invoice"/>
///   has <c>Status == "PAID"</c>, OR <see cref="Attendance.AmountPaid"/>
///   is &gt; 0, OR <see cref="Attendance.AmountDueAtStudio"/> is null/0
///   (nothing left to collect at the studio).</item>
/// </list>
///
/// <para>The invoice lookup mirrors the one in
/// <see cref="ResolveAttendeeRevenueAsync"/> so the two surfaces stay
/// consistent. This is a pure read — re-runs remain idempotent.</para>
/// </summary>
private async Task<bool> IsAttendancePaidAsync(Attendance att)
{
    // Package-credit redemptions were paid for when the package was bought.
    if (att.PaymentMethod == "PACKAGE_CREDIT") return true;

    // Free classes are satisfied (0₫ by design, not an unpaid balance).
    if (att.IsFreeClass) return true;

    // Direct evidence of payment on the attendance row.
    if ((att.AmountPaid ?? 0m) > 0m) return true;

    // Nothing left to collect at the studio ⇒ treated as paid. (null is
    // treated as "no outstanding balance" — matches legacy rows that
    // pre-date the field and the fully-prepaid online flow.)
    if ((att.AmountDueAtStudio ?? 0m) <= 0m) return true;

    // Otherwise, a linked PAID invoice settles it. Mirrors the invoice
    // lookup in ResolveAttendeeRevenueAsync.
    var linkedInvoice = await _invoices.Find(
        Builders<Invoice>.Filter.ElemMatch(
            i => i.Lines,
            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
        )
    ).FirstOrDefaultAsync();

    return linkedInvoice is not null && linkedInvoice.Status == "PAID";
}

/// <summary>
/// Resolves the revenue attributed to a single attendee for commission
/// calculation. Uses the linked invoice's paid balance as the source of
/// truth; falls back to the session's snapshotted DropInPrice when no
/// invoice exists (e.g. package credit or pre-paid bookings).
/// </summary>
private async Task<decimal> ResolveAttendeeRevenueAsync(Attendance att, CalendarSession session)
{
    var qty = Math.Max(1, att.Quantity);

    // ── Package-credit bookings ──────────────────────────────────────
    // When a client redeems a pre-paid package, the invoice shows 0₫ (no new
    // money changed hands), but the instructor's commission must be based on
    // the class's value. Business rule (studio policy): the commission base is
    // the per-class rate WITHIN the package — i.e. what the package sold for
    // divided by its credits — NOT the full drop-in rate. That per-class value
    // is stored on the ClientPackage as FractionalValuePerClass.
    if (att.PaymentMethod == "PACKAGE_CREDIT")
    {
        if (!string.IsNullOrEmpty(att.PackageInstanceId))
        {
            var pkg = await _clientPackages
                .Find(p => p.Id == att.PackageInstanceId)
                .FirstOrDefaultAsync();
            if (pkg is not null && pkg.FractionalValuePerClass > 0m)
            {
                // Duo Private packages break the "credits scale 1:1 with seats"
                // assumption every other format relies on here: ONE Duo credit
                // pays for the WHOLE 2-person class (Attendance.Quantity == 2),
                // unlike a 2-seat group booking or the legacy 2-credit private
                // duo, where each seat really did cost its own credit. Multiplying
                // by `qty` for a Duo package would double the revenue base (e.g.
                // 1,300,000 -> 2,600,000) for any % / PERCENTAGE_TIERED instructor.
                return string.Equals(pkg.Format, "DUO", StringComparison.OrdinalIgnoreCase)
                    ? pkg.FractionalValuePerClass
                    : pkg.FractionalValuePerClass * qty;
            }
        }
        // Fallback only when the package's per-class value is unknown
        // (e.g. missing package link) — the session's drop-in price.
        return (session.DropInPrice ?? 0m) * qty;
    }

    // ── Monetary-payment bookings ────────────────────────────────────
    // 1. Try to find a linked invoice for this attendance and use its
    //    actual paid amount (TotalNet) as the revenue base.
    var linkedInvoice = await _invoices.Find(
        Builders<Invoice>.Filter.ElemMatch(
            i => i.Lines,
            Builders<InvoiceLine>.Filter.Eq(l => l.AttendanceId, att.Id)
        )
    ).FirstOrDefaultAsync();

    // The "VAT (online only)" surcharge is a pass-through fee, NOT studio
    // revenue, so it must never be part of the commission base. It is stored
    // separately as Invoice.OnlineFeeAmount (never inside a line), so the
    // per-line total below is already fee-free; only the whole-invoice and
    // AmountPaid fallbacks need the fee stripped out. Apportion the fee to
    // this attendee by their share of the invoice's line subtotal.
    decimal onlineFeeShare = 0m;
    if (linkedInvoice is not null && linkedInvoice.OnlineFeeAmount > 0m)
    {
        var lineSubtotal = linkedInvoice.Lines.Sum(l => l.UnitPrice * l.Quantity - l.LineDiscount);
        var myLine = linkedInvoice.Lines.FirstOrDefault(l => l.AttendanceId == att.Id);
        var myLineTotal = myLine is not null ? (myLine.UnitPrice * myLine.Quantity - myLine.LineDiscount) : 0m;
        onlineFeeShare = (lineSubtotal > 0m && myLineTotal > 0m)
            ? linkedInvoice.OnlineFeeAmount * (myLineTotal / lineSubtotal)
            : linkedInvoice.OnlineFeeAmount; // single-booking invoice: exclude the whole fee
    }

    if (linkedInvoice is not null && linkedInvoice.Status == "PAID")
    {
        // Prefer the specific line total (already excludes the online fee).
        // Note: invoice line already includes quantity in its total.
        var line = linkedInvoice.Lines
            .FirstOrDefault(l => l.AttendanceId == att.Id);
        if (line is not null)
        {
            var lineTotal = line.UnitPrice * line.Quantity - line.LineDiscount;
            if (lineTotal > 0m) return lineTotal;
        }
        // Whole-invoice fallback: strip the online fee out of the net.
        var netExFee = linkedInvoice.TotalNet - linkedInvoice.OnlineFeeAmount;
        if (netExFee > 0m) return netExFee;
    }

    // 2. If the attendance has a recorded paid amount, use that — less this
    //    attendee's share of any online fee that was bundled into the payment.

