[HttpGet("client-context")]
[Authorize(Roles = "Customer")]
public async Task<IActionResult> GetClientContext()
{
    var clientId = User.FindFirstValue("clientId");
    if (string.IsNullOrWhiteSpace(clientId))
    {
        // Account exists but is unlinked — degrade gracefully so the
        // checkout page falls through to its guest-contact section
        // instead of redirecting away.
        return Ok(new
        {
            clientId = (string?)null,
            clientName = (string?)null,
            clientPhone = (string?)null,
            clientEmail = (string?)null,
            packages = Array.Empty<object>()
        });
    }

    var client = await _clientService.GetClientByIdAsync(clientId);

    // Pull all formats so the frontend can match against any session format
    // without a second round-trip. MAT packages are fetched separately because
    // WalletService treats MAT as a sub-type (MAT wallets also accept GROUP packages
    // but a dedicated MAT package must still appear in the list). DUO likewise needs
    // its own fetch — a Duo Private booking is a PRIVATE-format session, so without
    // this a Duo package would never appear in the checkout page's package list at all.
    var groupPkgs = await _walletService.GetActivePackagesForClientAsync(clientId, "GROUP");
    var privatePkgs = await _walletService.GetActivePackagesForClientAsync(clientId, "PRIVATE");
    var matPkgs = await _walletService.GetActivePackagesForClientAsync(clientId, "MAT");
    var duoPkgs = await _walletService.GetActivePackagesForClientAsync(clientId, "DUO");
    var allActive = groupPkgs.Concat(privatePkgs).Concat(matPkgs).Concat(duoPkgs).DistinctBy(p => p.Id);

    return Ok(new
    {
        clientId,
        clientName = client?.FullName,
        clientPhone = client?.PhoneNumber,
        clientEmail = client?.Email,
        packages = allActive.Select(p => new
        {
            p.Id,
            p.Format,
            p.TotalCredits,
            p.CreditsUsed,
            p.CreditsRemaining,
            p.ExpiryDate,
            p.Status
        })
