echo
ssh -i ~/.ssh/soulpilates_deploy root@51.79.226.200 "docker exec soulpilates-staging-mongo mongosh --quiet -u sp_staging -p 2d1e73bd7e07d10d596148f4f7929b66 --authenticationDatabase admin soulpilates --eval '
var invR = db.Invoices.deleteMany({_id: ObjectId(\"6aa36f92df38183a17609059\")});
