using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Issue #5 — retention check-in reminders.
///
/// <para>
/// Twin of <see cref="ReminderService"/>, but the "due window" semantic is
/// inverted: instead of "session starts in N hours", it's "last check-in was
/// N days ago and the package still has credits". Each window label (e.g.
/// <c>"14d"</c>) is tracked on <see cref="ClientPackage.RetentionRemindersSent"/>
/// so re-running the job is safe — every package + window pair is emailed at
/// most once. Settings come from <see cref="GlobalSettings"/> so the studio
/// can tweak cadence + windows live without redeploys.
/// </para>
///
/// <para>
/// Send-then-tag ordering: the email goes out first, then the tag is
/// $push-appended. If the SMTP call throws, we leave the tag off so the next
/// tick retries.
/// </para>
///
/// <para>
/// SPM — PER-CLIENT win-back throttle. The per-package x per-window
/// <see cref="ClientPackage.RetentionRemindersSent"/> tag over-sent: a client
/// with several active packages got one email per package per window, and the
/// tag never cleared on a return booking. The authoritative gate is now
/// <see cref="Client.WinBackEmailSentAt"/> — at most ONE win-back per lapse per
/// CLIENT. On a successful send we stamp the client (NOT the package). A genuine
/// new booking (WALK_IN/ONLINE create paths in SchedulingService/PaymentService)
/// resets the stamp to null, re-arming a future win-back. The package tag is now
/// used only to stop re-querying packages whose client has no email / opted out.
/// </para>
/// </summary>
public class RetentionReminderService : IRetentionReminderService
{
    private readonly IMongoCollection<ClientPackage> _packages;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IMongoCollection<Client> _clients;
    private readonly IEmailService _emailService;
    private readonly ISettingsService _settings;
    private readonly ILogger<RetentionReminderService> _logger;
    private readonly string _publicBaseUrl;

    public RetentionReminderService(
        MongoDbContext db,
        IEmailService emailService,
        ISettingsService settings,
        ILogger<RetentionReminderService> logger,
        IConfiguration configuration)
    {
        _packages = db.GetCollection<ClientPackage>("ClientPackages");
        _attendances = db.GetCollection<Attendance>("Attendances");
        _clients = db.GetCollection<Client>("Clients");
        _emailService = emailService;
        _settings = settings;
        _logger = logger;
        var rawBase = configuration["PublicSite:BaseUrl"];
        _publicBaseUrl = string.IsNullOrWhiteSpace(rawBase) ? "http://localhost:4321" : rawBase.TrimEnd('/');
    }

    public async Task<int> SendDueRemindersAsync(DateTime nowUtc, CancellationToken ct = default)
    {
        var s = await _settings.GetAsync(ct);
        if (!s.EnableRetentionReminders) return 0;

        var windows = (s.RetentionReminderWindows ?? new())
            .Select(w => (Tag: w, Days: ParseDays(w)))
            .Where(p => p.Days > 0)
            .OrderByDescending(p => p.Days) // Send the largest-gap reminder first so older inactivity gets the firmer copy.
            .ToList();

        if (windows.Count == 0) return 0;

        var sent = 0;
        foreach (var (tag, days) in windows)
        {
            // A package is eligible for window `tag` when:
            //   - It is currently active (status ACTIVE/LOW_BALANCE — not expired/completed).
            //   - CreditsRemaining ≥ configured floor — exhausted packs belong on a re-buy nudge, not a retention nudge.
            //   - Its last CHECKED_IN attendance is older than `days` (or there's no check-in ever).
            //   - This `tag` is not already on RetentionRemindersSent.
            var filter = Builders<ClientPackage>.Filter.And(
                Builders<ClientPackage>.Filter.In(p => p.Status, new[] { "ACTIVE", "LOW_BALANCE" }),

