function bookingPaymentBadge(b) {
  if (b.isFreeClass) return `<span style="font-size:11px;color:var(--color-success);font-weight:600;">✅ FREE</span>`;
  const pm = b.paymentMethod;
  const paid = b.amountPaid ?? 0;
  const due = b.amountDueAtStudio ?? 0;
  const fmt = (n) => (n ?? 0).toLocaleString();
  if (pm === "PACKAGE_CREDIT") return `<span style="font-size:11px;color:var(--color-brand-accent);font-weight:600;">💳 Package</span>`;
  if (pm === "STRIPE_FULL" && due <= 0) return `<span style="font-size:11px;color:var(--color-success);font-weight:600;">✅ Paid online</span>`;
  if (pm === "STRIPE_DEPOSIT" && due > 0) return `<span style="font-size:11px;color:var(--color-warning);font-weight:600;">⚠️ ${fmt(due)} ₫ due</span>`;
  if (pm === "STRIPE_DEPOSIT" && due <= 0) return `<span style="font-size:11px;color:var(--color-success);font-weight:600;">✅ Paid</span>`;
  if (pm === "PAY_AT_STUDIO" && due > 0) return `<span style="font-size:11px;color:var(--color-warning);font-weight:600;">🏪 ${fmt(due)} ₫ due</span>`;
  if (pm === "PAY_AT_STUDIO" && due <= 0 && paid > 0) return `<span style="font-size:11px;color:var(--color-success);font-weight:600;">✅ Studio paid</span>`;
  if (!pm && paid <= 0 && due <= 0) return `<span style="font-size:11px;color:var(--color-text-muted);">❓ —</span>`;
  if (due <= 0 && paid > 0) return `<span style="font-size:11px;color:var(--color-success);font-weight:600;">✅ ${fmt(paid)} ₫</span>`;
  return `<span style="font-size:11px;color:var(--color-warning);font-weight:600;">⚠️ ${fmt(due)} ₫ due</span>`;
}

// SPM-105: route the session-history "Collect" action to POS the same way the
// bookings/sessions tabs do (redirect with the booking pre-loaded into the
// POS cart) instead of an inline collect form. Uses the exact query params
// pos.astro parses for collectClass (see bookings.astro for the reference).
function bookingCollectBtn(b) {
  if (b.isFreeClass) return "";
  const due = b.amountDueAtStudio ?? 0;
  const pm = b.paymentMethod;
  const needsPayment = due > 0 || (!pm && (b.amountPaid ?? 0) <= 0);
  if (!needsPayment) return "";
  return `
    <div style="margin-top:4px;">
      <button onclick="profileCollectPayment('${b.attendanceId}', '${b.calendarSessionId || ''}', ${due}, '${encodeURIComponent(b.className || 'Class')}', '${encodeURIComponent(b.instructorName || '')}', '${encodeURIComponent(b.format || '')}')" style="background:var(--color-brand-accent);color:#fff;border:none;font-size:10px;padding:3px 8px;border-radius:3px;cursor:pointer;font-weight:600;">💳 Collect at POS →</button>
    </div>`;
}

// Session history is paginated so EVERY session shows, no matter how many
// times the client came — 20 per page, "Load more" appends the next page.
const BOOKING_PAGE_SIZE = 20;
let bookingOffset = 0;
let bookingTotalShown = 0;

const statusBadge = (s) =>
  s === "ARRIVED" || s === "CHECKED_IN"
    ? "badge-success"
    : s === "NO_SHOW"
      ? "badge-danger"
      : "badge-default";

function renderBookingRows(bookings) {
  return bookings
    .map(
      (b) => `
          <tr>
            <td class="text-muted text-sm">${b.sessionStartTime ? new Date(b.sessionStartTime).toLocaleDateString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : new Date(b.bookedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</td>
            <td>${b.className ?? "—"}</td>
            <td class="text-muted text-sm">${b.instructorName ?? "—"}</td>
            <td><span class="badge ${statusBadge(b.status)}">${b.status}</span></td>
