function loadBookingPage() {
  const btn = document.getElementById("bookingLoadMoreBtn");
  const wrap = document.getElementById("bookingLoadMoreWrap");
  const countEl = document.getElementById("bookingCount");
  if (btn) { btn.disabled = true; btn.textContent = "Loading…"; }

  fetch(`${API}/api/scheduling/client/${clientId}/bookings?limit=${BOOKING_PAGE_SIZE}&offset=${bookingOffset}`, {
    headers: { Authorization: "Bearer " + token },
  })
    .then((r) => (r.ok ? r.json() : Promise.reject(r.status)))
    .then((bookings) => {
      const table = document.getElementById("bookingTable");
      if (bookingOffset === 0 && !bookings.length) {
        table.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:40px;color:var(--color-text-muted);">No sessions yet</td></tr>`;
        if (wrap) wrap.style.display = "none";
        return;
      }
      // Replace the "Loading…" placeholder on the first page, then append.
