[HttpGet("client/{clientId}/bookings")]
[Authorize(Roles = "Admin,Receptionist,HeadInstructor,Instructor")]
public async Task<IActionResult> GetClientBookings(
    string clientId,
    [FromQuery] int limit = 50,
    [FromQuery] bool includeCancelled = false,
    [FromQuery] int offset = 0)
{
    var rows = await _schedulingService.GetBookingHistoryForClientAsync(clientId, limit, includeCancelled, offset);
    // Project to camelCase wire shape that matches the Astro client-profile
    // page's existing template (className / instructorName / sessionStartTime).
    return Ok(rows.Select(r => new
    {
        attendanceId = r.AttendanceId,
        calendarSessionId = r.CalendarSessionId,
        bookedAt = r.BookedAt,
        sessionStartTime = r.SessionStartTime,
        sessionEndTime = r.SessionEndTime,
        className = r.ClassName,
        format = r.Format,
        instructorName = r.InstructorName,
        instructorPhotoUrl = r.InstructorPhotoUrl,
        status = r.Status,
        bookingReference = r.BookingReference,
        // ── Payment bridge ──
        paymentMethod = r.PaymentMethod,
        amountPaid = r.AmountPaid,
        amountDueAtStudio = r.AmountDueAtStudio,
        isFreeClass = r.IsFreeClass,
        // ── Seat count ──
        quantity = r.Quantity,
    }));
}

