// Seat-count badge — mirrors the class-detail roster's convention (card
// cmskphkyx…): a "Duo" tag for a 2-seat PRIVATE booking, a generic "×N"
// pill for any other multi-seat booking (e.g. a GROUP class booked for
// more than one person). A single credit-consuming Attendance row can
// cover several seats, and without this the history table looks
// identical to a 1-credit session — see the "does this session's row
// reflect that it actually used N credits" report.
function bookingSeatBadge(b) {
  const qty = b.quantity ?? 1;
  if (qty <= 1) return "";
  if (b.format === "PRIVATE" && qty === 2) {
    return `<span title="Duo Class — 2 people on one Private booking" style="display:inline-flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;background:rgba(139,92,246,0.18);color:#8B5CF6;border:1px solid rgba(139,92,246,0.4);border-radius:999px;padding:1px 7px;margin-left:6px;">👯 Duo</span>`;
  }
  return `<span title="${qty} seats" style="display:inline-flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;background:rgba(var(--brand-accent-rgb,212,150,60),0.18);color:var(--color-brand-accent);border:1px solid rgba(var(--brand-accent-rgb,212,150,60),0.35);border-radius:999px;padding:1px 6px;margin-left:6px;">×${qty}</span>`;
}

function renderBookingRows(bookings) {
  return bookings
    .map(
      (b) => `
          <tr>
            <td class="text-muted text-sm">${b.sessionStartTime ? new Date(b.sessionStartTime).toLocaleDateString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }) : new Date(b.bookedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</td>
            <td>${b.className ?? "—"}${bookingSeatBadge(b)}</td>
            <td class="text-muted text-sm">${b.instructorName ?? "—"}</td>
            <td><span class="badge ${statusBadge(b.status)}">${b.status}</span></td>
            <td>${bookingPaymentBadge(b)}${bookingCollectBtn(b)}</td>
          </tr>`,
    )
    .join("");
}

