using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;
using System.Collections.Generic;

namespace SoulPilates.Core.Entities;

/// <summary>
/// Effective-dated, immutable snapshot of every rate-affecting field on a
/// <see cref="Staff"/> row. Created automatically by <c>StaffService</c>
/// whenever an admin edits a rate, salary, tier ladder, or headcount field.
///
/// <para>
/// <b>Why this exists.</b> Before this entity, <see cref="SoulPilates.Services.PayrollService"/>
/// read live <c>Staff.GroupFlatRatePerClass</c> et al. on every run. That meant
/// editing a rate in April and re-running January's payroll silently re-priced
/// historical sessions, and the new <c>PayrollRun.TotalPayroll</c> then flowed
/// into <c>AccountingService.ComputeMonthlyWashoutAsync</c>, corrupting the
/// locked-or-not historical washout. The Google Sheets ledger had the same
/// failure mode — this entity is the architectural fix.
/// </para>
///
/// <para>
/// <b>How it's used.</b> Every payroll run asks the revision service for the
/// revision that was in force at the run's <c>PeriodEnd</c>; the answer drives
/// the rate math. The current <see cref="Staff"/> document remains the "live"
/// editable view for the admin UI, but is no longer authoritative for payroll
/// math — it's just a denormalised cache of the latest revision's values.
/// </para>
///
/// <para>
/// Revisions are append-only. Editing or deleting one is not exposed in the
/// service surface (other than via a deliberate one-off Mongo command for
/// data cleanup, audit-logged separately).
/// </para>
/// </summary>
public class StaffRateRevision : BaseEntity
{
    /// <summary>The <see cref="Staff"/> row this revision belongs to.</summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string StaffId { get; set; } = null!;

    /// <summary>
    /// Denormalised at write-time so the revision survives a rename of the
    /// staff member (or a future tombstone-and-replace). The same defence-in-depth
    /// pattern we already use on <c>Attendance.ClientName</c> and <c>Bonus.RecipientStaffName</c>.
    /// </summary>
    public string StaffNameSnapshot { get; set; } = string.Empty;

    /// <summary>
    /// Inclusive moment from which this revision is the in-force rate sheet for
    /// payroll calculations. The service picks the most-recent revision whose
    /// <c>EffectiveFrom &lt;= period_end</c>. Stored in UTC.
    /// </summary>
    public DateTime EffectiveFrom { get; set; }

    /// <summary>
    /// Free-text justification for the change (e.g. "annual review", "promoted
    /// to senior tier"). Optional but encouraged in the admin UI — appears in
    /// the rate-history table for the staff row.
    /// </summary>
    public string? ChangeNote { get; set; }

    /// <summary>
    /// User id of the admin who triggered the revision, when available.
    /// Optional — bulk-import / migration paths leave this null.
    /// </summary>
    [BsonRepresentation(BsonType.ObjectId)]
    public string? CreatedByUserId { get; set; }

    /// <summary>
    /// True iff this revision was synthesised by the bootstrap path (legacy
    /// staff that existed before the revision system; their first payroll-run
    /// after deploy mints one revision pinning the rates that were in force
    /// at the time). Useful to flag in admin UI: "no rate edit was recorded
    /// before this point — this is the pre-revision baseline".
    /// </summary>
    public bool IsBootstrap { get; set; }

    // ── Snapshot block — mirrors the rate-affecting fields of Staff ──────

    public string CommissionModel { get; set; } = "PERCENTAGE_TIERED";

    public List<CommissionTier> Tiers { get; set; } = new();
    public bool HasTieredPrivateCommission { get; set; } = true;
    public decimal FlatPrivateCommissionPct { get; set; } = 0.5m;

    public decimal GroupFlatRatePerClass { get; set; }
    public decimal GroupRatePerHead { get; set; }

    public decimal FreeGroupClassRate { get; set; }
    public decimal FreePrivateClassRate { get; set; }

    public decimal RatePerHead { get; set; }
    public List<HeadcountPayoutTier> HeadcountTiers { get; set; } = new();
    public decimal PrivateRatePerHead { get; set; }
    public List<HeadcountPayoutTier> PrivateHeadcountTiers { get; set; } = new();
    public bool UseMarginalHeadcountTiers { get; set; } = true;

    public decimal BaseSalary { get; set; }
    public decimal BaseRate { get; set; }
}

