using MongoDB.Driver;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Mongo-backed implementation of <see cref="IStaffRateRevisionService"/>.
///
/// <para>
/// Collection: <c>StaffRateRevisions</c>. A compound index on
/// <c>(StaffId, EffectiveFrom)</c> makes the as-of query a one-document
/// lookup — descending sort + limit 1, sub-millisecond at studio scale.
/// </para>
/// </summary>
public class StaffRateRevisionService : IStaffRateRevisionService
{
    private readonly IMongoCollection<StaffRateRevision> _revisions;
    private readonly IMongoCollection<Staff> _staff;

    public StaffRateRevisionService(MongoDbContext dbContext)
    {
        _revisions = dbContext.GetCollection<StaffRateRevision>("StaffRateRevisions");
        _staff = dbContext.GetCollection<Staff>("Staff");

        // Indexes:
        //   • Primary access pattern is "give me the revision in force at T
        //     for staff S" → descending EffectiveFrom inside a StaffId bucket
        //     gives us a one-document FirstOrDefault.
        //   • Listing the history for the staff form uses the same index in
        //     ascending order; Mongo will scan it both ways.
        var keys = Builders<StaffRateRevision>.IndexKeys
            .Ascending(r => r.StaffId)
            .Descending(r => r.EffectiveFrom);
        _revisions.Indexes.CreateOne(new CreateIndexModel<StaffRateRevision>(keys,
            new CreateIndexOptions { Name = "ix_staff_effectivefrom" }));
    }

    public async Task<StaffRateRevision> AppendRevisionAsync(
        Staff currentStaff,
        DateTime? effectiveFrom = null,
        string? changeNote = null,
        string? createdByUserId = null,
        bool isBootstrap = false)
    {
        var revision = new StaffRateRevision
        {
            StaffId = currentStaff.Id!,
            StaffNameSnapshot = currentStaff.Name ?? string.Empty,
            EffectiveFrom = effectiveFrom ?? DateTime.UtcNow,
            ChangeNote = changeNote,
            CreatedByUserId = createdByUserId,
            IsBootstrap = isBootstrap,

            CommissionModel = currentStaff.CommissionModel,
            // Deep-copy the tier lists so subsequent edits to the live Staff
            // document can't mutate the in-memory revision before persistence.
            // Bson serialisation would also copy on write, but defending against
            // a mistake here is cheap and the lists are tiny.
            Tiers = currentStaff.Tiers.Select(t => new CommissionTier
            {
                MinClasses = t.MinClasses,
                MaxClasses = t.MaxClasses,
                CommissionPercentage = t.CommissionPercentage,
            }).ToList(),
            HasTieredPrivateCommission = currentStaff.HasTieredPrivateCommission,
            FlatPrivateCommissionPct = currentStaff.FlatPrivateCommissionPct,

            GroupFlatRatePerClass = currentStaff.GroupFlatRatePerClass,
            GroupRatePerHead = currentStaff.GroupRatePerHead,

            FreeGroupClassRate = currentStaff.FreeGroupClassRate,
            FreePrivateClassRate = currentStaff.FreePrivateClassRate,

            RatePerHead = currentStaff.RatePerHead,
            HeadcountTiers = currentStaff.HeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            PrivateRatePerHead = currentStaff.PrivateRatePerHead,
            PrivateHeadcountTiers = currentStaff.PrivateHeadcountTiers.Select(h => new HeadcountPayoutTier
            {
                MinStudents = h.MinStudents,
                MaxStudents = h.MaxStudents,
                RatePerStudent = h.RatePerStudent,
            }).ToList(),
            UseMarginalHeadcountTiers = currentStaff.UseMarginalHeadcountTiers,

            BaseSalary = currentStaff.BaseSalary,
            BaseRate = currentStaff.BaseRate,
        };

        await _revisions.InsertOneAsync(revision);
        return revision;
    }

    public async Task<StaffRateRevision?> ResolveAsOfAsync(string staffId, DateTime asOf)
    {
        // Primary lookup: most-recent revision whose EffectiveFrom <= asOf.
        var inForce = await _revisions
            .Find(r => r.StaffId == staffId && r.EffectiveFrom <= asOf)
            .SortByDescending(r => r.EffectiveFrom)
            .FirstOrDefaultAsync();

        if (inForce is not null) return inForce;

        // Fallback A: any revision exists, but ALL of them are dated AFTER asOf.
        // This happens when a staff member is created today and someone asks for
        // their rates as of last month. Use the earliest known revision —
        // strictly speaking it isn't in force at asOf, but it's the closest
        // documented rate sheet and the alternative (returning null and refusing
        // to pay payroll) is worse for the user. The earliest is typically the
        // bootstrap revision anyway.
        var earliest = await _revisions
            .Find(r => r.StaffId == staffId)
            .SortBy(r => r.EffectiveFrom)
            .FirstOrDefaultAsync();
        if (earliest is not null) return earliest;

        // Fallback B: no revision exists for this staff yet. Lazy-bootstrap one
        // from the current live Staff document so this is the first and last
        // time we have to deal with the migration. Subsequent payroll runs go
        // through the fast path above.
        var liveStaff = await _staff.Find(s => s.Id == staffId).FirstOrDefaultAsync();
        if (liveStaff is null) return null;

        // EffectiveFrom is set to a sentinel "long ago" date so any future asOf
        // resolves to it cleanly. Using CreatedAt of the Staff row preserves a
        // touch of authenticity when present.
        var bootstrapFrom = liveStaff.CreatedAt == default
            ? new DateTime(2000, 1, 1, 0, 0, 0, DateTimeKind.Utc)
            : liveStaff.CreatedAt;

        return await AppendRevisionAsync(
            liveStaff,
            effectiveFrom: bootstrapFrom,
            changeNote: "Auto-generated baseline (no prior rate history recorded).",
            isBootstrap: true);
    }

    public async Task<IReadOnlyList<StaffRateRevision>> ListAsync(string staffId)
    {
        return await _revisions
            .Find(r => r.StaffId == staffId)
            .SortBy(r => r.EffectiveFrom)
            .ToListAsync();
    }

    public bool RateFieldsDiffer(Staff before, Staff after)
    {
        // Scalars first — cheap.
        if (before.CommissionModel != after.CommissionModel) return true;
        if (before.HasTieredPrivateCommission != after.HasTieredPrivateCommission) return true;
        if (before.FlatPrivateCommissionPct != after.FlatPrivateCommissionPct) return true;
        if (before.GroupFlatRatePerClass != after.GroupFlatRatePerClass) return true;
        if (before.GroupRatePerHead != after.GroupRatePerHead) return true;
        if (before.FreeGroupClassRate != after.FreeGroupClassRate) return true;
        if (before.FreePrivateClassRate != after.FreePrivateClassRate) return true;
        if (before.RatePerHead != after.RatePerHead) return true;
        if (before.PrivateRatePerHead != after.PrivateRatePerHead) return true;
        if (before.UseMarginalHeadcountTiers != after.UseMarginalHeadcountTiers) return true;
        if (before.BaseSalary != after.BaseSalary) return true;
        if (before.BaseRate != after.BaseRate) return true;

        // Tier ladders — order-sensitive comparison. A reordering edit alone
        // doesn't usually change math (we sort by Min on resolution) but to be
        // safe we treat it as a rate change so the admin sees the revision.
        if (!TiersEqual(before.Tiers, after.Tiers)) return true;
        if (!HeadcountTiersEqual(before.HeadcountTiers, after.HeadcountTiers)) return true;
        if (!HeadcountTiersEqual(before.PrivateHeadcountTiers, after.PrivateHeadcountTiers)) return true;

        return false;
    }

    private static bool TiersEqual(IReadOnlyList<CommissionTier> a, IReadOnlyList<CommissionTier> b)
    {
        if (a.Count != b.Count) return false;
        for (var i = 0; i < a.Count; i++)
        {
