public async Task<Staff> CreateStaffAsync(Staff staff)
{
    await _staff.InsertOneAsync(staff);
    await EnsureStudioRentalClientAsync(staff);

    await _revisions.AppendRevisionAsync(
        staff,
        effectiveFrom: staff.CreatedAt == default ? DateTime.UtcNow : staff.CreatedAt,
        changeNote: "Initial staff creation.");

    return staff;
}

public async Task UpdateStaffAsync(string id, Staff staff)
{
    staff.Id = id;
    staff.UpdatedAt = DateTime.UtcNow;

    var existing = await _staff.Find(s => s.Id == id).FirstOrDefaultAsync();
    if (existing is not null)
    {
        if (staff.CreatedAt == default) staff.CreatedAt = existing.CreatedAt;
        if (string.IsNullOrEmpty(staff.UserId)) staff.UserId = existing.UserId;
        if (string.IsNullOrEmpty(staff.PhotoUrl)) staff.PhotoUrl = existing.PhotoUrl;
        if (string.IsNullOrEmpty(staff.StudioRentalClientId)) staff.StudioRentalClientId = existing.StudioRentalClientId;

        if (string.IsNullOrEmpty(staff.Bio)) staff.Bio = existing.Bio;
        if (staff.YearsExperience == 0) staff.YearsExperience = existing.YearsExperience;
        if (staff.Specialties == null || staff.Specialties.Count == 0)
            staff.Specialties = existing.Specialties;
    }

    await EnsureStudioRentalClientAsync(staff);
    await _staff.ReplaceOneAsync(s => s.Id == id, staff);

    var linkedUserId = !string.IsNullOrWhiteSpace(staff.UserId) ? staff.UserId : existing?.UserId;
    if (string.IsNullOrWhiteSpace(linkedUserId))
    {
        linkedUserId = await _users
            .Find(u => u.StaffId == id)
            .Project(u => u.Id)
            .FirstOrDefaultAsync();
    }
    if (!string.IsNullOrWhiteSpace(linkedUserId))
