  { id: "6a476d87d6425f2d99c684dd", amt: "72000" },   // Lower Back Love, Sep30 03:00 — rev 400,000
  { id: "6a476d86d6425f2d99c683f1", amt: "207000" },  // Sculpt Arms & Shoulders, Sep30 04:00 — rev 1,150,000
  { id: "6a476d87d6425f2d99c684e8", amt: "157500" },  // Lower Back Love, Sep30 09:00 — rev 875,000
  { id: "6a476d86d6425f2d99c68407", amt: "90000" },   // Sculpt Arms & Shoulders, Sep30 10:00 — rev 500,000
  { id: "6a476d87d6425f2d99c685aa", amt: "153000" },  // Private Session, Sep30 02:00 — rev 850,000
