db.CalendarSessions.find({_id: {$in: overrides.map(function(o){return ObjectId(o.id);})}}, {ClassName:1, StartTime:1, CommissionOverride:1}).forEach(s=>print(s.StartTime + " | " + s.ClassName + " | override=" + s.CommissionOverride));
EOF
