var invId = ObjectId("6abe3061ac4362da365f0374");
var payId = ObjectId("6abe3061ac4362da365f0376");

var inv = db.Invoices.findOne({_id: invId});
var pay = db.Payments.findOne({_id: payId});

// Shift both IssueDate and PaymentDate back exactly 1 day (preserving time-of-day),
// since the washout's cash-basis revenue match requires BOTH to fall in the same
// month -- moving only IssueDate would drop this 18,000,000 out of both months.
function shiftBackOneDay(d) {
  return new Date(d.getTime() - 24*60*60*1000);
}

var newIssueDate = shiftBackOneDay(inv.IssueDate);
var newPaymentDate = shiftBackOneDay(pay.PaymentDate);

print("Invoice IssueDate: " + inv.IssueDate + " -> " + newIssueDate);
print("Payment PaymentDate: " + pay.PaymentDate + " -> " + newPaymentDate);

db.Invoices.updateOne({_id: invId}, {$set: {
  IssueDate: newIssueDate,
  Notes: "Date corrected 2026-10-01: invoice originally logged Oct 1 but the transaction actually happened Sept 30; IssueDate and the linked payment's PaymentDate both moved back one day so September's washout picks up this revenue correctly (cash-basis revenue requires both to match the same month).",
}});

db.Payments.updateOne({_id: payId}, {$set: { PaymentDate: newPaymentDate }});

print("=== VERIFY ===");
printjson(db.Invoices.findOne({_id: invId}, {IssueDate:1, Notes:1}));
printjson(db.Payments.findOne({_id: payId}, {PaymentDate:1}));
EOF
