using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.Services;

/// <summary>
/// Background service that materialises <see cref="CalendarSession"/> rows on a
/// rolling admin-configurable horizon (default 30 days) every 6 hours.
///
/// <para><b>V2</b>: Reads <see cref="ClassBlueprint.WeeklySlots"/> via
/// <see cref="ISchedulingService.MaterialiseAllBlueprintsAsync"/>.</para>
///
/// <para>The horizon is now sourced from
/// <see cref="GlobalSettings.MaterialisationHorizonDays"/> (admin-configurable
/// in Settings → Schedule tab) instead of a hardcoded constant.</para>
/// </summary>
public class ScheduleMaterialiserBackgroundService : BackgroundService
{
    private readonly IServiceProvider _services;
    private readonly ILogger<ScheduleMaterialiserBackgroundService> _logger;

    /// <summary>Fallback horizon when the setting hasn't been configured yet.</summary>
    private const int DefaultHorizonDays = 30;

    public ScheduleMaterialiserBackgroundService(
        IServiceProvider services,
        ILogger<ScheduleMaterialiserBackgroundService> logger)
    {
        _services = services;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        // First tick fires after a short delay so app startup isn't blocked
        // by a potentially long materialise sweep.
        await Task.Delay(TimeSpan.FromMinutes(1), stoppingToken);

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();

                // Read the admin-configured horizon from GlobalSettings.
                var settingsService = scope.ServiceProvider.GetRequiredService<ISettingsService>();
                var settings = await settingsService.GetAsync(stoppingToken);
                var horizonDays = settings.MaterialisationHorizonDays > 0
                    ? settings.MaterialisationHorizonDays
                    : DefaultHorizonDays;

                // V2: Blueprint-driven materialisation (sole engine)
                var scheduling = scope.ServiceProvider.GetRequiredService<ISchedulingService>();
                var (bps, created) = await scheduling.MaterialiseAllBlueprintsAsync(horizonDays, DateTime.UtcNow);
                _logger.LogInformation(
                    "V2 Materialiser tick: blueprints={Blueprints} sessionsCreated={Created} horizonDays={Horizon}",
                    bps, created, horizonDays);
            }
            catch (Exception ex)
            {
                // Top-level guard — a fault here would tear down the
                // hosted service for the rest of the process. Log and
                // wait for the next tick.
                _logger.LogError(ex, "ScheduleMaterialiserBackgroundService tick threw");
            }

            // 6h cadence. The horizon is typically 30+ days so we have ample slack.
            await Task.Delay(TimeSpan.FromHours(6), stoppingToken);
        }
    }
}

