namespace SoulPilates.Core.Entities;

/// <summary>
/// The full receptionist-KPI configuration for one calendar month, plus that
/// month's live inputs (Google review count, notes). Each month owns its own
/// config so settings can differ month-to-month; a new month auto-inherits the
/// most recent prior month's config (see the service's get-or-create), so nothing
/// has to be re-entered unless the studio wants to change it.
/// </summary>
public class ReceptionistKpiMonthOverride : BaseEntity
{
    public int Year { get; set; }
    public int Month { get; set; }

    // ── Live monthly inputs ──────────────────────────────────────
    public bool KpiEnabled { get; set; } = true;
    public int GoogleReviewCount { get; set; }
    public string Note { get; set; } = string.Empty;

    // ── Per-month config (auto-carried forward, editable per month) ──
    /// <summary>
    /// False on legacy rows that predate per-month config, and on a bare row before
    /// seeding. The service seeds the config fields below from the previous month
    /// (or global defaults) and flips this true so it only happens once.
    /// </summary>
    public bool ConfigInitialized { get; set; } = false;

    public decimal BonusPoolAmount { get; set; } = 5_000_000m;
    public decimal DailyTaskCompletionPercent { get; set; } = 1m;
    public decimal AttendanceCommissionPerHead { get; set; } = 0m;
    public string AttendanceSplitMode { get; set; } = "EQUAL_ACTIVE";

    public List<ReceptionistDailyTaskDefinition> DailyTasks { get; set; } = new();
    public List<ReceptionistKpiTier> RevenueTiers { get; set; } = new();
    public List<ReceptionistKpiTier> PackageSalesTiers { get; set; } = new();
    public List<ReceptionistKpiTier> GoogleReviewTiers { get; set; } = new();
}
