// ── Metrics ──────────────────────────────────────────────────

private async Task<ReceptionistMonthMetrics> ComputeMonthMetricsAsync(
    int year,
    int month,
    ReceptionistKpiMonthOverride monthConfig,
    List<Staff> participants,
    CancellationToken ct)
{
    var start = new DateTime(year, month, 1, 0, 0, 0, DateTimeKind.Utc);
    var end = start.AddMonths(1);

    var paidInvoices = await _invoices
        .Find(x => x.Status == "PAID" && x.IssueDate >= start && x.IssueDate < end)
        .ToListAsync(ct);

    var grossRevenue = paidInvoices.Sum(x => x.TotalNet);
    var packageSales = await CountPackageSalesAsync(paidInvoices, ct);

    // Receptionist-uploaded Google-review screenshots for this month that a manager has
    // APPROVED. This count is ADDED to the admin-entered manual GoogleReviewCount to form
    // the metric that the review tiers reward against — see EffectiveGoogleReviewCount.
    // Pending/Rejected uploads do NOT count, so with zero approved uploads the effective
    // value equals the manual value and the manager's manual path is unchanged.
    var reviewUploadCount = (int)await _reviewUploads
        .CountDocumentsAsync(
            x => x.Year == year && x.Month == month && x.Status == ReviewApprovalStatus.Approved,
            cancellationToken: ct);

    // Completed sessions this month (with their local start time), and the paid
    // headcount per session.
    var sessions = await _sessions
        .Find(x => x.Status == "COMPLETED" && x.StartTime >= start && x.StartTime < end && !x.IsFreelance)
        .Project(x => new { x.Id, x.StartTime })
        .ToListAsync(ct);

    var headBySession = new Dictionary<string, int>();
    decimal attendanceHeadcount = 0m;
    if (sessions.Count > 0)
    {
        var sessionIds = sessions.Select(s => s.Id).ToList();
        var attendanceRows = await _attendances
            .Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.In(x => x.CalendarSessionId, sessionIds),
                Builders<Attendance>.Filter.In(x => x.Status, CountingAttendanceStatuses)))
            .ToListAsync(ct);

        foreach (var a in attendanceRows)
        {
            if (string.IsNullOrWhiteSpace(a.CalendarSessionId)) continue;
            headBySession[a.CalendarSessionId] = headBySession.GetValueOrDefault(a.CalendarSessionId) + Math.Max(1, a.Quantity);
        }
        attendanceHeadcount = headBySession.Values.Sum();
    }

    // Attendance commission is SHIFT-BASED: for each class, only receptionists who
    // were on shift (within a work window, excluding lunch breaks) at the class's
    // local start time earn the per-head commission for that class's attendees,
    // split equally between them. If nobody was on shift, that class pays nothing.
    var perHead = Math.Max(0m, monthConfig.AttendanceCommissionPerHead);
    var commissionByStaff = new Dictionary<string, decimal>();
    decimal distributedPool = 0m;

    if (headBySession.Count > 0 && perHead > 0m && participants.Count > 0)
    {
        var from = new DateOnly(year, month, 1);
        var to = from.AddMonths(1).AddDays(-1);
        var occurrences = await _shifts.GetScheduleAsync(from, to, null);
        var receptionistIds = participants.Where(p => p.Id != null).Select(p => p.Id!).ToHashSet();
        var occByDate = occurrences
            .Where(o => receptionistIds.Contains(o.StaffId))
            .GroupBy(o => o.Date)
            .ToDictionary(g => g.Key, g => g.ToList());

        foreach (var s in sessions)
        {
            if (!headBySession.TryGetValue(s.Id!, out var head) || head <= 0) continue;
            var local = StudioTime.Local(s.StartTime);
            var dateKey = local.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            var minutes = local.Hour * 60 + local.Minute;
            if (!occByDate.TryGetValue(dateKey, out var dayOccs)) continue;

            var covering = dayOccs
                .Where(o => IsWithinShift(o, minutes))
                .Select(o => o.StaffId)
                .Distinct()
                .ToList();
            if (covering.Count == 0) continue;

            var sessionCommission = head * perHead;
            var perStaff = sessionCommission / covering.Count;
            foreach (var sid in covering)
                commissionByStaff[sid] = commissionByStaff.GetValueOrDefault(sid) + perStaff;
            distributedPool += sessionCommission;
        }
    }

    return new ReceptionistMonthMetrics
    {
        GrossRevenue = grossRevenue,
        PackageSalesCount = packageSales,
        ReviewUploadCount = reviewUploadCount,
        AttendanceHeadcount = attendanceHeadcount,
        AttendanceCommissionPool = RoundVnd(distributedPool),
        CommissionByStaff = commissionByStaff,
    };
}

/// <summary>True if <paramref name="minutes"/> (local minutes-of-day) falls inside a shift
/// occurrence's work window and NOT inside one of its breaks.</summary>
private static bool IsWithinShift(StaffShiftOccurrence occ, int minutes)
{
    if (!TryMinutes(occ.StartTime, out var s) || !TryMinutes(occ.EndTime, out var e)) return false;
    if (minutes < s || minutes >= e) return false;
    foreach (var b in occ.Breaks ?? new())
    {
        if (TryMinutes(b.Open, out var bo) && TryMinutes(b.Close, out var bc)
            && minutes >= bo && minutes < bc)
            return false;
    }
    return true;
}

private static bool TryMinutes(string? hhmm, out int minutes)
{
    minutes = 0;
    if (string.IsNullOrWhiteSpace(hhmm)) return false;
    var parts = hhmm.Split(':');
    if (parts.Length < 2) return false;
    if (!int.TryParse(parts[0], out var h) || !int.TryParse(parts[1], out var m)) return false;
    minutes = h * 60 + m;
    return true;
}

private async Task<int> CountPackageSalesAsync(List<Invoice> paidInvoices, CancellationToken ct)
{
    var legacyProductIds = paidInvoices
        .SelectMany(x => x.Lines)
        .Where(x => string.IsNullOrWhiteSpace(x.ProductTypeSnapshot) && !string.IsNullOrWhiteSpace(x.ProductId))
        .Select(x => x.ProductId!)
        .Distinct()
        .ToList();

    var legacyProducts = legacyProductIds.Count == 0
        ? new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        : (await _products.Find(x => legacyProductIds.Contains(x.Id!)).ToListAsync(ct))
            .ToDictionary(x => x.Id!, x => x.Type ?? string.Empty, StringComparer.OrdinalIgnoreCase);

    return paidInvoices
        .SelectMany(x => x.Lines)
        .Count(line =>
        {
            var productType = line.ProductTypeSnapshot;
            if (string.IsNullOrWhiteSpace(productType) && !string.IsNullOrWhiteSpace(line.ProductId))
                legacyProducts.TryGetValue(line.ProductId, out productType);
            return string.Equals(productType, "PACKAGE", StringComparison.OrdinalIgnoreCase);
        });
}

