  Email: null, IsStudioRentalProfile: false, StudioRentalStaffId: null,
  PhoneNumber: null, PhoneCountryCode: null, ContactPlatform: "NONE", CountryOfOrigin: "",
  InternalNotes: "Placeholder client for a manual +1 package credit on Linh's October 2026 receptionist KPI. Not a real customer. Safe to delete together with its invoice.",
  Notes: [], MedicalHistory: "", Tags: ["ARTIFICIAL"], DateOfBirth: null, ReferralSource: null,
  ReferredByPartnerId: null, FirstVisitDate: null, LifetimeValue: NumberDecimal("0"),
  RetentionRemindersOptedOut: true, UnsubscribeToken: null
};
var cRes = db.Clients.insertOne(client);
print("Placeholder client: " + cRes.insertedId);

// Next invoice number for today's prefix, using the app's own count+1 rule
var prefix = "SP-INV-" + now.toISOString().slice(2,10).replace(/-/g,"") + "-";
var count = db.Invoices.countDocuments({InvoiceNumber: {$regex: "^" + prefix}});
var number = prefix + String(count + 1).padStart(4, "0");

var inv = {
  CreatedAt: now, UpdatedAt: null,
  InvoiceNumber: number,
  ClientId: cRes.insertedId,
  IssueDate: now,
  TotalGross: NumberDecimal("0"), TotalDiscount: NumberDecimal("0"), TotalTax: NumberDecimal("0"), TotalNet: NumberDecimal("0"),
  RefereePartnerId: null, Status: "PAID",
  Notes: "ARTIFICIAL: manual +1 package credit for Linh's October 2026 receptionist KPI. $0, no real sale. Delete this invoice and its placeholder client to remove the credit.",
  PaymentMethod: null, VoucherRedemptionId: null, PromoRedemptionId: null,
  StockDeductedAt: now, OnlineFeeAmount: NumberDecimal("0"),
  Lines: [{
    _id: null, CreatedAt: now, UpdatedAt: null, InvoiceId: null,
    ProductId: ObjectId("e8bdadec5162cd6bf87ca11b"), VariantId: null, Quantity: 1,
    UnitPrice: NumberDecimal("0"), LineDiscount: NumberDecimal("0"), LineTotal: NumberDecimal("0"),
    AttendanceId: null, CalendarSessionId: null, Description: "Artificial KPI credit", ProductTypeSnapshot: "PACKAGE"
  }]
};
var iRes = db.Invoices.insertOne(inv);
print("Invoice " + number + " inserted: " + iRes.insertedId);

// Verify exactly what the KPI counts
var start = new Date("2026-10-01T00:00:00Z"), end = new Date("2026-11-01T00:00:00Z"), n = 0;
db.Invoices.find({Status:"PAID", IssueDate:{$gte:start,$lt:end}}).forEach(function(i){
  i.Lines.forEach(function(l){ if (l.ProductTypeSnapshot === "PACKAGE") { n++; print("  counts: " + i.InvoiceNumber + " net=" + i.TotalNet); } });
});
print("October PackageSalesCount now = " + n);
