    /// <summary>
    /// SPM-83: instructor-scoped client search for the quick-add-booking UI.
    /// Returns a MINIMAL projection (id/name/phone/email) so instructors can pick an
    /// existing client to add to their own class WITHOUT exposing the internal notes /
    /// medical history that the admin-only GET /api/client list returns.
    /// </summary>
    [HttpGet("clients")]
    public async Task<IActionResult> SearchClients([FromQuery] string? search)
    {
        var clients = await _clientService.SearchClientsAsync(search ?? "");
        var results = clients.Select(c => new { id = c.Id, name = c.FullName, phone = c.PhoneNumber, email = c.Email });
        return Ok(results);
    }

    /// <summary>
    /// Sentinel <c>viewAs</c> value (SPM-103) that requests the
    /// whole-studio "All instructors" aggregate view rather than a
    /// single impersonated instructor. Matched case-insensitively.
    /// </summary>
    private const string ViewAsAll = "all";

    /// <summary>
    /// Resolves the effective Staff ID for this request.
    ///
    /// <para>
    /// For Admin / SuperAdmin / Owner users: if a <c>viewAs</c> query
    /// parameter is present and non-empty, returns that value so the
    /// privileged user can impersonate any instructor. Otherwise falls
    /// back to their own JWT <c>staff_id</c> claim (which may be null
    /// for admin/owner-only users with no Staff link).
    /// </para>
    ///
    /// <para>
    /// For Instructor users: always returns their own JWT <c>staff_id</c>
    /// claim, ignoring <c>viewAs</c> entirely (defence-in-depth).
    /// </para>
    ///
    /// <para>
    /// SPM-103: the <c>viewAs=all</c> sentinel is NOT a staff id — it is
    /// handled separately by <see cref="IsAllInstructorsMode"/> on the
    /// schedule/calendar endpoints. This method returns null for it so
    /// any caller that does not opt into the aggregate view degrades to
    /// the "no staff linked" path rather than treating "all" as an id.
    /// </para>
    /// </summary>
    private string? ResolveStaffId()
    {
        var ownStaffId = User.FindFirst("staff_id")?.Value;
        var viewAs = HttpContext.Request.Query["viewAs"].FirstOrDefault();
        if (!string.IsNullOrWhiteSpace(viewAs) && IsAdminRole())
        {
            if (string.Equals(viewAs, ViewAsAll, StringComparison.OrdinalIgnoreCase))
                return null;
            return viewAs;
        }
        return ownStaffId;
    }

    /// <summary>
    /// SPM-103 — true when a privileged user (Admin / SuperAdmin / Owner)
    /// has requested the whole-studio "All instructors" aggregate view
    /// via <c>?viewAs=all</c>. Instructor-role tokens can never enter
    /// this mode (the <c>viewAs</c> query param is ignored for them).
    /// </summary>
    private bool IsAllInstructorsMode()
    {
        if (!IsAdminRole())
            return false;
        var viewAs = HttpContext.Request.Query["viewAs"].FirstOrDefault();
        return string.Equals(viewAs, ViewAsAll, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Returns true when the authenticated user carries a privileged
    /// role that may impersonate instructors via <c>?viewAs</c>: Admin,
    /// SuperAdmin, or (SPM-103) Owner. Owners get the same schedule /
    /// roster impersonation parity as admins, but are still blocked from
    /// the earnings / financial endpoints (enforced per-endpoint).
    /// </summary>
    private bool IsAdminRole()
    {
        return User.IsInRole("Admin") || User.IsInRole("SuperAdmin") || User.IsInRole("Owner");
    }

    /// <summary>
    /// Head Instructor — a senior instructor who oversees the whole studio's
    /// schedule. Grants read access to EVERY instructor's classes (calendar +
    /// class detail), but NOT financial impersonation: earnings stay their own,
    /// so this is intentionally separate from <see cref="IsAdminRole"/>.
    /// </summary>
    private bool IsHeadInstructor() => User.IsInRole("HeadInstructor");

    /// <summary>
    /// Returns the redacted <c>InstructorProfileDto</c> for the
    /// authenticated user (or the impersonated instructor when
    /// <c>?viewAs={staffId}</c> is supplied by an admin).
    /// Returns 404 with <c>{ profileLinked = false }</c>
    /// when no staff row is found.

