    [HttpGet("bookings")]
    public async Task<IActionResult> GetBookings([FromQuery] BookingListQuery query)
    {
        if (!IsAllInstructorsMode())
        {
            var staffId = ResolveStaffId();
            if (string.IsNullOrWhiteSpace(staffId))
                return NotFound(new { profileLinked = false });
            query.InstructorId = staffId;
        }

        var result = await _schedulingService.ListBookingsAsync(query);
        return Ok(result);
    }

    /// <summary>
    /// Instructor-safe class detail used by the schedule drawer.
    /// </summary>
    [HttpGet("class/{sessionId}")]
    public async Task<IActionResult> GetClassDetail(string sessionId)
    {
        var detail = await _schedulingService.GetClassDetailAsync(sessionId);
        if (detail is null)
            return NotFound(new { message = "Class session not found." });

        if (!IsAdminRole() && !IsHeadInstructor())
        {
            var staffId = ResolveStaffId();
            if (string.IsNullOrWhiteSpace(staffId))
                return NotFound(new { profileLinked = false });
            if (!string.Equals(detail.InstructorId, staffId, System.StringComparison.Ordinal))
                return StatusCode(403, new { message = "You can only view your own class details." });
        }

        return Ok(detail);
    }

