      if (p.email) cRows.push(`<a href="mailto:${esc(p.email)}" style="display:flex;align-items:center;gap:8px;color:var(--color-text-primary,#eee);text-decoration:none;font-size:14px;word-break:break-all;"><span>✉️</span><span>${esc(p.email)}</span></a>`);
