  }
  function icHideMultiDD() { document.getElementById('icMultiDropdown').classList.remove('open'); _icMultiSessions = []; }

  document.getElementById('icMultiList').addEventListener('click', e => {
    const btn = e.target.closest('[data-icidx]'); if (!btn) return;
    e.stopPropagation();
    const s = _icMultiSessions[parseInt(btn.dataset.icidx)];
    icHideMultiDD();
    if (s) insOpenDrawer(s.id);
  });

  // Close floating on outside click
  document.addEventListener('click', e => {
    const dd = document.getElementById('icMultiDropdown');
    if (dd.classList.contains('open') && !dd.contains(e.target)) icHideMultiDD();
  });

  // Batch attendee fetch
  async function icBatchFetchAtt() {
    const ids = icAllSessions.filter(s => s.status !== 'BLOCKED' && s.status !== 'CANCELLED').map(s => s.id);
    const batch = 8;
    for (let i = 0; i < ids.length; i += batch) {
      await Promise.all(ids.slice(i, i + batch).map(async sid => {
        try {
          const bookings = await fetch(vaUrl(`${API}/api/scheduling/session/${sid}/bookings`),
            { headers: { Authorization: 'Bearer ' + token } }).then(r => r.json());
          icAttCache.set(sid, bookings);
          icPatchNames(sid, bookings);
        } catch {}
      }));
    }
  }
  function icPatchNames(sid, bookings) {
    const el = document.querySelector(`.ic-ev-clients[data-icsid="${sid}"]`);
    if (!el || !bookings.length) return;
    const max = 3;
    const lines = bookings.slice(0, max).map(b => {
      const parts = (b.clientName || 'Unknown').split(' ');
      const abbr = parts.length > 1 ? `${parts[0]} ${parts[parts.length-1][0]}.` : parts[0];
      return `<div class="ic-ev-client-line">⬤ ${esc(abbr)}</div>`;
    });
    if (bookings.length > max) lines.push(`<div class="ic-ev-more">+${bookings.length - max} more</div>`);
    el.innerHTML = lines.join('');
  }

  // Wire calendar controls
  document.getElementById('icPrevBtn').addEventListener('click', () => icChangeWeek(-1));
  document.getElementById('icNextBtn').addEventListener('click', () => icChangeWeek(1));
  document.getElementById('icTodayBtn').addEventListener('click', icJumpToday);
  document.getElementById('icViewWeek').addEventListener('click', () => icSetView('week'));
  document.getElementById('icViewDay').addEventListener('click', () => icSetView('day'));
  document.getElementById('icHasAttendees').addEventListener('change', (e) => {
    classState.hasAttendees = e.target.checked;
    const myCb = document.getElementById('insHasAttendees');
    if (myCb) myCb.checked = classState.hasAttendees;
    icRenderGrid();
  });

  // ── Init on load ──
  insInit();
