  // ── Drawer tab switching ──
  function insDrawerTab(tab) {
    document.querySelectorAll('.ins-dp-tab').forEach(t => t.classList.toggle('active', t.dataset.tab === tab));
    const map = { attendees: 'insTPAttendees', waitlist: 'insTPWaitlist', details: 'insTPDetails' };
    Object.values(map).forEach(id => document.getElementById(id)?.classList.remove('active'));
    document.getElementById(map[tab])?.classList.add('active');
  }
  window.insDrawerTab = insDrawerTab;

  // ── Roster ──
  async function insRefreshRoster(sessionId) {
    const roster = document.getElementById('insRoster');
    if (!roster) return;

    let attendees = [];
    try {
      const r = await fetch(vaUrl(`${API}/api/instructor/class/${sessionId}`), {
        headers: { Authorization: 'Bearer ' + token },
      });
      if (r.ok) {
        const detail = await r.json();
        _currentDrawerSession = detail;
        attendees = detail.attendees || [];
      }
    } catch {}

    const countEl = document.getElementById('insAttCount');
    if (countEl) countEl.textContent = `(${attendees.length})`;

    if (!attendees.length) {
      roster.innerHTML = '<div style="text-align:center;padding:32px 20px;color:var(--color-text-muted);font-size:12px;">No bookings for this session.</div>';
      return;
    }

    const avatarColors = ['#2BB7A3','#8B5CF6','#F4923C','#3B82F6','#EC4899','#F59E0B','#10B981','#6366F1'];

    // SPM-79 — reschedule is offered for BOOKED attendees on a genuinely-upcoming
    // SCHEDULED session the instructor owns (admins/owners impersonating may move
    // any booking). Mirrors the transfer ownership gate; aggregate "all" view is
    // read-only so no action is exposed there.
    const sess = _currentDrawerSession;
    const _ownsRoster = _isAdmin || (myStaffId && sess?.instructorId === myStaffId);
    const canReschedule = !_isAllInstructors && _ownsRoster
      && sess?.status === 'SCHEDULED' && sess?.startTime && new Date(sess.startTime) > new Date();

    // Cache for the attendee profile modal (opened by tapping a row).
    window._insRosterAtt = attendees;
    window._insCanManageRoster = _ownsRoster && !_isAllInstructors;
    roster.innerHTML = attendees.map((a, idx) => {
      const initials = (a.clientName || 'U').split(' ').map(w => w[0]).join('').substring(0, 2).toUpperCase();
      const ac = avatarColors[idx % avatarColors.length];
      const statusNorm = (a.status === 'CHECKED_IN') ? 'ARRIVED' : (a.status || 'BOOKED');

