    [HttpGet("session/{sessionId}/waitlist")]
    public async Task<IActionResult> GetSessionWaitlist(string sessionId)
    {
        var session = await _schedulingService.GetSessionByIdAsync(sessionId);
        if (session == null)
            return NotFound(new { message = "Session not found." });

        if (!IsAdminRole() && !IsHeadInstructor())
        {
            var staffId = ResolveStaffId();
            if (string.IsNullOrWhiteSpace(staffId))
                return NotFound(new { profileLinked = false });
            if (!string.Equals(session.InstructorId, staffId, System.StringComparison.Ordinal))
                return StatusCode(403, new { message = "You can only view the waitlist for your own sessions." });
        }

        var entries = await _waitlistService.GetActiveForSessionAsync(sessionId);
        return Ok(entries.Select((e, i) => new
        {
            entryId = e.Id,
            position = i + 1,
            clientId = e.ClientId,
            clientName = e.ClientName,
            clientPhone = e.ClientPhone,
            clientEmail = e.ClientEmail,
            joinedAt = e.JoinedAt,
        }));
    }

    /// <summary>
    /// P3-S10 — current-month earnings for the instructor.
    /// Live recalc — does not write a <see cref="SoulPilates.Core.Entities.PayrollRun"/>.
    /// Supports <c>?viewAs={staffId}</c> for admin impersonation.
    ///
    /// <para>
    /// SPM-103: the Owner role is deliberately NOT granted instructor
    /// earnings / financial visibility. Owners are allowed onto this
    /// controller only for the schedule / roster impersonation parity,
    /// so this endpoint explicitly rejects Owner-only tokens with 403.
    /// Admin / SuperAdmin retain their existing access; instructors keep
    /// their own earnings.
    /// </para>
    /// </summary>

