    [HttpGet("bookings")]
    [HttpGet("class-days")]
    public async Task<IActionResult> GetClassDays([FromQuery] int? year = null, [FromQuery] int? month = null)
    {
        var staffId = ResolveStaffId();
        if (string.IsNullOrWhiteSpace(staffId))
            return NotFound(new { profileLinked = false });

        var nowLocal = DateTime.UtcNow + TimeSpan.FromHours(7);
        var y = year ?? nowLocal.Year;
        var mo = month ?? nowLocal.Month;

        var counts = await _instructorService.GetClassDaysAsync(staffId, y, mo);
        return Ok(new
        {
            year = y,
            month = mo,
            total = counts.Values.Sum(),
            counts = counts.ToDictionary(k => k.Key.ToString(), v => v.Value),
        });
    }

