    public async Task<IActionResult> GetCalendarSessions([FromQuery] DateTime start, [FromQuery] DateTime end)
    {
        var allSessions = await _schedulingService.GetSessionsAsync(start, end);

        // SPM-103 — "All instructors" aggregate: return every
        // instructor's sessions, unfiltered. Head Instructors always see the
        // whole studio's schedule on their own portal.
        if (IsAllInstructorsMode() || IsHeadInstructor())
            return Ok(allSessions);

        var staffId = ResolveStaffId();
        if (string.IsNullOrWhiteSpace(staffId))
            return NotFound(new { profileLinked = false });

        var mySessions = allSessions.Where(s => s.InstructorId == staffId);
        return Ok(mySessions);
    }

