using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Options;
using SoulPilates.Core.Interfaces;

namespace SoulPilates.API.Authorization;

/// <summary>
/// Authorization requirement for a single admin page module (e.g. "clients").
/// Access is granted when EITHER the caller's role enables the module in
/// <c>RoleAccessSettings</c>, OR the caller carries a per-user <c>module</c>
/// claim for it (set from <c>User.AllowedAdminModules</c> at login). This keeps
/// the backend gate identical to the AdminLayout nav gate — one source of truth.
/// </summary>
public sealed class ModuleRequirement : IAuthorizationRequirement
{
    public string ModuleKey { get; }
    public ModuleRequirement(string moduleKey) => ModuleKey = moduleKey.Trim().ToLowerInvariant();
}

public sealed class ModuleAuthorizationHandler : AuthorizationHandler<ModuleRequirement>
{
    private readonly ISettingsService _settings;

    public ModuleAuthorizationHandler(ISettingsService settings) => _settings = settings;

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context, ModuleRequirement requirement)
    {
        var user = context.User;
        if (user?.Identity?.IsAuthenticated != true) return;

        // 1) Per-user access — an explicit `module` claim always suffices.
        if (user.FindAll("module").Any(c =>
                string.Equals(c.Value?.Trim(), requirement.ModuleKey, StringComparison.OrdinalIgnoreCase)))
        {
            context.Succeed(requirement);
            return;
        }

        // Custom-access accounts are fully governed by their explicit module set
        // above — no role fallback, so a page can be genuinely revoked per user.
        if (user.HasClaim(c => string.Equals(c.Type, "access_mode", StringComparison.OrdinalIgnoreCase)
                               && string.Equals(c.Value, "custom", StringComparison.OrdinalIgnoreCase)))
            return;

        // 2) Role default — the caller's role enables the module in RoleAccessSettings.
        var role = (user.FindFirstValue(ClaimTypes.Role)
                    ?? user.Claims.FirstOrDefault(c => string.Equals(c.Type, "role", StringComparison.OrdinalIgnoreCase))?.Value
                    ?? string.Empty).Trim().ToLowerInvariant();
        if (string.IsNullOrEmpty(role)) return;

        var settings = await _settings.GetAsync();
        var roleAccess = (settings.RoleAccessSettings ?? new List<Core.Entities.RoleAccessSetting>())
            .FirstOrDefault(x => string.Equals(x.RoleKey, role, StringComparison.OrdinalIgnoreCase));

        if (roleAccess is { IsEnabled: true } &&
            roleAccess.EnabledModuleKeys.Any(k =>
                string.Equals(k?.Trim(), requirement.ModuleKey, StringComparison.OrdinalIgnoreCase)))
        {
            context.Succeed(requirement);
        }
    }
}

/// <summary>
/// Materialises "Module:{key}" policies on demand so any controller can write
/// <c>[Authorize(Policy = "Module:clients")]</c> without pre-registering each
/// module. Falls back to the default provider for all other policy names.
/// </summary>
public sealed class ModulePolicyProvider : IAuthorizationPolicyProvider
{
    public const string Prefix = "Module:";
    private readonly DefaultAuthorizationPolicyProvider _fallback;

    public ModulePolicyProvider(IOptions<AuthorizationOptions> options)
        => _fallback = new DefaultAuthorizationPolicyProvider(options);

    public Task<AuthorizationPolicy> GetDefaultPolicyAsync() => _fallback.GetDefaultPolicyAsync();
    public Task<AuthorizationPolicy?> GetFallbackPolicyAsync() => _fallback.GetFallbackPolicyAsync();

    public Task<AuthorizationPolicy?> GetPolicyAsync(string policyName)
    {
        if (policyName?.StartsWith(Prefix, StringComparison.OrdinalIgnoreCase) == true)
        {
            var moduleKey = policyName.Substring(Prefix.Length);
            var policy = new AuthorizationPolicyBuilder()
                .RequireAuthenticatedUser()
                .AddRequirements(new ModuleRequirement(moduleKey))
                .Build();
            return Task.FromResult<AuthorizationPolicy?>(policy);
        }
        return _fallback.GetPolicyAsync(policyName!);
    }
}

