using SoulPilates.Core.DTOs;

namespace SoulPilates.Services;

/// <summary>
/// Strips contact details, package usage, payment amounts and promo / invoice links from client-facing
/// DTOs before they are returned to a plain Instructor. Instructors may see WHO is in their classes
/// (name, seats, status, visit history, medical notes for safety) but not how to contact them, what
/// package they hold, or what they have spent. Only applied to the plain Instructor role — Admin,
/// Receptionist, Manager and Head Instructor responses are never passed through here.
/// </summary>
public static class InstructorClientRedaction
{
    /// <summary>Instructors can tell "paid" from "unpaid" but never learn that a client is using a package.</summary>
    public static string CoarsePaymentStatus(string? status) =>
        string.Equals(status, "package", StringComparison.OrdinalIgnoreCase) ? "paid" : (status ?? "unpaid");

    public static void Apply(ClassDetailDto detail)
    {
        detail.ClientInfoRestricted = true;
        foreach (var a in detail.Attendees)
        {
            a.ClientPhone = null;
            a.ClientEmail = null;
            a.PaymentMethod = null;
            a.AmountPaid = 0m;
            a.AmountDueAtStudio = 0m;
            a.PromoCode = null;
            a.LinkedInvoiceId = null;
            a.LinkedInvoiceNumber = null;
            a.PaymentStatus = CoarsePaymentStatus(a.PaymentStatus);
        }
    }

    public static void Apply(BookingListDto b)
    {
        b.ClientPhone = null;
        b.MarketingSource = null;
        b.PromoCode = null;
        b.PaymentMethod = null;
        b.AmountPaid = 0m;
        b.AmountDueAtStudio = 0m;
        b.LinkedInvoiceId = null;
        b.LinkedInvoiceNumber = null;
        b.PaymentStatus = CoarsePaymentStatus(b.PaymentStatus);
    }

    public static void Apply(SessionRosterDto r)
    {
        r.ClientPhone = null;
        r.PaymentStatus = CoarsePaymentStatus(r.PaymentStatus);
    }

    /// <summary>Keeps name, medical notes, date of birth and visit history; drops contact, referral source and tags.</summary>
    public static InstructorClientProfileDto Apply(InstructorClientProfileDto p)
    {
        p.Email = null;
        p.Phone = null;
        p.ReferralSource = null;
        p.Tags = new List<string>();
        p.InfoRestricted = true;
        return p;
    }
}
