using FluentAssertions;
using SoulPilates.Core.DTOs;
using SoulPilates.Services;
using Xunit;

namespace SoulPilates.Tests.Services;

public class InstructorClientRedactionTests
{
    [Fact]
    public void ClassDetail_StripsContactMoneyAndPackageInfo_ButKeepsRosterBasics()
    {
        var detail = new ClassDetailDto
        {
            Attendees =
            {
                new ClassAttendeeDto
                {
                    AttendanceId = "a1", ClientId = "c1", ClientName = "Jane Doe", Status = "ARRIVED", Quantity = 2,
                    ClientPhone = "+84 900", ClientEmail = "jane@x.com", PaymentMethod = "PACKAGE_CREDIT",
                    AmountPaid = 500000m, AmountDueAtStudio = 100m, PromoCode = "WELCOME", PaymentStatus = "package",
                    LinkedInvoiceId = "inv", LinkedInvoiceNumber = "SP-INV-1", IsUnpaid = false, IsNew = true,
                },
                new ClassAttendeeDto { AttendanceId = "a2", ClientId = "c2", ClientName = "Bob", PaymentStatus = "unpaid", IsUnpaid = true },
            },
        };

        InstructorClientRedaction.Apply(detail);

        detail.ClientInfoRestricted.Should().BeTrue();
        var a = detail.Attendees[0];
        a.ClientPhone.Should().BeNull();
        a.ClientEmail.Should().BeNull();
        a.PaymentMethod.Should().BeNull();
        a.AmountPaid.Should().Be(0m);
        a.AmountDueAtStudio.Should().Be(0m);
        a.PromoCode.Should().BeNull();
        a.LinkedInvoiceId.Should().BeNull();
        a.LinkedInvoiceNumber.Should().BeNull();
        a.PaymentStatus.Should().Be("paid", "a package client must not be revealed as a package client");
        a.ClientName.Should().Be("Jane Doe");
        a.Quantity.Should().Be(2);
        a.Status.Should().Be("ARRIVED");
        a.IsNew.Should().BeTrue();
        detail.Attendees[1].PaymentStatus.Should().Be("unpaid");
        detail.Attendees[1].IsUnpaid.Should().BeTrue();
    }

    [Theory]
    [InlineData("package", "paid")]
    [InlineData("PACKAGE", "paid")]
    [InlineData("paid", "paid")]
    [InlineData("unpaid", "unpaid")]
    [InlineData("partial", "partial")]
    [InlineData("free", "free")]
    [InlineData(null, "unpaid")]
    public void CoarsePaymentStatus_OnlyCollapsesPackage(string? input, string expected) =>
        InstructorClientRedaction.CoarsePaymentStatus(input).Should().Be(expected);

    [Fact]
    public void BookingList_StripsPhoneMarketingPaymentAndInvoice()
    {
        var b = new BookingListDto
        {
            ClientName = "Jane", ClientPhone = "123", MarketingSource = "google", PromoCode = "X", PaymentMethod = "STRIPE",
            AmountPaid = 1m, AmountDueAtStudio = 2m, PaymentStatus = "package", LinkedInvoiceId = "i", LinkedInvoiceNumber = "n", Quantity = 2,
        };

        InstructorClientRedaction.Apply(b);

        b.ClientPhone.Should().BeNull();
        b.MarketingSource.Should().BeNull();
        b.PromoCode.Should().BeNull();
        b.PaymentMethod.Should().BeNull();
        b.AmountPaid.Should().Be(0m);
        b.AmountDueAtStudio.Should().Be(0m);
        b.LinkedInvoiceId.Should().BeNull();
        b.LinkedInvoiceNumber.Should().BeNull();
        b.PaymentStatus.Should().Be("paid");
        b.ClientName.Should().Be("Jane");
        b.Quantity.Should().Be(2);
    }

    [Fact]
    public void Roster_StripsPhone_AndHidesPackage()
    {
        var r = new SessionRosterDto { ClientName = "Jane", ClientPhone = "123", PaymentStatus = "package", StillOwes = false };
        InstructorClientRedaction.Apply(r);
        r.ClientPhone.Should().BeNull();
        r.PaymentStatus.Should().Be("paid");
        r.ClientName.Should().Be("Jane");
    }

    [Fact]
    public void Profile_KeepsSafetyInfo_DropsContactReferralAndTags()
    {
        var p = new InstructorClientProfileDto
        {
            ClientId = "c1", Name = "Jane", Email = "j@x.com", Phone = "123", MedicalHistory = "bad knee",
            DateOfBirth = new DateTime(1990, 1, 1), ReferralSource = "Google", Tags = new List<string> { "VIP" },
            TotalVisits = 7, LastVisit = new DateTime(2026, 9, 1), MemberSince = new DateTime(2026, 1, 1),
        };

        var result = InstructorClientRedaction.Apply(p);

        result.Email.Should().BeNull();
        result.Phone.Should().BeNull();
        result.ReferralSource.Should().BeNull();
        result.Tags.Should().BeEmpty();
        result.InfoRestricted.Should().BeTrue();
        result.Name.Should().Be("Jane");
        result.MedicalHistory.Should().Be("bad knee");
        result.DateOfBirth.Should().Be(new DateTime(1990, 1, 1));
        result.TotalVisits.Should().Be(7);
        result.LastVisit.Should().NotBeNull();
        result.MemberSince.Should().NotBeNull();
    }
}
